WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[24481] = { title = "Rockbiter Weapon", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to draw upon the spirits of earth, and imbue your weapon with elemental power.", objectives = "" }
WordHunterWoW_QuestEN[24482] = { title = "Power Word: Fortitude", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to channel the fortitude of An'she, and imbue yourself with great stamina.", objectives = "" }
WordHunterWoW_QuestEN[24483] = { title = "Stormglen", description = "Our carriage drivers were told to regroup in the fishing town of Stormglen.  Our scouts report there might be shelter and supplies to be found there.\n\nMeet Gwen Armstead there, she'll be in charge of taking care of our people.", objectives = "" }
WordHunterWoW_QuestEN[24484] = { title = "Pest Control", description = "Well, what do you know, {name}?  All this time and Stormglen's been left mostly intact.\n\nIt's too bad the Forsaken are still working their way inland, but it'll make a fine place to rest our feet for a night or two.\n\nThe other half of town is overrun with spiders, so I've asked the villagers to stay away from there.\n\nPerhaps you'd like to lend a hand in clearing the spiders out?  I'm certain our injured men and women will sleep more soundly if they know someone's keeping those eight-legged beasts at bay.", objectives = "" }
WordHunterWoW_QuestEN[24485] = { title = "Seal of Righteousness", description = "I am but an apprentice myself, {name}, but I can still impart a lesson to you in thanks.\n\nAllow me to teach you how to fill yourself with the light of An'she, and strike down your enemies with ", objectives = "" }
WordHunterWoW_QuestEN[24486] = { title = "Make Hay While the Sun Shines", description = "The trogg village to the southwest suffered similar damage to ours.  One would assume, logically, that there would be some trogg artifacts sticking out of the ground, too!\n\nUnfortunately, it looks like most of the artifacts have already been scooped up by trogg scavengers.  Please, go see if you can find some way to get them back.  Believe it or not, knowledge about troggs may eventually lead to further knowledge about the mighty dwarves!", objectives = "" }
WordHunterWoW_QuestEN[24487] = { title = "Whitebeard Needs Ye", description = "Ye've done us a great service here, but I'm afraid I've gotta send ye off elsewhere.\n\nGrelin Whitebeard, a good friend of mine, has put in word that he may need some reinforcements near the troll camps to the southwest.  Follow the road westward, ye should find him soon enough.\n\nBe well, {name}.  Troggs may be a pain, but trolls are a whole other type of trouble.", objectives = "" }
WordHunterWoW_QuestEN[24488] = { title = "The Replacements", description = "My guys are all on the injured roster! Our shredders are all kaput! The ref is about to call the game!\n\nIt's down to the wire and I need you, {name}!!!\n\nLet's get one of these shredders in working condition. There are replacement parts all over Bilgewater Port. Any green-blooded Kezanian will gladly let you have them if there's a chance that the Buccaneers will win.\n\nWe'll show those no-good Steamwheedle Sharks how to play footbomb!", objectives = "" }
WordHunterWoW_QuestEN[24489] = { title = "Trolling for Information", description = "I'm notoriously bad at reading troll facial expressions.  That being said, these trolls don't look angry to me.  They seem to be confused... maybe a little frightened.\n\nSomething happened that we're not seeing here, {name}.  I say we do some investigation before we just kill every troll in sight.\n\nThere are three troll camps in the area: one to the southeast, one to the southwest, and one due west.  Each camp has a soothsayer... see if you can get close enough to listen to what they're saying.", objectives = "" }
WordHunterWoW_QuestEN[24490] = { title = "A Trip to Ironforge", description = "The presence of a fire elemental here in Coldridge is no small matter.  That earthquake did more than just upset a bunch of troggs... it changed the world enough to tear a gash into the elemental plane.  We should submit a report to Ironforge.\n\nYou wouldn't be willing to take a trip, would ya?  Don't worry, I've a feeling that you'll do just fine.  Talk to Hands Springsprocket by the tunnel on the eastern edge of the valley.  He'll point you in the right direction.", objectives = "" }
WordHunterWoW_QuestEN[24491] = { title = "Follow that Gyro-Copter!", description = "D-d-did you see that?  How the whole cave just crumbled like that?  I guess it's good that you got here when you did, and not a minute earlier.\n\nWhile this development makes my job of monitoring the cave entrance much easier, I imagine it makes it a lot harder for you to get to Kharanos.\n\nHey wait, I've got an idea!  The Gnomeregan Airmen have a flight path not far from here.  I'll send up a signal, and they should be here to help.  I imagine they'll land back over at Anvilmar.", objectives = "" }
WordHunterWoW_QuestEN[24492] = { title = "Pack Your Bags", description = "The weight limit on my gyro is such that I only have enough room for one {race}.  Looks like you're in luck, {name}!\n\nThat dwarf woman Jona told me that most of your personal belongings have been moved inside Anvilmar.  Please gather what you'll need, finish up any affairs that remain, and return to me when you're prepared for takeoff.", objectives = "" }
WordHunterWoW_QuestEN[24493] = { title = "Don't Forget About Us", description = "You're leaving?  Make sure you stock up before you head out.\n\nMore importantly, please speak to Tharek Blackstone once you arrive in Kharanos.  Tell him what has happened here in Coldridge, and that we could use some assistance.  Hopefully he'll be able to arrange something for us.", objectives = "" }
WordHunterWoW_QuestEN[24495] = { title = "Pieces of the Past", description = "I found a journal by a man named Bradshaw.  Unfortunately it's missing many pages.  Especially towards the end.\n\nIf you find enough of the pages I might be able to piece together what happened here after the Curse broke out.\n\nWho knows... maybe the people in this town found a way out.   Maybe there are still survivors out there.\n\n Maybe my father is still alive.", objectives = "" }
WordHunterWoW_QuestEN[24497] = { title = "Airborne Again", description = "We just got word from Valormok that we can't send anymore windriders that way unless we want them shot down by Talrendis snipers. We can't give up Valormok if we want a secure route to Ashenvale, so we're going in another way.\n\nThe airborne priests have graciously offered to drop some people in for us from above sniper range. Head up to the military area and secure a ride on one of their planes. They'll get you there in one piece, and hopefully once you're there, you can resecure our windrider lines.", objectives = "" }
WordHunterWoW_QuestEN[24498] = { title = "The Path to the Citadel", description = "They've put my captured soldiers to work in the quarry!\n\nKill their captors and set them free, hero. We will need their aid when we confront Scourgelord Tyrannus.", objectives = "" }
WordHunterWoW_QuestEN[24499] = { title = "Echoes of Tortured Souls", description = "We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.", objectives = "" }
WordHunterWoW_QuestEN[24500] = { title = "Wrath of the Lich King", description = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain. but you need to find Jaina and escape the Lich King while there's still time.", objectives = "" }
WordHunterWoW_QuestEN[24501] = { title = "Queen-Sized Troubles", description = "The spiders keep coming in alarming numbers, {name}.  You're going to have to go into their lair and kill the broodmother.\n\nWe've spotted the giant spider known as Rygna at the edge of the Blackwald in an area covered in thick webs.  It'll be dangerous, but we're all counting on you.", objectives = "" }
WordHunterWoW_QuestEN[24502] = { title = "Necessary Roughness", description = "We're down to our last shredder. While no one was looking, I loaded it up with, shall we say, modified footbombs.\n\nKid, I need you to get in that shredder and give 'em heck!", objectives = "" }
WordHunterWoW_QuestEN[24503] = { title = "Fourth and Goal", description = "It's all up to you, kid. You demolished the Steamwheedle Sharks, so now all that's left to do is to kick the winning goal.\n\nNow, just between you and me, I think we should do this one right. I don't want you to just kick a goal... I want you to kick it so far it sails between the two smokestacks behind the goal!\n\nI've modified the footbomb to give you the extra power that you'll need.\n\nMake me proud!", objectives = "" }
WordHunterWoW_QuestEN[24504] = { title = "Clear the High Road", description = "This way, {class}! I see you've discovered the high road.\n\nThe Alliance hopes to sever our ties with Stonetalon, but they forget that we tauren have hunted across these lands for generations. We know every hillside switchback and game trail from here to Thousand Needles.\n\nBut for these paths to stay open, we must stop the humans from mapping them out.\n\nPatrol the trail east and kill any high road scouts you find along the way, then speak to Tunawa Stillwind just up the path.", objectives = "" }
WordHunterWoW_QuestEN[24505] = { title = "Holdout at Hunter's Hill", description = "Honor's Stand may have been lost, but its spirit was never crushed. Even now survivors are holding out at a point called \"Hunter's Hill.\"\n\nContinue following the high road and you will find our camp just up ahead. Speak with Onatay when you get there and let her know the trail is, for the moment, still clear.", objectives = "" }
WordHunterWoW_QuestEN[24506] = { title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy queen, the Lady Sylvanas Windrunner, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find fierce fighters to send her way. I think you'll do.\n\nGo to her within the entrance to the forge, {class}.", objectives = "" }
WordHunterWoW_QuestEN[24507] = { title = "The Path to the Citadel", description = "They've put our captured soldiers to work in the quarry.\n\nKill their captors and set them free, {class}. We will need their aid when we confront Scourgelord Tyrannus.", objectives = "" }
WordHunterWoW_QuestEN[24510] = { title = "Inside the Frozen Citadel", description = "{class}! Come close quickly, I must have a word!\n\nMy patron, the Lady Jaina Proudmoore, has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \"The Forge of Souls.\" She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you.\n\nPlease, find her there as soon as you can.", objectives = "" }
WordHunterWoW_QuestEN[24511] = { title = "Echoes of Tortured Souls", description = "Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up.\n\nClear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel.", objectives = "" }
WordHunterWoW_QuestEN[24512] = { title = "Warriors' Redemption", description = "Those that surrendered when Honor's Stand fell are no longer worthy of our Horde, {class}. But I'm not giving up on them yet. The prison tower below us is lightly guarded. Let's give those prisoners one final chance to die with honor.\n\nI've set up ropes that will allow you to quickly clamber up and down the mountain. Slip down, acquire the confiscated weapons, and re-arm the prisoners inside the tower.\n\nAnd {name}, stay by the tower! We're not yet equipped for an assault on the base proper.", objectives = "" }
WordHunterWoW_QuestEN[24513] = { title = "Eye for an Eye", description = "Who goes there? Your footsteps are not the lazy stride of a guard.\n\nA {class}, you say? Still brave and free? There's no hope for me, friend. I have lost my eyesight and am no longer fit for battle.\n\nI dared speak up while Captain Peake savagely beat one of the prisoners. In return he kicked me in the head. And kept kicking. He kicked me blind, {race}.\n\nYou'll find Captain Peake at the top of this tower. If you seek justice, bring me his eyes.\n\nIf he does not part with them willingly... so be it.", objectives = "" }
WordHunterWoW_QuestEN[24514] = { title = "Raptor Scraps", description = "We are besieged here, {class}, and between that chasm and the harassment of the Alliance we are short on supplies. But we make do with what's at hand, as we tauren always have.\n\nIn the absence of a forge, a skilled leatherworker can strengthen and patch up our damaged armor with good quality hides.\n\nDown below is the hunting ground of the Terrortooth Raptors. They are not so easy to kill, in part due to the ruggedness of their thick skin. Hunt them, {name}, and bring their hides to me!", objectives = "" }
WordHunterWoW_QuestEN[24515] = { title = "Signals in the Sky", description = "Turn your eyes to the southeast. Do you see the campfire smoke from Camp Una'fe?\n\nNot ten minutes ago I saw great puffs of white smoke roll up into the sky from the center of camp. It was an old signal used by my village to coordinate the hunt over great distances, but this time, it was a distress signal.\n\n{name}, my brother Makaba had gone into that unnatural jungle. Please go there and make sure he's not in any trouble.\n\nThere are few paths: look for tents within the wilderness.", objectives = "" }
WordHunterWoW_QuestEN[24517] = { title = "Put the Fear in Them", description = "Do you see the trail below us, {name}? That is MY trail. And if the Alliance dogs choose to use my trail, they'd best be looking over their shoulder.\n\nIt's time to collect my toll! Slay the footsoldiers from Honor's Stand and see if we can't send them scurrying back to their walls.\n\nBe sure to take out at least one of their officers patrolling the road. They need to realize that nobody is safe.", objectives = "" }
WordHunterWoW_QuestEN[24518] = { title = "The Low Road", description = "This bundle of papers was found in a leather satchel hidden under the officer's clothes.\n\nBattle maps of the region depict Honor's Stand, connected to what appears to be a large unfinished roadway crossing the Barrens all the way from Theramore. It looks like the Alliance plans to build a road from the coast straight into the heart of Kalimdor!\n\nKilrok Gorehammer will want to see this.", objectives = "" }
WordHunterWoW_QuestEN[24519] = { title = "Stalling the Survey", description = "These maps have all been drawn by the same steady hand. I've seen a human surveyor heading up and down the road between the hold and the jungle to the east.\n\nWe can set their plans back by making an example out of this surveyor, {name}.\n\n<Kilrok points to the signature at the bottom of the maps.>\n\nWhat do you think that says? \"Zykes?\" Even human names sound thin and weak. Kill him.", objectives = "" }
WordHunterWoW_QuestEN[24520] = { title = "Give Sassy the News", description = "I'd celebrate with you, {name}, but it feels like that dragon did a number on ol' Mount Kajaro. I... uh... I think I'm gonna grab my stuff and get on the first ship leaving the island!\n\nAnyways, you should probably head back to headquarters and let Sassy know that you won the footbomb title for us. I'm sure she'll also want to know about the dragon and Mount Kajaro.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[24522] = { title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing, who will be inspecting the guards there.", objectives = "" }
WordHunterWoW_QuestEN[24523] = { title = "Wildmane Totem", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", objectives = "" }
WordHunterWoW_QuestEN[24524] = { title = "Wildmane Cleansing", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young {name}.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the Grimtotem's poisons!  Let clean water flow once again!", objectives = "" }
WordHunterWoW_QuestEN[24525] = { title = "Keeping the Dogs at Bay", description = "Not everyone who fled Taurajo was able to make it to Una'fe, {name}. Some died of wounds along the way. Others were jumped by opportunistic quilboar.\n\nI'll take care of the grim task of finding and gathering the bodies. But there is something you can do for me.\n\nHecklefang scavengers prowl the lands south of here and are savaging the corpses, tearing at their bowels and dragging away the limbs of the dead. Please, thin their numbers so that I can perform the proper funerary rites.", objectives = "" }
WordHunterWoW_QuestEN[24529] = { title = "Bad to Worse", description = "When the refugees fled north from Taurajo, some were separated as darkness closed in. Many were taken prisoner by the Bristleback quilboar who set up camp west and southwest of here.\n\nI am not certain what the quilboar hoped to get from us by capturing our refugees; all they have earned is my ire. And all they'll get in return is vengeance.\n\nRescue my trapped brothers and sisters, and kill their captors to send a message to the quilboar.", objectives = "" }
WordHunterWoW_QuestEN[24533] = { title = "Words of Power", description = "Now, if ya DO want to become somethin' special, ye'll need to talk to me.  A priest is nothin' without his spells.  And how do you learn new spells?\n\nYa go and get more experience. So go out, get stronger, and then come show me what ya learn.", objectives = "" }
WordHunterWoW_QuestEN[24534] = { title = "Speaking Their Language", description = "The quilboar are attacking because they perceive weakness. Strength is the only language they understand. So we will show them strength.\n\n<Makaba withdraws a large horn from his satchel.>\n\nThis is admittedly crude work but it'll do. Bristleback leaders use horns like these to challenge one another for dominance.\n\n{name}, I want you to challenge the Bristleback champion, Sabersnout, to single combat. Defeat him in front of his followers. Blow the horn at the Bristleback challenge ring due south of here.", objectives = "" }
WordHunterWoW_QuestEN[24535] = { title = "Thalorien Dawnseeker", description = "If you truly bear Quel'Delar, {name}, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", objectives = "" }
WordHunterWoW_QuestEN[24539] = { title = "When Plants Attack", description = "This camp was built at the edge of this jungle, and already it is overwhelmed by plant growth. Something unnatural is happening here!\n\nEarlier I made the mistake of sending some of the healthier refugees out to gather nuts and berries. Those that returned talked about the plant life actually grasping at their legs or even picking them up. I worry about those that haven't come back yet.\n\n{class}, please rescue the refugees trapped in the grasping overgrowth around the camp. ", objectives = "" }
WordHunterWoW_QuestEN[24540] = { title = "War Dance", description = "Some see our people as gentle giants, or noble savages. They have never seen us fight against our own kind...against betrayers from within.\n\nThe Grimtotem were offered mercy in exile, and they have scarred their own home to spite us. They will no longer be tolerated in Mulgore.\n\nI've already sent our warriors ahead to drive them out through Stonetalon Pass, to the north. You have fought bravely against the Grimtotem, {name}; I ask that you join the battle again. Go, and help deal this final blow.", objectives = "" }
WordHunterWoW_QuestEN[24542] = { title = "A Curious Bloom", description = "The great archdruid Naralex recently appeared here in the Barrens. He's either behind this mess or trying to fix it. Either way, you should talk with him before this jungle engulfs the whole world! He's in a small tauren camp to the southeast.\n\nAlong the way, it would be helpful for you to gather plant samples for him to study. The newest flower buds will tell him a great deal about the most recent changes in the jungle.", objectives = "" }
WordHunterWoW_QuestEN[24543] = { title = "A Family Divided", description = "The children you see here were all rescued from Taurajo when the fighting started. I'm trying to track down their parents.\n\nOne of the refugees you rescued from the quilboar recognized the strongest child as belonging to Kirge and Mawre Sternhorn. Moreover, he said Kirge was camped at the Fields of Blood, just north of the Taurajo massacre site.\n\n{name}, please go there and tell Kirge Sternhorn that his child is alive and well!", objectives = "" }
WordHunterWoW_QuestEN[24545] = { title = "The Sacred and the Corrupt", description = "It is against my judgment that I present you this errand, {race}, as it will likely end in your undoing.\n\nIgnore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through.\n\nYou must return to Frostmourne Cavern and recover Light's Vengeance, Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.", objectives = "" }
WordHunterWoW_QuestEN[24546] = { title = "A Line in the Dirt", description = "The Alliance scorches a trail of murder across the Barrens. We must stop them here or there is nothing left for us.\n\nAcross the Fields of Blood there are a number of strategic hills, marked by wooden towers and neutral gray banners. We must take and hold these hills if we hope to slow the Alliance advance!\n\nLook for the towers to the north, east, and south of what's left of Taurajo. Claim a neutral flag and defend the hill against counterattack!", objectives = "" }
WordHunterWoW_QuestEN[24547] = { title = "A Feast of Souls", description = "Shadow's Edge is among the greatest weapons a {class} could hope to obtain.\n\nIs your lust for power sated, {race}?\n\n<You feel Mograine's penetrating gaze.>\n\nI thought not. A final warning then...\n\nYou now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit.\n\nThe weapon you hold is but an empty husk, a mere shadow of what it may become.", objectives = "" }
WordHunterWoW_QuestEN[24548] = { title = "The Splintered Throne", description = "The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit.\n\nWhen Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel.\n\nI shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.", objectives = "" }
WordHunterWoW_QuestEN[24549] = { title = "Shadowmourne...", description = "", objectives = "" }
WordHunterWoW_QuestEN[24550] = { title = "Journey into Thunder Bluff", description = "The wells are cleansed, and Mulgore's waters run sweet and clear once more. You've saved us...but you've also uncovered grim happenings. The actions of the Grimtotem must be made known.\n\nIt is time for you to enter Thunder Bluff, our great city atop the mesa.  Go to our leader, Baine Bloodhoof, son of Cairne. He must hear of this.", objectives = "" }
WordHunterWoW_QuestEN[24551] = { title = "Meet the New Boss", description = "Our defense of the Barrens hasn't gone well under Gar'dul's command, {name}. Garrosh has sent Warlord Bloodhilt here to take control of the situation. He's here in camp, and if you want to make a good impression, you'll demonstrate some initiative.\n\nHead east into the Fields of Blood and seek out Northwatch recon units. Bringing the new Warlord a stack of their merit badges will help you make a name for yourself!", objectives = "" }
WordHunterWoW_QuestEN[24552] = { title = "Lion's Pride", description = "If you seek vengeance on our Alliance invaders, you would do well to observe the fiercest of predators in the Barrens.\n\nThe lions that stalk amongst the tall grass do so with cunning, stealth, and power. Learn from their example and you will understand the kind of war we need to fight.\n\nHunt the plains prowlers and pridemanes, then return to me to discuss what you have learned. You will often find them in the shade of large trees.", objectives = "" }
WordHunterWoW_QuestEN[24553] = { title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", objectives = "" }
WordHunterWoW_QuestEN[24554] = { title = "The Battered Hilt", description = "This battered old sword hilt has seen better days. Before the hilt was snapped from the blade, it must've been a magnificent example of the blacksmith's art.\n\nThe graceful symbols and exotic gemstones decorating the hilt suggest that the weapon may have belonged to a powerful person. Surely, the Sunreavers would be interested in hearing about the recovery of such an artifact. Seek out their representatives at Quel'Delar's Rest, to the south of the Argent Tournament Grounds.", objectives = "" }
WordHunterWoW_QuestEN[24555] = { title = "What The Dragons Know", description = "There's no mistaking it - this hilt comes from a powerful, ancient weapon, but which one? I do not recognize these particular markings, but we haven't hit a dead end yet.\n\nKorialstrasz, better known as Krasus, has long been a friend to the quel'dorei and the Kirin Tor. With his vast knowledge and resources, he's certain to know something. Travel to the top of Wyrmrest Temple and seek his counsel, then report to Magister Hathorel inside Sunreaver's Sanctuary in Dalaran.", objectives = "" }
WordHunterWoW_QuestEN[24556] = { title = "A Suitable Disguise", description = "Getting you inside the Silver Enclave will be tougher than it appears. Only those who possess Silver Covenant tabards are permitted entry to sanctuary. If we can get our hands on one, a simple enchantment will do the rest of the work.\n\nOn the balcony above Threads of Fate, you'll find Shandy Glossgleam. I've helped him a few times in the past, so he owes me a favor. He handles laundry for a wide variety of people in the city. Maybe he can find a way to 'lend' you a tabard for a while.", objectives = "" }
WordHunterWoW_QuestEN[24557] = { title = "The Silver Covenant's Scheme", description = "One of my contacts in the Underbelly caught sight of a Silver Covenant agent gathering information at the Cantrips and Crows Tavern. Silver Covenant members aren't normally found in the sewers, so they must be plotting something.\n\nGo into the Underbelly, find this Silver Covenant agent, and eliminate him. Search the body for any information that might give us a lead on the location of that tome from Wyrmrest. We can't let those simpering Silver Covenant weaklings get it back to Icecrown before we do.", objectives = "" }
WordHunterWoW_QuestEN[24558] = { title = "Return To Myralion Sunblaze", description = "We must get this book to Myralion Sunblade. Would you bring it to him? I cannot rely on anyone else to transport the book and you have proven adept at evading the Silver Covenant's men.\n\nTake it with you to Quel'Delar's Rest, south of the Argent Tournament Grounds in Icecrown. Myralion will be waiting for you. If he can identify that blade, we may be able to claim it in the name of Aethas Sunreaver and show Dalaran and the Alliance that we will lead the charge against the Lich King.", objectives = "" }
WordHunterWoW_QuestEN[24559] = { title = "Reforging The Sword", description = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel.\n\nIn the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar.\n\nYou must gather bars of infused saronite and capture the forgemaster's hammer, then bring them to the forgemaster's anvil and reforge the sword.", objectives = "" }
WordHunterWoW_QuestEN[24560] = { title = "Tempering The Blade", description = "At last, the pieces of Quel'Delar are rejoined and the blade is whole, but it cannot see battle until you have tempered it. That jagged saronite edge is brittle and will shatter the moment it strikes anything.\n\nDeep in Icecrown Citadel's Forge of Souls is a place where the blade can safely be tempered. Take Quel'Delar with you to the abode of the Devourer of Souls and look for the crucible. Plunge the blade into the crucible to temper it and bring it back to me. I'll be waiting in The Frozen Halls.", objectives = "" }
WordHunterWoW_QuestEN[24561] = { title = "The Halls Of Reflection", description = "You have re-forged and tempered the sword, yet it sits quietly in its sheath, little different from a mundane blade. You say the sword pulls you, as though it possesses a will?\n\nDare you bring it where it wishes to go? It is not right that the sword should be this silent and this insistent, yet I fear that if you do not take the sword to its destination, we will never learn why. Bear it with you to Icecrown Citadel's Halls of Reflection, but be on your guard. I will wait for you in The Frozen Halls.", objectives = "" }
WordHunterWoW_QuestEN[24562] = { title = "Journey To The Sunwell", description = "Take Quel'Delar to the Sunwell as quickly as possible, {name}. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas, and there, seek entry to the Sunwell itself, where you can cleanse the sword.\n\nThe guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing, who will be inspecting the guards there.", objectives = "" }
WordHunterWoW_QuestEN[24563] = { title = "Thalorien Dawnseeker", description = "You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword.\n\nIf you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", objectives = "" }
WordHunterWoW_QuestEN[24564] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", objectives = "" }
WordHunterWoW_QuestEN[24565] = { title = "Biological Intervention", description = "The energies unleashed here have surged through the wildlife, twisting them into powerful and unstable forms. If allowed to spread beyond this grove, these deviates will wreak havoc on the existing ecosystem, devouring local prey and driving out the weaker natural creatures.\n\nYou must go and cull the population of the overgrowth. Return when this task is done.", objectives = "" }
WordHunterWoW_QuestEN[24566] = { title = "Sowing a Solution", description = "Based on what you've brought me, I think we may have a solution. I've imbued the lashvine seeds with healing energies.\n\nSimple contact with these should imbue the creatures here with enough energy to force out the corrupted influence.\n\nGo and attempt to heal the mutated raptors and plainstriders by sprinkling the seeds on them, and report the results back to me.", objectives = "" }
WordHunterWoW_QuestEN[24567] = { title = "Report for Tryouts", description = "{name}, Coach Crosscheck is looking for you. He's the leader of our fearless footbomb team, the Bilgewater Buccaneers.\n\nHe says that the division title against the Steamwheedle Sharks is on the line and that you're the only one that can bring it home for us!\n\nHead west into town. You can't miss Kajaro Field.\n\nA footbomb star. This is going to be great for your image!", objectives = "" }
WordHunterWoW_QuestEN[24568] = { title = "To the Walls!", description = "{name}, they're massing at the gates! The Alliance is trying to push their way into Mulgore, using footsoldiers to overwhelm the guards.\n\nWe have so little with which to defend the walls. We've kept pots of water boiling to repel the attackers until help arrives... Those will have to do.\n\nBut we need someone to coordinate our defenses. Say the word and I can give you an eagle-eye view of the battlefield.\n\nWe need you, {name}!", objectives = "" }
WordHunterWoW_QuestEN[24569] = { title = "Siegebreaker", description = "{name}, you've proven yourself on the Fields of Blood. But the Alliance still threatens our tauren friends.\n\nThe siege machinery outside the gates of Mulgore is like a spear aimed at our heart. I want you to go to the gates, south of here, and remove those siege vehicles from play.\n\nHere, use these stickybombs. They're courtesy of our new goblin allies. It looks as though they stuffed explosive powder into ... what looks like ... grease-covered socks. But they'll do.", objectives = "" }
WordHunterWoW_QuestEN[24570] = { title = "Adder Subtraction", description = "The corruption unleashed here must be studied if we're to find a way of properly fighting it.\n\nLuckily, not all the creatures have been as altered as others. The smaller snakes drink little water, and do not eat plants, so their exposure to the energies here has been minimal. They've still absorbed enough to change coloration.\n\nGo collect these snakes from the overgrowth and return them to me, so we can see just what is happening to the creatures here.", objectives = "" }
WordHunterWoW_QuestEN[24571] = { title = "Lashvine Seeds", description = "There's got to be a way to cure these poor creatures without having to take their lives. I have an idea, but I'll need your help, {class}.\n\nThe lashvine plants that roam here hold seeds full of the primal energy of this place. Collect these for me and bring them back, and we'll see if something can be done.", objectives = "" }
WordHunterWoW_QuestEN[24572] = { title = "Taking Back Taurajo", description = "Outstanding work at the gates, {name}! The main body of the Alliance force is in general retreat. But I'm not satisfied.\n\nThey sacked Taurajo, which was little more than a hunters' camp. This 'Alliance' is unmasked at last for what it really is: A renegade band of butchers.\n\nEven now a group of humans linger behind to pick at the bones of smouldering Taurajo.\n\n<Bloodhilt hurls an axe into the dirt.>\n\nMake them suffer.", objectives = "" }
WordHunterWoW_QuestEN[24573] = { title = "Honoring the Dead", description = "With the immediate threat gone, can you help with some grim business?\n\nWe tauren do not bury our dead, we prepare the body for its return to the elements and place it at our sacred grave sites. Those killed in the Taurajo massacre have had no funeral, and I worry misguided Alliance soldiers will burn the bodies of the dead before the proper rites have been performed.\n\n{name}, please take this totem to Taurajo and perform services for Krulmoo, Dranh, Yonada, and Omusa. They ... didn't make it out of there. ", objectives = "" }
WordHunterWoW_QuestEN[24574] = { title = "To Harvest Chaos", description = "If I have truly sown chaos, it is time for reaping.\n\nThe lumbering outgrowths of plant life shamble through the imbued stream here, {name}. They are a direct manifestation of the unstable forces mutating this area. Slay as many as you can, and we might be able to slow the spread of the overgrowth further.\n\nAnd while you're at it...be on the lookout for parts of them that appear especially corrupted. Bring any such pieces to me.", objectives = "" }
WordHunterWoW_QuestEN[24575] = { title = "Liberation Day", description = "We recently found out that the villagers at Emberstone survived most of the ravages of the Curse.\n\nUnfortunately their village wasn't as fortunate when it came to the Forsaken invasion.\n\nThe Forsaken have taken the villagers prisoner and are forcing them to work the nearby mine as slaves.", objectives = "" }
WordHunterWoW_QuestEN[24577] = { title = "Desolation Hold Inspection", description = "Thanks to you, the immediate threat is over. But my work here in the Barrens is only beginning.\n\nHonor's Stand was captured and Taurajo was sacked while Warlord Gar'dul was in charge of the region. The Warchief has sent me here to clean up his mess.\n\nI would like you to ride into Desolation Hold to the south in advance of me and let Gar'dul know that it is time for a reckoning.\n\nTalk to me when you are ready to leave and I will assemble my vanguard to accompany you.", objectives = "" }
WordHunterWoW_QuestEN[24578] = { title = "The Blackwald", description = "It took a while, but I think I've put together what happened here.  At least partially.\n\nThere were survivors of the Curse in this town.  They joined others in the mountains, in Tempest's Reach.\n\nEveryone left, except the man who kept the journal, old man Bradshaw.  He noticed that the worgen attacks had stopped all of a sudden and decided to venture into the Blackwald.\n\nThere is an abandoned mill just northeast of town, it was where Bradshaw lived.  See if you can find any clues there.", objectives = "" }
WordHunterWoW_QuestEN[24579] = { title = "Sartharion Must Die!", description = "Sartharion, the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple.\n\nThe Council of Six has decreed that Sartharion must die!", objectives = "" }
WordHunterWoW_QuestEN[24580] = { title = "Anub'Rekhan Must Die!", description = "Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath.\n\nNow a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad.\n\nThe Council of Six has decreed that Anub'Rekhan must die!", objectives = "" }
WordHunterWoW_QuestEN[24581] = { title = "Noth the Plaguebringer Must Die!", description = "Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged!\n\nMake haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions.\n\nDestroy him! The Council of Six has decreed that Noth must die!", objectives = "" }
WordHunterWoW_QuestEN[24582] = { title = "Instructor Razuvious Must Die!", description = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade.\n\nYou and your group are going to prove everyone wrong.\n\nThe Council of Six has decreed that Razuvious must die!", objectives = "" }
WordHunterWoW_QuestEN[24583] = { title = "Patchwerk Must Die!", description = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight.\n\nI want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct.\n\nThe Council of Six has decreed that Patchwerk must die!", objectives = "" }
WordHunterWoW_QuestEN[24584] = { title = "Malygos Must Die!", description = "Our resources are strained. Malygos, the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity. Without magic, we are doomed.\n\n{class}, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!", objectives = "" }
WordHunterWoW_QuestEN[24585] = { title = "Flame Leviathan Must Die!", description = "Within the Formation Grounds sits Ulduar's first line of defense: Flame Leviathan.\n\nThe Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth.\n\nThis must not come to pass. The Council of Six has decreed that Flame Leviathan must die!", objectives = "" }
WordHunterWoW_QuestEN[24586] = { title = "Razorscale Must Die!", description = "Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar. Of late, however, she has been spotted raining fire down upon lands outside of the titan complex.\n\nThough the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!", objectives = "" }
WordHunterWoW_QuestEN[24587] = { title = "Ignis the Furnace Master Must Die!", description = "The great fire giant, Ignis the Furnace Master toils away inside of Ulduar's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power.\n\nThe Council of Six has decreed that Ignis must die!", objectives = "" }
WordHunterWoW_QuestEN[24588] = { title = "XT-002 Deconstructor Must Die!", description = "Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine!\n\nYou will find the Deconstructor within Ulduar's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!", objectives = "" }
WordHunterWoW_QuestEN[24589] = { title = "Lord Jaraxxus Must Die!", description = "Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader.\n\nYou must be there when it happens, {class}. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more.\n\nThe Council of Six has decreed that Lord Jaraxxus must die!", objectives = "" }
WordHunterWoW_QuestEN[24590] = { title = "Lord Marrowgar Must Die!", description = "Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself.\n\nWithout the destruction of this bone wraith, there is no hope of taking Icecrown Citadel.\n\nThe Council of Six has decreed that Lord Marrowgar must die!", objectives = "" }
WordHunterWoW_QuestEN[24591] = { title = "Changing of the Gar'dul", description = "When Bloodhilt arrives, I'd like to - ah - talk in private. Can you accompany me to make sure things stay on the level? This Bloodhilt is a, ah, he's a, he's a loose cannon.\n\n<Gar'dul tries to compose himself.>\n\nMeet me atop the northern tower and we'll talk with Bloodhilt together.", objectives = "" }
WordHunterWoW_QuestEN[24592] = { title = "Betrayal at Tempest's Reach", description = "King Greymane has been taken prisoner by Lord Godfrey in Tempest's Reach!\n\nHe managed to convince two of the eastern lords to go with his plan.  The fool seems to think he can strike a deal with the Forsaken by turning Greymane over to them.\n\nListen carefully, {name}.  We need to resolve this with as little bloodshed as possible.\n\nThis potion will allow you to sneak in undetected.  We need you to assassinate the traitorous lords before this gets out of hand!", objectives = "" }
WordHunterWoW_QuestEN[24593] = { title = "Neither Human Nor Beast", description = "It is time, {name}.  This... alchemy that has kept the beast inside you at bay will not last for long.\n\nThe first cursed worgen were night elf druids like our new allies.  They, however, abandoned the balance that the rest of their kind embraced and allowed the beast to take over their minds.\n\nIt is only fitting that their brethren be the ones that deliver us from the Curse.  Go, {class}.  Drink from the waters of Tal'doren and make peace with yourself.", objectives = "" }
WordHunterWoW_QuestEN[24594] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.", objectives = "" }
WordHunterWoW_QuestEN[24595] = { title = "The Purification of Quel'Delar", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", objectives = "" }
WordHunterWoW_QuestEN[24596] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", objectives = "" }
WordHunterWoW_QuestEN[24598] = { title = "The Purification of Quel'Delar", description = "The Sunwell and the end of Quel'Delar's exile await, {name}.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", objectives = "" }
WordHunterWoW_QuestEN[24601] = { title = "The Nightmare Scar", description = "This confirms it. The overgrowth here is not being caused by a mere overabundance of energy.\n\nDo you understand? This is beyond what happened at the Wailing Caverns now. A rift into the Nightmare must have torn open in the middle of the very land we're standing on! And to think it's my fault...\n\nI'm done picking at the edges of this wound. Go to the west, to the center of the overgrowth, and meet me again there. We will dive into the heart of this corruption and force it shut!", objectives = "" }
WordHunterWoW_QuestEN[24602] = { title = "Laid to Rest", description = "In our hurried escape for safety, we disturbed the resting homes of our ancestors, {name}.  A grave sin, if you'll pardon the pun.\n\nIt is tradition that a small memento be buried on top of a Gilnean's graveyard, beneath the shallow earth.  The stampede of people fleeing these tunnels has unearthed these mementos and angered the spirits.\n\nFind them and bring them to me.  We'll see to it that the dead return to their eternal slumber.", objectives = "" }
WordHunterWoW_QuestEN[24603] = { title = "Don't Stop Bereavin'", description = "For a moment, I thought my hatred had stilled. My wife laid to rest, a final offering of the blood of her murderers to quell her tortured spirit. I thought perhaps peace would appeal to me.\n\nI was wrong.\n\nI will not rest now until every single filthy, squealing, murderous quilboar lays dead and broken! I cannot kill them fast enough with my own two hands.  Go and slay more for me, {race}.", objectives = "" }
WordHunterWoW_QuestEN[24604] = { title = "Concern for Mankrik", description = "I would ask a favor of you, {class}.\n\nA warrior named Mankrik passed through our camp not long ago, on a lonely journey. His wife was killed by the quilboar, long ago, and he still seeks revenge. I cannot forget his eyes...burning with inconsolable hatred, every waking moment.\n\nWe did not talk long, but I cannot bear to think of him out there alone. Please, bring this to Mankrik, and tell him it is from me... ", objectives = "" }
WordHunterWoW_QuestEN[24606] = { title = "Blood of the Barrens", description = "This bright red stone, found clutched in the grasp of a quilboar, has been carefully carved into the likeness of a great boar, with thorny vines sprouting from its back. Its surface is smooth and worn with care.\n\nDid the quilboar make this? If you find others, maybe one of the shaman at Firestone Point could tell you more about them.", objectives = "" }
WordHunterWoW_QuestEN[24607] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Nortet to the east.", objectives = "" }
WordHunterWoW_QuestEN[24608] = { title = "Mangletooth", description = "I no longer care for honor or glory, {class}. All that matters to me is that the quilboar die, by any means, at anyone's hand.\n\nMangletooth, the chief of these filthy Razormane, sits in his lair to the northwest, atop a hill. End his life.\n\nI plan to stay here, and pile these bodies until no more vermin run squealing from the Kraul to face me...", objectives = "" }
WordHunterWoW_QuestEN[24616] = { title = "Losing Your Tail", description = "You must have many questions, {name}.  And they will be answered in time.\n\nI know why you're here and what you're looking for.\n\nI can't lead you there with the enemy tracking you.\n\nOne of Sylvanas's scouts has been following your tracks.  You can't lead the Forsaken to the place you seek.  Take this talisman and walk along the road just north of here.\n\nLet the ranger lure you to her trap and use the power of the talisman to break free and counterattack.", objectives = "" }
WordHunterWoW_QuestEN[24617] = { title = "Tal'doren, the Wild Home", description = "There are others like you, {name}.  And they too, were lost and confused.\n\nThere is a place where you belong.\n\nTal'doren, the wild home, was once home to an order of druids who took the shape of wolves.\n\nIt is there that you will find the answers you seek.  It is also there that you will find someone who can offer guidance.  An old friend.", objectives = "" }
WordHunterWoW_QuestEN[24618] = { title = "Claim the Battle Scar", description = "We have fought the Alliance to a standstill here, even as the land beneath our feet falls apart. To the east you will find the Battlescar, a wide swath of decimated terrain. It is little more than a line in the sand, but it must be OUR line.\n\nIn the center of the scar you will find a flag marker designating who controls it. Scout out the flag.\n\nIf it's not already ours, capture it for the Horde - it will swing the battle in our favor. Investigate the scar and kill anyone you find in there!", objectives = "" }
WordHunterWoW_QuestEN[24619] = { title = "Parts-is-Parts", description = "I've always wanted to try making an abomination. It looks simple enough, but you know how it is when you learn things from a book. There's no substitute for doing!\n\nFirst, I'm going to need parts. Lots of parts. And you're going to get them for me.\n\nNo need to be picky: human, orc... it doesn't matter. Parts is parts.\n\nJust be sure the corpses you harvest come from the Battlescar, so I know they're fresh.\n\n<Calder presses a rusted, gore-covered bonesaw into your hands and smiles disarmingly.> ", objectives = "" }
WordHunterWoW_QuestEN[24620] = { title = "Hearts-is-Hearts", description = "These parts - so lovely! Muscle and sinew and fingers and toes ... I am SO hungry right now.\n\nBut work must come first. Once I stitch this pile of parts together I'm going to need a heart strong enough to pump sludge through this rat's nest of veins. I would use my own heart, but it's a shriveled up husk resembling a turnip.\n\nNo, I need some real power. Get me a kodo heart from one of those giant landquaker bulls to the south of the Battlescar.", objectives = "" }
WordHunterWoW_QuestEN[24621] = { title = "Smarts-is-Smarts", description = "My monstrosity is taking shape! All that's left is to stuff his skull with something useful.\n\nI'm talking about brains, {name}. And here I'm going to be picky. The abomification process causes significant brain damage so it's best to start with someone smart.\n\nOne of the Alliance officers should do nicely. Seek out one of the Captains on the far side of the Battlescar and try not to damage the goods while you kill him.", objectives = "" }
WordHunterWoW_QuestEN[24622] = { title = "A Troll's Truest Companion", description = "If ya lookin' for something ta do, we need some more raptors moved over to da pens. If ya head over to da island south of here, you can be meetin' with our caretakers and dey can set ya up.\n\nDey might appreciate a hand too. Got ta be spreadin' da love, ya know?", objectives = "" }
WordHunterWoW_QuestEN[24623] = { title = "Saving the Young", description = "I actually have somethin' really important dat I could use help with, if ya be willin', mon.\n\nOur hatchlins' are bein' stolen by someone on da next island. At first I thought dey were just runnin' away or that nature be claimin' dem, but we are missin' more than a dozen of da little guys now.\n\nPlease head to Zalazane's Fall to da northwest and point da little hatchlins back dis way. Poor tings.", objectives = "" }
WordHunterWoW_QuestEN[24624] = { title = "Mercy for the Lost", description = "The fiend who stole our raptors has been corruptin' dem with some kind of magic. Now dat dey've grown with dis corruption inside of them, I fear dere's little we can be doin' to save dem outside grantin' them da peace of death. Go ta Zalazane's Fall, northwest of here, an' see da task done.\n\nI hope ya can stomach dae work. I don't tink I could bring myself ta do da deed, even knowin' that it be needed.", objectives = "" }
WordHunterWoW_QuestEN[24625] = { title = "Consort of the Sea Witch", description = "I been investigatin' our corrupted Bloodtalons troubles and I think I've found da source. A lone naga. He was holdin' a red orb aloft over our hatchlings and I could see dem... changin'.\n\nI'm certain he tinks his thievery and spellcastin' have gone unnoticed, so ya should be able ta catch him unawares. Kill dis naga and bring me back dat vile orb - you'll be findin' him to da northwest, at Zalazane's Fall.", objectives = "" }
WordHunterWoW_QuestEN[24626] = { title = "Young and Vicious", description = "Ya be a good one, {name}.\n\nMoraya was askin' for new raptors ta train. We shouldn't keep her waitin' any longa! I have a few other recruits bringin' some over as well, but I have a special one dat I've been promisin' Moraya for a while.\n\nSwiftclaw be one of our fastest and bravest young raptors yet, but he can be a bit unruly. I'll lend ya da lasso, I just need ya to catch him somewhere on da island here and steer him over to da pens on da main isle. I doubt he'll be makin' it easy on ya though.", objectives = "" }
WordHunterWoW_QuestEN[24627] = { title = "At Our Doorstep", description = "The night elves have taught us much during this time, {name}.  They've taught us who we are and where we come from.\n\nThanks to them... thanks to this place... we're no longer mere beasts.  We have regained free will.\n\nThe Forsaken aren't here for our land alone.\n\nThey're looking for something we possess.  An artifact capable of uncontrollably spreading the Curse to all humanity.  We cannot let them find it.\n\nSylvanas's banshees have come very close.  Help my trackers take them out.", objectives = "" }
WordHunterWoW_QuestEN[24628] = { title = "Preparations", description = "What you know as the Curse began as a heresy among our brethren.\n\nFaced with a losing battle against demonic forces, the Druids of the Pack eschewed the balance they were sworn to and allowed the beast to overtake them.\n\nThey were banished to the Emerald Dream where they live in eternal slumber under a tree identical to this one, but not before their curse spread to others.\n\nToday our ceremony will restore balance to your people. Bring me the leaf that grows only in Tal'doren's vicinity.", objectives = "" }
WordHunterWoW_QuestEN[24631] = { title = "Flightmare", description = "The Alliance has hired in Wildhammer mercenaries to control the skies over the Battlescar. I believe these same gryphon-riders were the ones to firebomb Taurajo during the attack.\n\nI want our skies scoured clean.\n\nThe wildhammer dwarves fly low enough for a sharp-eyed {class} to hook them. Take this. Target their gryphons and dismount the riders - once grounded, show them no mercy.", objectives = "" }
WordHunterWoW_QuestEN[24632] = { title = "Tauren Vengeance", description = "My people are not wrathful by nature, but sometimes a thirst for justice causes us to take up arms in anger.\n\nMy old friend Gann Stonespire, on learning of the butchery in Taurajo, flew into a fury. Tribal elders could no longer hold his rage in check.\n\nNow he has all but parted ways with the Horde. He's gone rogue, {name}, and seeks to lash out at the Alliance with a small band of like-minded partisans.\n\nIf you, too, seek vengeance, you will find him southeast of here, at the foot of Bael Modan.", objectives = "" }
WordHunterWoW_QuestEN[24633] = { title = "Mahka's Plea", description = "I can't put him out of my mind, {name}. Sometimes at night, I can hear his howls of rage and suffering, echoing across the plains. To imagine him out there, alone and in such pain...\n\nPlease, I must ask a favor of you. Go to Mankrik, and tell him to come see me.", objectives = "" }
WordHunterWoW_QuestEN[24634] = { title = "Intelligence Warfare", description = "I am convinced the Alliance is using spies to scout the field and pass along information. They knew to strike at Taurajo while the hunters were afield. And they countered every one of Gar'dul's moves like he was an open book.\n\nWell {name}, I for one will not be outplayed. Not here. We will win the battle for intelligence.\n\nEven now I hear reports of Alliance operatives slinking around in the shadows, especially here, outside these very walls. Kill them and bring me back something of use.", objectives = "" }
WordHunterWoW_QuestEN[24637] = { title = "The Butcher of Taurajo", description = "This operative had orders to secure the roadways between the Alliance command and Fort Triumph. General Hawthorne is on the move.\n\n<Bloodhilt crumples the documents in his fist.>\n\nIt's HIM, {name}! Hawthorne - I spit the name - he is the one who ordered the assault on Taurajo! Now we know when and where to strike him down. Quickly, follow the road north of the Battlescar and meet up with my assassin Karthog. CRUSH Hawthorne and string his body up along the road!", objectives = "" }
WordHunterWoW_QuestEN[24639] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start with da basics. I need ta know dat you know how ta swing dat weapon you're totin' around.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch ya fighting form and we'll go from dere.", objectives = "" }
WordHunterWoW_QuestEN[24641] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "" }
WordHunterWoW_QuestEN[24642] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "" }
WordHunterWoW_QuestEN[24643] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "" }
WordHunterWoW_QuestEN[24646] = { title = "Take Back What's Ours", description = "Ever since the Forsaken invaded Gilneas, we've tried to keep the location of the Scythe of Elune secret.   We moved it at night to one of many safe locations.  The Dark Rangers got close, but never found it... until now.\n\nThey were last spotted at the Woods' End Cabin, west of here.  Blow this horn when you find them and Tobias and his trackers will engage the Dark Rangers.\n\nOnly then will it be safe for you to venture inside the cabin and take back the scythe.  Hurry, {name}.  It must not reach Sylvanas.", objectives = "" }
WordHunterWoW_QuestEN[24653] = { title = "Echoes of Agamaggan", description = "I think the quilboar are being driven by more than just crude desire. Would you help me look into this further?\n\nTo the west, scattered among the quilboar's settlements and camps, I've noticed boar skulls. They gleam from a distance, polished smooth...distinct from the remains littered in their waste piles. I think these may be objects of worship.\n\nBring me several of these to examine, {name}.", objectives = "" }
WordHunterWoW_QuestEN[24654] = { title = "Silithissues", description = "The silithid! They're bugs, {name}. Or something like bugs. They're not natural... and we built a fortress on the equivalent of an anthill.\n\nTake this burning pitch. It'll set the buggers on fire and plug up their burrows at the same time. Be careful when you pour this stuff on there - the silithid will come out in swarms!\n\nLook for silithid mounds around the exterior of Desolation Hold. They look like heaps of sand. Kill anything that crawls out.", objectives = "" }
WordHunterWoW_QuestEN[24667] = { title = "Firestone Point", description = "I've been on top of this silithid situation for almost a month, which makes me the local expert. Just last week the Earthen Ring was visiting, and wanted me to write down everything I know.\n\n<Crawgol hands you a tattered book.>\n\nI'm not much of a writer. Or a reader, for that matter. But this book is probably the most definitive thing ever written about this foe.\n\nDeliver it to Tauna Skychaser down in Firestone Point. It's south of here, just west of the main road.", objectives = "" }
WordHunterWoW_QuestEN[24671] = { title = "Cluster Cluck", description = "Ridiculous! The greatest goblin mind of all time reduced to food detail? I made the Micro Mechachicken just for this reason and they let it get away!\n\n<Hobart turns a deeper shade of green as his blood pressure rises.>\n\nDo I look like I should be rounding up escaped cluckers? No, my friend, not I! Bamm most definitely, though he's too lazy.\n\nYour station in life has recently taken a turn for the worse. You do it!\n\nTake these remote control fireworks and attach them to the cluckers.", objectives = "" }
WordHunterWoW_QuestEN[24672] = { title = "Onwards and Upwards", description = "I will do as Darius asked and have our people move through the Blackwald.\n\nYou ought to catch up with King Greymane.  He and Krennan went into Tempest's Reach after Lord Godfrey confirmed survivors had made their dwelling there.\n\nFollow the road out of Stormglen into the mountains.  I asked Krennan to wait for you at the bridge before Tempest's Reach.", objectives = "" }
WordHunterWoW_QuestEN[24673] = { title = "Return to Stormglen", description = "It'll be a long time before our nation comes together again.  The old political divisions pale in comparison to what divides us now.\n\nYet if there was ever a time for us to come together and unite against a common enemy, it is now.  And it is you, {name}, who have proven able to bridge the gap between our people.\n\nReturn to Stormglen and tell them it is safe to go through the Blackwald on their way to Tempest's Reach.  We will take care of any Forsaken who follow them.", objectives = "" }
WordHunterWoW_QuestEN[24674] = { title = "Slaves to No One", description = "I was one of the few that escaped, {name}.  When the Forsaken took over our town and our mine, they treated us with utmost cruelty.\n\nThose of us who were weak and could not endure hard labor were worked to death by the abomination known as Brothogg.\n\nMy wife was among his victims, {class}, and I swore that one day her death would be avenged.  I am too frail now, but you can deliver justice... for my wife... for Gilneas!", objectives = "" }
WordHunterWoW_QuestEN[24675] = { title = "Last Meal", description = "I'm not dumb, {name}.  I know what's ahead of us.\n\nOur people are going to go through those gates and fight against an enemy that is better trained, has more numbers and better weapons than us.\n\nEven if we succeed, it'll be at a great cost.  For most of us, today's meal will be the last.\n\nI cannot fight, but I sure can cook.  Bring me meat from the stags that roam this area and I will ensure that the last meal these folks get will be their best.", objectives = "" }
WordHunterWoW_QuestEN[24676] = { title = "Push Them Out", description = "The people are free, but the town is still occupied by the Forsaken.  They're cut off from their main force, so if we're to drive them out, now's our chance.\n\nTheir leader, Executor Cornell, is known  for his unbound ruthlessness.  Also among them is Valnov the Mad, a so-called scientist who carries out inhuman experiments on villagers too old to work the mines.\n\nTake care of them all.", objectives = "" }
WordHunterWoW_QuestEN[24677] = { title = "Flank the Forsaken", description = "I thank you, {name}.  We can't rest on our laurels, however.\n\nWe found out about a mining town, currently under Forsaken occupation.  We sent some of my men, along with Crowley's daughter to the nearby livery stables to begin operations there.  Liam should be joining them shortly.\n\nI'll stay here and organize the final push for Gilneas City.  Speak to Lord Hewell to secure a horse to get you there.", objectives = "" }
WordHunterWoW_QuestEN[24678] = { title = "Knee-Deep", description = "It's time to pack it in, {name}.  Most of our people have made it through -- it's your turn now.\n\nTake this torch, you're going to need it.  The tunnel is full of nasty, knee-biting critters of the worst kind.  Use it to keep them at bay.\n\nSpeak to Krennan on the other side.", objectives = "" }
WordHunterWoW_QuestEN[24679] = { title = "Patriarch's Blessing", description = "You've done it, {name}.  Even in these times we must honor our dead.\n\nTake these offerings and place them at Aderic's tomb.\n\nLet's hope that's enough to placate the ghosts of our ancestors.", objectives = "" }
WordHunterWoW_QuestEN[24680] = { title = "Keel Harbor", description = "We might've lost our city, but at least it looks like the dead have forgiven us.\n\nMeet with the rest of the survivors in Keel Harbor.\n\nI'm sure there's plenty to do before we're in the clear.  Genn hasn't arrived yet, so I suppose Lord Crowley will be in charge there.", objectives = "" }
WordHunterWoW_QuestEN[24681] = { title = "They Have Allies, But So Do We", description = "The night elves made good on their promise.  They've brought ships and are ready to offer us sanctuary in their lands.\n\nUnfortunately, the Forsaken's allies have arrived as well.\n\nThe orcs are advancing upon us while the Horde gunship prevents the transport ships from taking our people to safety.\n\nThe druids are holding the enemy back, but won't last long.  Fortunately, the elven ships were carrying siege weapons.  Take one of the glaive throwers and meet the enemy head on.", objectives = "" }
WordHunterWoW_QuestEN[24682] = { title = "The Pit of Saron", description = "Quickly, through the portal! I'll find you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[24683] = { title = "The Pit of Saron", description = "Quickly, through the portal! I'll meet you on the other side.", objectives = "" }
WordHunterWoW_QuestEN[24684] = { title = "A Weezil in the Henhouse", description = "<Gann grasps you with a blood-caked hand.>\n\nMy wounds are great but I will not rest until the dwarves of Bael Modan pay for their crimes. <Wheeze> We smuggled a man inside their fortress during our last raid. A goblin saboteur: Weezil Slipshadow. \n\nCreate a disruption at the gates - kill who you can - then slip inside the fortress of Bael'dun to the south and find Weezil.\n\nThat stronghold <cough> can only be destroyed from within, and Weezil can't do it alone.", objectives = "" }
WordHunterWoW_QuestEN[24685] = { title = "Dwarf Fortress", description = "I don't know if you noticed on your way in, but this whole fortress is erected around a giant cannon. If we can just find the ammunition magazine, we could blow this place sky-high as easy as kiss-my-hand!\n\nBut to figure it out I'm going to need the fortress schematics, and I haven't been able to steal them yet.\n\nLook for the plans on the lowest floor, right down these stairs.", objectives = "" }
WordHunterWoW_QuestEN[24686] = { title = "Carried on the Waves", description = "The Bloodpetals of Un'Goro have a fascinating life cycle.\n\nThese trees in front of us bear seeds that fall down into the river when they mature.  The river's current then takes the seed north of here, where the seed hatches - almost like an egg - and a newborn Bloodpetal emerges.\n\nI require these seeds for my studies.  Take this net, and use it to scoop up the bright orange seeds in the river.  You'll have to hunt them down under the water.", objectives = "" }
WordHunterWoW_QuestEN[24687] = { title = "Bouquets of Death", description = "You're already familiar with the first phase of the Bloodpetals' life cycle: the waterborne seed.  The next phase, however, is not so docile: the pack of juveniles.\n\nWhen Bloodpetals hatch, they quickly form gangs and travel together, offsetting their weakness with overwhelming numbers.  These packs of young lashers normally keep to themselves, but upset one of them and you upset them all.\n\nFor our safety and the safety of others, dispose of them.  They roam close by, to the west and north.", objectives = "" }
WordHunterWoW_QuestEN[24688] = { title = "Zen'Aliri", description = "You've already met one of my new students, the young worgen named Garl.  My other student is a troll by the name of Zen'Aliri.  He currently camps with the explorers of Marshal's Expedition, to the west of here.\n\nTake these results to him, {name}, and tell him to read them well.", objectives = "" }
WordHunterWoW_QuestEN[24689] = { title = "Flowing to the North", description = "Ithis Moonwarden is the night elf druid who indoctrinated me into the Cenarion Circle.  He has set up camp north of here, near the cliffs of the crater's easternmost edge.  Follow the flow of the Bloodpetal seeds, and I'll wager you'll find him nearby.\n\nMy studies are limited only to seeds and other reagents, but he pursues more advanced matters.  If you are curious to learn more about Un'Goro's flora, you should speak with him now.", objectives = "" }
WordHunterWoW_QuestEN[24690] = { title = "Blazerunner", description = "I'm still a bit concerned about these fire elementals, {name}.  One last request: head to the top of Fire Plume Ridge, and kill the one they call Blazerunner.  He's the biggest and strongest of all the fire elementals in the crater.  With him gone, I'll be able to sleep much better.", objectives = "" }
WordHunterWoW_QuestEN[24691] = { title = "Peculiar Delicacies", description = "Hey bub, interested in making an extra dime?\n\nI've got it on good authority that some interested parties are paying BIG money for silithid legs.  Yes, you heard me right, silithid legs!  Apparently these things are delicious if you cook them right.  They're like underground lobsters, and they live just south of here.\n\nThing is, I'll need a good amount of them to pay for my overhead.  Think you could get me 8 dozen or so?", objectives = "" }
WordHunterWoW_QuestEN[24692] = { title = "The Fledgling Colossus", description = "If you're here to help, then maybe you can help us with a lurking threat.\n\nTo the south lies the Slithering Scar, a quivering silithid outpost in the middle of the jungle.  You can't miss it.\n\nOne of my scouts reports that the silithid are harboring a young colossus in their large central underground chamber, and once it is fully grown, they plan to unleash it upon Un'Goro!\n\nThis must not be allowed to pass, {name}.  Find the colossus and kill it.", objectives = "" }
WordHunterWoW_QuestEN[24693] = { title = "Mossy Pile", description = "Here in Marshal's Stand, I can't really do too much profiteering without arousing suspicion from the scientists.  There is, however, another place where I might have use of you.\n\nMy business associate, Gremix, has a camp northwest of here, on the opposite side of the volcano.  He's a savvy business mind, and has a better eye for profit than even I do.  I'm sure he could put you to work, if you'd like to make some more coin.", objectives = "" }
WordHunterWoW_QuestEN[24694] = { title = "The Shaper's Terrace", description = "<As you look into the orb in front of you, you hear a voice.>\n\nThe crystal pylons have been activated.  A sufficient number of crystals have been gathered.  The prerequisites have been met.  We are prepared for teleport to The Shaper's Terrace.\n\nSpeak to me when you are ready, {race}.  We will consult with The Watcher.", objectives = "" }
WordHunterWoW_QuestEN[24695] = { title = "Ever Watching From Above", description = "When my master Khaz'Goroth shaped the world you call Azeroth, he designed Un'Goro Crater to be an area for experimentation.  You might call it the Titans' petri dish.\n\nIf you seek further knowledge about the methods in which we observe the world, pull the four levers behind me and complete my tests.", objectives = "" }
WordHunterWoW_QuestEN[24697] = { title = "How to Make Meat Fresh Again", description = "I don't believe we've met... I'm Nolen Tacker, Marshal Expeditions' new chief of the guards.  I'm also their chef.  There's actually more overlap than you'd think.\n\nI've got a fun little task for you.  Have you seen the spike pits around the perimeter of the camp?  See if you can convince some of the nearby dinosaurs to walk into them.  If you throw this rotten meat at them when they're not looking, it'll either make them hungry or angry.  Either way is fine, as long as they follow you into the pit!", objectives = "" }
WordHunterWoW_QuestEN[24698] = { title = "Adventures in Archaeology", description = "Hey, you want to try my new diemetradon dogs?  No?  Raptor risotto?  Pterrordax ptacos?\n\nFine.  Oh, I just remembered!  I have a friend nearby that might be able to use your assistance.  His name is Spark Nilminer, and he's Marshal Expeditions' chief archaeology officer.\n\nHe's been sent out to Golakka Hot Springs, to the west.  You'll likely find him on the springs' western shore.", objectives = "" }
WordHunterWoW_QuestEN[24699] = { title = "Gormashh the Glutinous", description = "Hey, I know!  We've been looking at the wrong tar creatures.\n\nGremix once told me about a larger-than-normal tar creature that he ran into.  It lurks around the tar pit far to the east of here, south of Fungal Rock.  I'll bet that the bigger these creatures get, the stickier they get!  We'll make some money yet, {name}!\n\nDon't forget the scraper!", objectives = "" }
WordHunterWoW_QuestEN[24700] = { title = "Hard to Harvest", description = "The Lakkari Tar Pits, just north of here, conceal a hidden treasure: rare flowers that grow at the bottom of the pits.  These tarblossoms, as they're called, are valued for their beauty and their durability.  It's been a while since I last harvested tarblossoms, so there should be some new plants growing at the bottom of the pits.  Grab some for me?\n\nBy the way, good luck swimming in tar.  It's nothing like swimming in water.", objectives = "" }
WordHunterWoW_QuestEN[24701] = { title = "Marshal's Refuse", description = "A big part of making money is shamelessness.  You have to be willing to profit off of the misfortune of others.  It all ends up boiling down to one question: How much do you love money?\n\nWhen Marshal and his crew abandoned their refuge up to the north, they left behind lots of supplies.  This stuff isn't rare, or even particularly valuable, but it's there if you're willing to take it.  His camp is up in the cliffs, to the north.\n\nOh, and be on the lookout for whatever it was that made them leave...", objectives = "" }
WordHunterWoW_QuestEN[24703] = { title = "An Important Lesson", description = "What ho, traveler!  You must know that you set foot upon the camp of Maximillian of Northshire!  Mayhap you have heard tales sung of my many exploits?  I can see from the look in your eye that you have.  That glint of recognition plays upon your visage like the White Lady's reflection o'er Stonecairne Lake.\n\nIt is clear to me that you seek adventure.  As you seem able enough, and thoroughly well-intentioned, I would offer to make you my squire.", objectives = "" }
WordHunterWoW_QuestEN[24704] = { title = "The Evil Dragons of Un'Goro Crater", description = "This crater is filled with a malignant breed of dragon.  Have you seen them?  They wander all about, parading their spiky backs and lizardy faces all around the Crater.\n\nDon't let them fool you, squire, for these dragons are no minions of graceful Alexstrasza.  They are clearly vicious, and direly in need of a hero's blade.\n\nI have decided that I will slay no less than 15 of them.  As my squire, you must come along.  Should we become separated, you may meet me back here at the Hot Springs.", objectives = "" }
WordHunterWoW_QuestEN[24705] = { title = "Town Dwellers Were Made to be Saved", description = "I've a feeling that we may find more than dragons here in this crater.  My paladin's instinct tells me that there are townsfolk nearby that require our aid. Those in distress cannot be ignored.\n\nLet us sally forth, Squire {name}!  The people of Un'Goro require our aid!", objectives = "" }
WordHunterWoW_QuestEN[24706] = { title = "The Spirits of Golakka Hot Springs", description = "A moment of seriousness now, {name}.  We have an important quest ahead of us.  The treacherous dragons that plague this valley will not cease their mischief until we destroy their repugnant brood mother.  Before we even attempt to complete such a task, we must ask the Light for aid.\n\nI have seen the Light manifest itself nearby, in the form of Spirits floating by the shores of Golakka Hot Springs.  Come, I must speak with them, and ask them for aid.", objectives = "" }
WordHunterWoW_QuestEN[24707] = { title = "The Ballad of Maximillian", description = "The time we have waited for is upon us, Squire {name}.  Un'Goro's brood mother will perish at my hands.  The gravity of our task weighs heavily on me, but with the power of the Light behind us, we are guaranteed to succeed.\n\nAre you ready to depart?", objectives = "" }
WordHunterWoW_QuestEN[24708] = { title = "The Fossil-Finder 3000", description = "One of the things I hate the most about digging is the fact that half the time, all you find is dirt.  That's why I've been spending most of my time out here tinkering instead of digging.\n\nLet me show you what I've invented: the Fossil-Finder 3000.  I just put the finishing touches on it.  If it works properly, it should find the largest fossils in the area.  I know, sweet, huh?\n\nTest it out and see if you can find some ridiculously big dinosaur bones.", objectives = "" }
WordHunterWoW_QuestEN[24709] = { title = "A Tale of Two Shovels", description = "Hey wait a minute, this bone has pickax marks on it.  These aren't yours, are they?  No, I recognize this mark... this must be that blasted dwarf!  Gah!\n\nLet me step back for a minute and explain.  There's another archaeologist south of here named Durrin Direshovel.  He practices a reckless, devil-may-care brand of archaeology that offends even me.\n\nA priceless fossil, ruined by sloppy pick-work.  This is the last straw, Durrin!\n\n{name}, go put an end to Direshovel and his negligent excavation.", objectives = "" }
WordHunterWoW_QuestEN[24710] = { title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nHe will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", objectives = "" }
WordHunterWoW_QuestEN[24711] = { title = "Frostmourne", description = "We've come so far... we're so close to our goal.\n\nI'm uncertain how we're going to escape with so many men lost and so few to keep our path secure, but we must press on.", objectives = "" }
WordHunterWoW_QuestEN[24712] = { title = "Deliverance from the Pit", description = "We need to make our way up the main path and through the cave to Tyrannus' rise.\n\nThere, he will be forced to confront us there lest we make our way into the citadel proper.\n\nGo now, {class}. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", objectives = "" }
WordHunterWoW_QuestEN[24713] = { title = "Frostmourne", description = "You must press on, hero. We've come so far... we're so close to our goal. For now, I must stay here and secure a path for your exit.\n\nFind Sylvanas and continue the mission.", objectives = "" }
WordHunterWoW_QuestEN[24714] = { title = "Chasing A-Me 01", description = "Unfortunately, something's happened to one of my greatest inventions.  You've seen mechanical squirrels, yes?  Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has been studying the local wildlife at Fungal Rock for several months, but she should have returned by now.  I fear the worst for her.\n\nCan you help me find her?", objectives = "" }
WordHunterWoW_QuestEN[24715] = { title = "Repairing A-Me 01", description = "<Suddenly, the robotic gorilla's eyes light up, and it begins to speak.>\n\n\"...operational capacity... less than 5%... accidentally... punctured oil reservoir...\"\n\n\"...use coconut milk... rock... save A-Me 01...\"\n\n<A-Me closes her eyes.>", objectives = "" }
WordHunterWoW_QuestEN[24717] = { title = "The Apes of Un'Goro", description = "There's plenty of money to be had here in Un'Goro, you just need to know where to look!\n\nApes may be common here in Un'Goro, but they're much rarer up north.  In Everlook, a gorilla hide fetches ten times what you'll get for it down here!\n\nI'm not going to send you all the way up to Winterspring - that'd be irresponsible - but I could use your help actually obtaining some hides.\n\nYou'll find gorillas at Fungal Rock, to the northeast, near a waterfall.  Don't forget to check inside the cave!", objectives = "" }
WordHunterWoW_QuestEN[24718] = { title = "The Mighty U'cha", description = "Looking around, you see bits of red fur laying around this part of the cave.  It appears to match the consistency of gorilla fur.\n\nBased on your conversations with Gremix, you know that he would almost certainly be interested in a red gorilla hide, if you were to obtain one.", objectives = "" }
WordHunterWoW_QuestEN[24719] = { title = "Claws of White", description = "Stop, {race}.  I could use the help of a {class} like you.\n\nRight outside this camp, there are raptors with deadly claws.  I've been using the claws for druid rituals, but it doesn't seem to be working.  However, I did notice that some of those raptors sometimes have white claws, when most have deathly black ones.\n\nThe earth works in strange ways.  Maybe you could fetch me some of the white claws, and I'll try one last time?", objectives = "" }
WordHunterWoW_QuestEN[24720] = { title = "Crystals of Power", description = "I'm sure you've noticed 'em, {name}. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?  \n\nYou'll find yellow crystals to the northwest, red crystals to the... oh, I'm sure you'll figure it out.", objectives = "" }
WordHunterWoW_QuestEN[24721] = { title = "The Eastern Pylon", description = "High up in the cliffs above me there is a large crystal pylon.  Who placed it there, I cannot say, nor can I determine any reason that it would be built in such a strange place.\n\nMaybe you can make more of it than I can.  I personally don't care what it does, so you needn't report back to me, but perhaps one of the scholars in Marshal's Stand might be interested in what you discover.", objectives = "" }
WordHunterWoW_QuestEN[24722] = { title = "The Northern Pylon", description = "You've done us a number of favors, {name}... now let Gremix do one for you.  The attacks on Marshal's Refuge were terrible, undoubtedly.  They came without warning, and took no prisoners.  They were lucky that so many of them survived.\n\nA few weeks ago, I came across a crystal pylon in the cliffs to the northeast of here, east of Marshal's Refuge.  I think the pylon and the attacks may be related somehow.  Maybe you can investigate?  I'm sure someone in Marshal's Stand will thank you.", objectives = "" }
WordHunterWoW_QuestEN[24723] = { title = "The Western Pylon", description = "Durrin's research touched on one area that intrigues me: a potential link between the titans and the dinosaurs.  J.D. Collie back at camp is always talking about titan this and crystal that... maybe she'd be interested.\n\nBefore you report to her, you might want to check out the crystal pylon not far from here.  It's just up in the cliffs, to the west of here.  It's got crystals on it, and it always seemed to me like it might have something to do with the titans.", objectives = "" }
WordHunterWoW_QuestEN[24730] = { title = "Roll the Bones", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", objectives = "" }
WordHunterWoW_QuestEN[24731] = { title = "The Fare of Lar'korwi", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nStart your search to the west.", objectives = "" }
WordHunterWoW_QuestEN[24732] = { title = "The Scent of Lar'korwi", description = "I'm actually surprised he has not come for you yet, {name}. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", objectives = "" }
WordHunterWoW_QuestEN[24733] = { title = "The Bait for Lar'korwi", description = "This will be the most difficult part because there is some complexity to the plan.  Continue following the river to the north, and look for a bend in the river.  It was here I saw Lar'korwi last.  You will know you are in the right area because of all the bones from massive creatures that once wandered nearby.\n\nTake the meat you recovered and place it there.  Then, rub this mixture I created on the meat.\n\nIf both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", objectives = "" }
WordHunterWoW_QuestEN[24734] = { title = "Lost!", description = "You've got to help me, {name}! My friend, Ringo left earlier to explore the volcano to the north of here, and he has been gone way too long. I am really worried about him.\n\nDo you think you could find him? Why don't you take my canteen with you -- if you do find Ringo, I'm sure he'll need it!", objectives = "" }
WordHunterWoW_QuestEN[24735] = { title = "A Little Help From My Friends", description = "Ugh... It's so hot...\n\nI was exploring this area, when all of a sudden, the heat just became unbearable. I must be suffering from heat exhaustion.\n\nPlease, help me get back to my friend Spraggle at Marshal's Stand. I think I'm well enough to follow you there.\n\nI am feeling a little out of it, so you can slap me if I'm feeling woozy.  If I do happen to faint again, just splash some water on me from Spraggle's canteen. That should work, I hope...", objectives = "" }
WordHunterWoW_QuestEN[24736] = { title = "Shizzle's Flyer", description = "I'm making a flying machine!\n\nI got stranded here, and I'm absolutely horrible at finding my way around. I'd take a gryphon or wind rider back to Gadgetzan, but those beasts just scare me to death.\n\nSo, will you help me? All I have left to build is the wings, and I was thinking that the webby scales from the pterrordax in the Screaming Reaches to the west would be perfect. There's no way I'm going to go up against one of those, but you look pretty tough. Why don't you give it a try?", objectives = "" }
WordHunterWoW_QuestEN[24737] = { title = "Super Sticky", description = "I'm always looking for a quick way to earn a gold, {name}. If you help me with my newest idea, I'll let you in on a little of the profit. How does that sound to you?\n\nI thought so!\n\nWe're going to be making some glue. Head to the tar pits just north of here, and collect me some tar. Not just any tar, now, you'll need to get it from the beasts that live around the tar pits. As a bonus, if you use my tar scraper on their corpses, you'll keep your hands nice and clean.", objectives = "" }
WordHunterWoW_QuestEN[24740] = { title = "Volcanic Activity", description = "Welcome.  I'm Williden Marshal, and my sister and I run this expedition of explorers and scientists.  You have a moment?\n\nI don't like the look of those elementals on that volcano, {class}.  We have too much equipment, too many notes... one crazed elemental could streak its way through our camp and do terrible, terrible damage.\n\nShow them that their new neighbors aren't to be trifled with.  And bring back the ash that they leave behind... we might as well do a little science while we're at it.", objectives = "" }
WordHunterWoW_QuestEN[24741] = { title = "Trading Up", description = "Hobart thinks he's going to feed us on those tiny clucker eggs? Bah! We're going to get some real eggs!\n\nI've already set up some traps on the Raptor Rise up the path to the east. Take this bunch of wild clucker eggs and lay them in the traps. The spiny raptors will go right after the clucker eggs, and then you'll get to trade up to their larger eggs.\n\nGenius!", objectives = "" }
WordHunterWoW_QuestEN[24742] = { title = "Finding the Source", description = "I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest lava flows.  It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!\n\nHot spots usually take the form of a glowing, rocky pillar jutting out of the ground.  You'll find them around the base of Fire Plume Ridge... one trip around the perimeter will likely suffice.", objectives = "" }
WordHunterWoW_QuestEN[24743] = { title = "Shadow's Edge", description = "", objectives = "" }
WordHunterWoW_QuestEN[24744] = { title = "The Biggest Egg Ever", description = "Bamm Megabomb? Who does he think he is? His spiny raptor eggs are no match for what we are about to recover!\n\nAs you well know, each Town-In-A-Box is equipped with a micro mechachicken for just such a dietary emergency. Luckily for us, my keen intellect was able to deduce the location that our prodigious, pre-programmed poultry ran off to.\n\nHead north to the Scorched Gully. But beware, its circuit boards are fried and I imagine it's not so micro any longer!", objectives = "" }
WordHunterWoW_QuestEN[24747] = { title = "Sabotage!", description = "These dwarven artillery shells have a built-in airburst timer. This is easy! Just sabotage one of the artillery shells in the loading bay and then hoist it up into the magazine. Boom, baby. BOOM!\n\nYou'll find the shells in one of two loading bays behind the main garage on this level. It's right around the corner.\n\nOnce you've rigged the artillery shell... Run! Run like the wind, {name}! Then report to Gann back at camp. I'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[24748] = { title = "The Lich King's Last Stand", description = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny.\n\nWith this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand.\n\nTake this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls.\n\nSteel yourself, {class}, and guide Shadowmourne to fulfill the purpose of its creation.", objectives = "" }
WordHunterWoW_QuestEN[24749] = { title = "Unholy Infusion", description = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness.\n\nYou must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him.\n\nFind a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", objectives = "" }
WordHunterWoW_QuestEN[24750] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Soratha to the east.", objectives = "" }
WordHunterWoW_QuestEN[24751] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the arcane arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", objectives = "" }
WordHunterWoW_QuestEN[24753] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "" }
WordHunterWoW_QuestEN[24754] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "" }
WordHunterWoW_QuestEN[24755] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "" }
WordHunterWoW_QuestEN[24756] = { title = "Blood Infusion", description = "Your weapon is ready to be endowed with the power of blood.\n\nYou must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, {race}.\n\nOnce the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death.\n\nMay her screams pierce the ears of the Lich King as he awaits his fate.", objectives = "" }
WordHunterWoW_QuestEN[24757] = { title = "Frost Infusion", description = "Shadow's Edge is prepared to receive its final infusion of power.\n\nSindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death.\n\nWithout his dragon, nothing shall stand between you and the Lich King.", objectives = "" }
