WordHunterWoW_QuestEN[24790] = { title = "Daily Normal Random (1st)", description = "", objectives = "" }
WordHunterWoW_QuestEN[24794] = { title = "Speak With Spraggle", description = "My good friend Spraggle has been fretting about something for some time now.  I'd help her, but as you can see, I'm pretty comfortable right now.\n\nCould you check in with her and see what she needs?", objectives = "" }
WordHunterWoW_QuestEN[24795] = { title = "A Victory For The Silver Covenant", description = "In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, {name}. Long have we dreamt of reclaiming Quel'Delar.\n\nThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? Perhaps the Argent Crusade can find one. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Silver Covenant.", objectives = "" }
WordHunterWoW_QuestEN[24796] = { title = "A Victory For The Silver Covenant", description = "In spite of Queen Lana'thel's boasting, you have restored Quel'Delar, {name}. Long have we dreamt of reclaiming Quel'Delar.\n\nThe Silver Covenant, and indeed all quel'dorei owe you a debt of gratitude.\n\nVereesa Windrunner, the leader of the Silver Covenant, asked to see you after you returned from the Sunwell. Take Quel'Delar with you and go to Dalaran's Violet Citadel where she waits, {name}.", objectives = "" }
WordHunterWoW_QuestEN[24798] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei!\n\nAll of Silvermoon will celebrate you as a hero, {name}.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? No worthy sin'dorei has come forward. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.", objectives = "" }
WordHunterWoW_QuestEN[24799] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers!\n\nAll the Horde will celebrate you as a hero, {name}.\n\nAs a {class}, the sword seems to know you lack the training to wield it and hasn't bonded to you. Where, then, will its next master come from? I will not conceal my disappointment; I had hoped it would be a worthy sin'dorei. Let us seek the Argent Crusade's counsel. Go north to the Argent Tournament Grounds and present the sword to Justicar Mariel Trueheart on behalf of the Sunreavers.", objectives = "" }
WordHunterWoW_QuestEN[24800] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the sin'dorei! All of Silvermoon will proclaim you a hero, as will all of the Horde.\n\nArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, {name} and bring Quel'Delar with you. The archmage wishes to congratulate you personally!", objectives = "" }
WordHunterWoW_QuestEN[24801] = { title = "A Victory For The Sunreavers", description = "At last, Quel'Delar is restored for the glory of the Sunreavers and the Horde! This is a blessing for our efforts against the Lich King.\n\nArchmage Aethas Sunreaver, the leader of the Sunreavers, asked to see you after you returned from the Sunwell. Travel to the Violet Citadel in Dalaran as soon as you can, {name} and bring Quel'Delar with you. The archmage wishes to congratulate you personally!", objectives = "" }
WordHunterWoW_QuestEN[24802] = { title = "Wrath of the Lich King", description = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that?\n\nMany questions remain, but you need to find Sylvanas and escape the Lich King while there's still time.", objectives = "" }
WordHunterWoW_QuestEN[24807] = { title = "Winnoa Pineforest", description = "While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice.  The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at Vendetta Point, southwest of here.", objectives = "" }
WordHunterWoW_QuestEN[24812] = { title = "No More Mercy", description = "Da naga have committed great atrocities on our people. Da time ta show dem mercy has long passed.\n\nEnter da cave and kill any naga you find dere. Every naga dead dis day is one less naga ta take us unawares later on. I trust ya will be thorough.", objectives = "" }
WordHunterWoW_QuestEN[24813] = { title = "Territorial Fetish", description = "Dis is no casual counter-attack. We be fully intendin' ta slaughter every last naga here and do anything we can ta ensure that dey will have no desire ta return.\n\nI want ya ta place dese fetishes on any Spitescale banner ya be findin' inside their cave. It should prove a clear statement of what we think of their presence here. More dan dat, da magic in dese fetishes will be weakenin' any Spitescale dat approach, which should make dem second guess stayin' on our isle.", objectives = "" }
WordHunterWoW_QuestEN[24814] = { title = "An Ancient Enemy", description = "Da Sea Witch is here, on top of dis very isle. We've been waitin' a long time for dis chance at revenge and ya will be havin' da privilege of seein' it through.\n\nMeet with Vol'jin, up da ramp to da northeast. Let him know when you are ready ta join da battle.", objectives = "" }
WordHunterWoW_QuestEN[24815] = { title = "Choose Your Path", description = "", objectives = "" }
WordHunterWoW_QuestEN[24816] = { title = "Who's Top of the Food Chain Now?", description = "Fine, fine, perhaps the whole egg thing didn't quite pan out. Who's up for some shark meat?\n\nOnly one little problem. Well, a big problem, actually. A really BIG problem: The Hammer!\n\nOf course, I have a brilliant idea. Swim out into the Dire Strait to the west and get us some shark parts. Give them to my assistant, Greely. I'm too important to get my hands dirty with the small details.", objectives = "" }
WordHunterWoW_QuestEN[24817] = { title = "A Goblin in Shark's Clothing", description = "Combining the remains of the Mechachicken with these shark parts, we've assembled the greatest fighting submersible of all time: the Mechashark X-Steam!\n\nHobart and I want you to pilot it, {name}. Go west to the water and activate the Mechashark X-Steam Controller.\n\nYou must kill The Hammer if we're to have any hope of exploiting the natural resources of the Dire Strait to their fullest extent. It's for the good of the cartel!", objectives = "" }
WordHunterWoW_QuestEN[24823] = { title = "Path of Destruction", description = "You seek to continue down the path of destruction?", objectives = "" }
WordHunterWoW_QuestEN[24824] = { title = "The Disturbed Earth", description = "We are here to monitor the scars of the land, and watch for further signs of instability.  While we haven't seen any yet, a cataclysmic aftershock could devastate the Barrens even further.\n\nTo the northeast, near the chasm, earth elementals rampage out of control. To soothe the earth, these need to occasionally be destroyed, and their essence returned in a ritual. If you help us do this, {class}, I would be happy to reward you.", objectives = "" }
WordHunterWoW_QuestEN[24825] = { title = "Path of Wisdom", description = "You seek to continue down the path of wisdom?", objectives = "" }
WordHunterWoW_QuestEN[24826] = { title = "Path of Vengeance", description = "You seek to continue down the path of vengeance?", objectives = "" }
WordHunterWoW_QuestEN[24827] = { title = "Path of Courage", description = "You seek to continue down the path of courage?", objectives = "" }
WordHunterWoW_QuestEN[24828] = { title = "Path of Destruction", description = "You seek to continue down the path of destruction?", objectives = "" }
WordHunterWoW_QuestEN[24829] = { title = "Path of Destruction", description = "You seek to continue down the path of destruction?", objectives = "" }
WordHunterWoW_QuestEN[24830] = { title = "Path of Wisdom", description = "You seek to continue down the path of wisdom?", objectives = "" }
WordHunterWoW_QuestEN[24831] = { title = "Path of Wisdom", description = "You seek to continue down the path of wisdom?", objectives = "" }
WordHunterWoW_QuestEN[24832] = { title = "Path of Vengeance", description = "You seek to continue down the path of vengeance?", objectives = "" }
WordHunterWoW_QuestEN[24833] = { title = "Path of Vengeance", description = "You seek to continue down the path of vengeance?", objectives = "" }
WordHunterWoW_QuestEN[24834] = { title = "Path of Courage", description = "You seek to continue down the path of courage?\n", objectives = "" }
WordHunterWoW_QuestEN[24835] = { title = "Path of Courage", description = "You seek to continue down the path of courage?\n", objectives = "" }
WordHunterWoW_QuestEN[24852] = { title = "Our Tribe, Imprisoned", description = "Despite their size, the Bristleback greatly outnumber us. A pack ambush can easily overwhelm even the largest tauren.\n\nMany new initiates have taken up arms to defend our home. Some have given their lives, but others have been captured alive.\n\nPlease, find their cages and free them. The battle should keep the quilboar distracted.", objectives = "" }
WordHunterWoW_QuestEN[24854] = { title = "Finding Stormclaw", description = "Zen'Aliri been studyin' the ways of the druid, {race}.  Hopefully one day, Zen'Aliri join the Druids of the Talon, and soar over this crater as a storm crow.\n\nBut for now, my mentor says I stay here and wait.  So Zen'Aliri waits.\n\nI know another druid who might be able to use your help.  His name is Garl Stormclaw, and he's somewhere to the east of here, studying reagents.  Maybe you go talk to him?", objectives = "" }
WordHunterWoW_QuestEN[24855] = { title = "Aberrant Flora", description = "Look how strangely the plant life reacts to the bloodpetals in the Roiling Gardens to the north.  The trees are enveloped with more flowers and vines than usual.  Large, sporous blossoms project themselves from the ground where they once did not.\n\nThe land is speaking to us, {race}.  The bloodpetals are destroying the balance.\n\nAs my final task, I ask you to visit the swarming adult Bloodpetals and prune their numbers.", objectives = "" }
WordHunterWoW_QuestEN[24856] = { title = "Invasion Imminent!", description = "Your work here is done for now, but there's no rest for the wicked, eh?\n\nYou remember Megs Dreadshredder, our old marketing rep? She's taken some others over the hills to the southeast, just past the Raptor Rise. If you follow the path east out of town and follow it south at the fork, you can't miss her.\n\nApparently there's some trouble or other brewing with the snake-men at the ruins on the shore. Go see if you can't sort it all out, would you?", objectives = "" }
WordHunterWoW_QuestEN[24858] = { title = "Bilgewater Cartel Represent", description = "Looks like the naga down there in the ruins are preparing to invade our Town-In-A-Box. I have lots of dead scouts here as proof.\n\nI don't know about you, but I'm not about to let them try. Let's get the jump on them!\n\nCould you lay the foundation for our new coastal holdings by replacing their banners with our own? That's some prime real estate down there!", objectives = "" }
WordHunterWoW_QuestEN[24859] = { title = "Naga Hide", description = "It's oft whispered in dark corners of a material so fine, so exquisite to the touch, that goblins of sophisticated taste will spend any amount of moolah to get their hands on some.\n\nOf course, I'm speaking of naga hide!\n\n<Brett looks around to make sure no one else is listening in.>\n\nI know that you're going to head down there and that it's inevitable that you're going to have to fight those snakes. Hey, they're not going to have a use for their hides anyway. They'll be dead!", objectives = "" }
WordHunterWoW_QuestEN[24861] = { title = "Last Rites, First Rites", description = "The camp is safe, and the quilboar driven off, all thanks to you, young one. You have my personal thanks for what you have done for my mother, my son, and for all of us.\n\nIt is now time to put Greatmother Hawkwind to rest. Lay the final offering at her feet, {name}, and we will say our goodbyes.", objectives = "" }
WordHunterWoW_QuestEN[24862] = { title = "Running the Gauntlet", description = "Look around you, {class}. We've had no luck dislodging the Horde from the hidden trails that overlook this valley. They appear out of nowhere to ambush our supply caravans and then disappear into the hills!\n\nI need you to run the gauntlet to Honor's Stand and let them know the roads still aren't safe. Talk to Mattingly, the supplies officer by the gate.\n\nAnd kill a few of these brutes along the way!", objectives = "" }
WordHunterWoW_QuestEN[24863] = { title = "Breaking the Siege", description = "Horde scouts hiding in the ruins up ahead ambushed my supply train. Only two of my bodyguards made it out of there alive. And me? I used to have hair!\n\nThe supplies I was delivering are scattered through the ruins up ahead. Gather them up and take them to Janice Mattingly at Honor's Stand. If they can't make it to Stonetalon, at least we can keep them out of Horde hands...", objectives = "" }
WordHunterWoW_QuestEN[24864] = { title = "Irresistible Pool Pony", description = "I've got a plan and you're the only one that I know crazy enough to pull it off!\n\nI need you to take this irresistible pool pony to the Vashj'elan Spawning Pool and inflate it. Then, swim down to their hatchlings with it on. I'll bet anything that the hatchlings can be lured away to follow you.\n\nBring them back here and we'll proceed with the next phase of the plan.", objectives = "" }
WordHunterWoW_QuestEN[24865] = { title = "Is This Stuff Still Good?", description = "You find what appears to be a crate of food, left behind when this camp was abandoned.  On the outside of the crate, you can make out a stamp that says \"PROPERTY OF MARSHAL EXPEDITIONS\".\n\nPerhaps you might find someone who could use this?", objectives = "" }
WordHunterWoW_QuestEN[24866] = { title = "An Abandoned Research Camp", description = "You find what appears to be a piece of research equipment, left behind when this camp was abandoned.  Chiseled onto the side of the device are the words \"PROPERTY OF MARSHAL EXPADISHUNS\".\n\nPerhaps you might find someone who could use this?", objectives = "" }
WordHunterWoW_QuestEN[24868] = { title = "Surrender or Else!", description = "{name}, you and Ace need to march those naga hatchlings down there and use them as leverage to convince the leader of the naga to surrender to us.\n\nAce knows where to go on the south side of the ruins... just follow him.", objectives = "" }
WordHunterWoW_QuestEN[24897] = { title = "Get Back to Town", description = "We were wrong. It wasn't the naga that were preparing to attack... it was the nearby Oomlot tribe.\n\n{name}, you need to get back to the Town-In-A-Box. The pygmies are already attacking!\n\nHere, take this. We bought it off of a pygmy who said it used to belong to some great leader of theirs. Someone whose name translates as Dark Tan Helmet.\n\nIt should fool them so that they don't attack you.", objectives = "" }
WordHunterWoW_QuestEN[24901] = { title = "Town-In-A-Box: Under Attack", description = "{name}, you have to defend us!\n\nI had the eggheads deploy the town's cannon defenses, but it seems like there's an unlimited supply of these Oomlot warriors!\n\nGet your behind into one of those B.C. Eliminators and eliminate the pygmy threat to the town!", objectives = "" }
WordHunterWoW_QuestEN[24902] = { title = "The Hunt For Sylvanas", description = "It's true then?  Gilneas has lost her favorite son.\n\nWe will mourn when this is all over but not a day sooner.\n\nWe will not allow ourselves the luxury of grief while the enemy still breathes Gilnean air.\n\nMy father's men are ready to strike while we still have the Banshee Queen's trail.  Just say the word if you're ready.  Liam deserves swift vengeance.", objectives = "" }
WordHunterWoW_QuestEN[24903] = { title = "Vengeance or Survival", description = "Tell Greymane that we have trackers on Sylvanas and tell him about the Plague.\n\nThe decision will be his.  Launch an all out attack against the leader of the Forsaken or try to evacuate our survivors.", objectives = "" }
WordHunterWoW_QuestEN[24904] = { title = "The Battle for Gilneas City", description = "The time has come, {name}.  We've rallied and armed every available Gilnean.\n\nIt is time to meet the enemy head on.  Time to settle the score with Sylvanas and her Forsaken dogs once and for all.\n\nLiam is heading the assault from this gate.  King Greymane and my father are leading the assault on the other districts.\n\nYou have a crucial role to play in this as well.  Take this rapier.  Use it to inspire our men and women in combat.  Speak to Krennan Aranas to take part in the battle for Gilneas City.", objectives = "" }
WordHunterWoW_QuestEN[24905] = { title = "Returning a Favor", description = "You know, while you were out doin' your thing, Megs stopped by here. I hadn't seen her in months, but she barely gave me the time of day, just wanted me to tell you she had more business lined up.\n\nShe said she was headed over to the Dunemaul Compound to set up shop, something about ogres. Since you're done here, might as well head over...I wouldn't keep a goblin like her waiting.", objectives = "" }
WordHunterWoW_QuestEN[24906] = { title = "Seaside Salvage", description = "We've got to get goods moving in this market ASAP if we want to be competitive. I've got an angle for us.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nHead down there and start salvaging; there's crates full of pure profit just floating around down there.", objectives = "" }
WordHunterWoW_QuestEN[24907] = { title = "Puddle Stomping", description = "Here's the situation. If we want to establish the Bilgewater Cartel's market presence in Gadgetzan, we'll need to start providing services to the community.\n\nThe new coast has been great for business here, but the sea also brought sea giants with it. They're large, foul, and drive real estate values down.\n\nHead to the shallows just south of town and kill as many as you can, and I'll cut you in on some of the deals I'm brokering here.", objectives = "" }
WordHunterWoW_QuestEN[24910] = { title = "Rocket Rescue", description = "Alright, {name}. We've done enough small jobs around here; it's time to seal the deal.\n\nThe ruins of Steamwheedle Port are still full of hapless Steamwheedle goblins, waiting to be rescued. Every single one of them is a potential future customer. They're firing on every boat that leaves port...so I say we take to the skies!\n\nThere's a hot air balloon just outside of town near the docks, we can use that. Go ahead and hop in, I'll catch up with you.", objectives = "" }
WordHunterWoW_QuestEN[24911] = { title = "Tropical Paradise Beckons", description = "Hey, you look like a discriminating adventurer.  Are you looking for something different?  Something exotic?  Something... profitable?\n\nWell shake the sand out of your boots, because I've got a proposition for you.  Williden Marshal is looking for competent sellswords such as yourself.  He's set up camp at Marshal's Stand, just southeast of the volcano in the center of lush Un'Goro Crater.\n\nThen again, paradise isn't for everyone, {race}.  It's up to you.  Your tropical oasis awaits.", objectives = "" }
WordHunterWoW_QuestEN[24912] = { title = "Empowerment", description = "<Highlord Darion Mograine speaks to you purposefully.>\n\nShadow's Edge is prepared to receive its final endowment of power.\n\nThe time has come to attempt the forging of Shadowmourne!", objectives = "" }
WordHunterWoW_QuestEN[24913] = { title = "Remember the Light", description = "Magtoor grows weaker by the second, {name}. My remedy is prepared... it must work. It must!\n\nYou have done so much for the both of us. I would be honored if you stayed for what may be Magtoor's final moments.", objectives = "" }
WordHunterWoW_QuestEN[24914] = { title = "Personal Property", description = "You can detect no hinges or openings on this box. Were it not for the shifting of items inside, it could easily be mistaken for solid metal.\n\nIf anyone could know the method of its opening, it would be Highlord Mograine.", objectives = "" }
WordHunterWoW_QuestEN[24915] = { title = "Mograine's Reunion", description = "What is that you hold, {class}?\n\nIt calls out to me, stirring feelings I thought to be long dead.", objectives = "" }
WordHunterWoW_QuestEN[24916] = { title = "Jaina's Locket", description = "Yes, {class}? How can I assist you?", objectives = "" }
WordHunterWoW_QuestEN[24917] = { title = "Muradin's Lament", description = "Whatdya got there, {race}?", objectives = "" }
WordHunterWoW_QuestEN[24918] = { title = "Sylvanas' Vengeance", description = "What is it, {race}?", objectives = "" }
WordHunterWoW_QuestEN[24919] = { title = "The Lightbringer's Redemption", description = "How may I be of service, {race}?", objectives = "" }
WordHunterWoW_QuestEN[24920] = { title = "Slowing the Inevitable", description = "As much as I want to exact swift and brutal revenge... I must honor my son's memory first.  He cared for his people first and foremost.\n\nThe Undertaker's Pass goes underground below Northgate River.  You must prevent the plague from being deployed while we evacuate our men, women and children to Aderic's Repose.\n\nWe captured one of the Forsaken's dreaded bombing bats.  I want you to fly the infernal beast as best you can and unleash hell upon those who seek to bring the Plague to our people.  Hurry!", objectives = "" }
WordHunterWoW_QuestEN[24921] = { title = "Report to Aubrey", description = "You there! Fresh off the boat? Welcome to Kalimdor, a land hellbent to kill you or die tryin'.\n\nThere's trouble at the hold - as I'm sure you noticed on your way in. Admiral Aubrey needs all hands on deck if we're to make it through this. Consider yourself drafted, {class}!\n\nFollow the road up the hill and you'll find Aubrey in the tower, topside.", objectives = "" }
WordHunterWoW_QuestEN[24924] = { title = "Oomlot Village", description = "The pygmies took most of our people back to their village. Who knows what evil they're up to?\n\n{name}, you have to go up there and free all of the captives before the pygmies work their voodoo on them!\n\nIzzy's already up near Oomlot Village to the southeast. She'll give you the heads-up on what's going down.\n\nYour pygmy helmet looks like it's in bad shape, but it should last long enough for you to get there.\n\nI hope.", objectives = "" }
WordHunterWoW_QuestEN[24925] = { title = "Free the Captives", description = "They've got a bunch of our people in there. I know that they're doing strange rituals to them. It looks like they're sucking the life force right out of them!\n\nYou have to go into the village and free the captives before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[24926] = { title = "Serving A-Me 01", description = "Greetings.  I unit A-Me 01.  You... {race}?\n\nA-Me's mission to study the local gorillas was success.  A-Me has gathered data that Karna needs.\n\nA-Me 01 not returning, though.  A-Me has new family now.  Here, with the gorillas, A-Me stay.\n\n<A-Me 01 detaches a small device from her hand and gives it to you.>\n\nYou bring data back to Karna.  You tell her what happen.", objectives = "" }
WordHunterWoW_QuestEN[24927] = { title = "Dead Man's Chest", description = "Look, babe, you should be able to see what's happening here pretty easily. There's pirates, there's goblins, the goblins are fighting the pirates. There's some sad little gnomes trying to fight the pirates too.\n\nI'll make it nice and simple for you: we need to kill a lot of pirates. Go do that, 'kay? We don't want the gnomes killing more than us, after all.", objectives = "" }
WordHunterWoW_QuestEN[24928] = { title = "To The Ground!", description = "I've conducted a thorough appraisal of the real estate here and, unfortunately, its market value is just far too low to be of any use. We're going to have to renovate.\n\nLuckily for you, I've learned a few things about arson. Hopefully you have too! You're going to be throwing these perfectly safe bottles of flaming rum at those filthy ramshackle huts over there.\n\nTry not to stand downwind.", objectives = "" }
WordHunterWoW_QuestEN[24929] = { title = "Send a Message", description = "The Oomlot leader, Yngwie, is too powerful to be left alive. He's barking nonsense from the raised west side of the village, across the rope bridge.\n\nGo up there and get him before he sends the rest of the village against us.\n\nPiece of cake!", objectives = "" }
WordHunterWoW_QuestEN[24930] = { title = "While You're At It", description = "Fine by me if King Greymane wants you to risk your life to rescue a known traitor.\n\nDo me a favor and do something useful while you're out there and kill these cursed fleabags.", objectives = "" }
WordHunterWoW_QuestEN[24931] = { title = "Gazer Tag", description = "You're going out to hunt hyenas, eh? If you don't mind, I've got an offer myself. I'm in need of eyes from the Glasshide Gazers that lurk to the north. Their eyes contain wonderful crystals, valuable to...collectors.\n\nNow, you may have heard that some sad individuals use these to enhance paramental abilities, but I assure you, my interests are purely academic!\n\nBring me a good portion of them and I'll pay you well for them. Better than these copper-pinching goblins will, at least!", objectives = "" }
WordHunterWoW_QuestEN[24932] = { title = "Cutting Losses", description = "I've spent the last week starin' at this ugly pit trying to think of how to exploit a bunch of dangerous, violent arthropods for profit. Now I'm out of ideas, and starving.\n\nThese things are a wash, and I say it's time to start clearing them out. Head down into that pit and start killin' bugs.", objectives = "" }
WordHunterWoW_QuestEN[24933] = { title = "Chicken of the Desert", description = "I've got an idea, but we're going to need bait.\n\nThe other day I saw a rabid blisterpaw hyena wander too close to the edge of the chasm, and one of the silithid comes diving out of nowhere. Nearly swallowed it whole! Horrible sight.\n\nSo we're gonna need hyena meat, obviously. Go gather some, make sure it's fresh, and bring it back here. There should be plenty just north of the camp.", objectives = "" }
WordHunterWoW_QuestEN[24934] = { title = "Repel Boarders!", description = "{name}, the sea is our only lifeline, and right now most of my fleet is either steaming back to Theramore for repairs or rusting at the bottom of this bay. Only the Blackpool remains afloat to defend our harbor.\n\nBut she's just signaled that she's being boarded!\n\nSpeak to me when you're ready, I'll have one of our naval gryphons deposit you right on the deck. Slaughter the rageroar sea dogs who dare assault my precious ship and report to Captain Fisher for further orders. ", objectives = "" }
WordHunterWoW_QuestEN[24937] = { title = "Oomlot Dealt With", description = "{name}, you have to get back to the Town-In-A-Box and warn them about the goblin zombies up in the volcano's caldera!", objectives = "" }
WordHunterWoW_QuestEN[24938] = { title = "The Guns of Northwatch", description = "Captain Fisher signaled us from below. The Horde fleet is landing shore parties? We can't let them flank us from the beach.\n\nI've already sent two of my best gunners down there to defend the beach head. Talk to Cannoneer Smythe down on the shore.\n\nYou'll have to fight your way through the courtyard to get there. See if you can help the others secure the hold on your way down!", objectives = "" }
WordHunterWoW_QuestEN[24939] = { title = "Run Out the Guns", description = "We've got the hardware but not the manpower, {name}. Man one of the carronades on the shore here and take out those incoming boats! ", objectives = "" }
WordHunterWoW_QuestEN[24940] = { title = "Up the Volcano", description = "A whole bunch of our people headed up to the top of the volcano to mount a counter-offensive. There's something horrible brewing up there on the Lost Peak.\n\nThey're waiting for you before they make any moves against the pygmies. Those evil little things turned a lot of us into zombies!\n\n{name}, save us!", objectives = "" }
WordHunterWoW_QuestEN[24941] = { title = "Langridge Shot", description = "{class}! Thank the Light - they've practically driven us back to the docks. The courtyard is overrun!\n\nWe're out of canister shot and the orcs are getting ready for an assault up the hill. We need to improvise some scatter-shot, and fast.\n\nHurry, run into the broken tower here and grab whatever sharp, pointy bits of scrap metal you can lay your hands on. Knives, forks, nails - anything! Load the cannon when you've got an armful!", objectives = "" }
WordHunterWoW_QuestEN[24942] = { title = "Zombies vs. Super Booster Rocket Boots", description = "Those zombies that got past us are nothing compared to the numbers waiting just through the pass. If we don't deal with them soon, the pygmy witch doctors are going to send all of them against the town, and even the cannons down there won't be able to handle that many!\n\nI brought a couple of shredder boots along. Greely modded them and now they're Super Booster Rocket Boots!\n\nUse the boots to incinerate the zombies in the Oostan villages to the east.", objectives = "" }
WordHunterWoW_QuestEN[24943] = { title = "Re-Take the Courtyard", description = "That's one way to clear a hill. Those corpses are impaled with knives and forks!\n\nThe Rageroar clan has breached the walls, but we can still turn this fight around. Go down the hill and help our men hold on to the courtyard below...", objectives = "" }
WordHunterWoW_QuestEN[24944] = { title = "Back in the Fight", description = "This fight isn't over, {class}. Not by a long shot.\n\nSome of the soldiers in the courtyard still have breath in their lungs. We can save them! I've soaked these rags in an herbal remedy we used to rely on back in Gilneas. The smell is awful but this poultice can practically raise the dead.\n\nUse these bandages on wounded defenders down in the courtyard and we'll see if we can't get them back in the fight.", objectives = "" }
WordHunterWoW_QuestEN[24945] = { title = "Three Little Pygmies", description = "Look, I think it's great that we're destroying all of these zombies, even though they're our friends and family. But don't you think we should be taking care of the pygmies that are creating them as well?\n\nAt the three Oostan villages, Nord, Sor, and Ost, there are witch doctors: Gaahl, Malmo, and Teloch.\n\nMaybe you could take care of them? I don't want to be turned into a zombie!", objectives = "" }
WordHunterWoW_QuestEN[24946] = { title = "Rockin' Powder", description = "I'll give these pygmies one thing... they sure know how to party! But they're not so clever. I think I've discovered the source of their rockin' powers: Rockin' Powder!\n\nIt turns out that this stuff, which turns them into world-class rockers, is also highly explosive. We must have it!\n\nSo, while you're in there at Oostan to the east, make sure that you pickup a whole bunch of the stuff. Trust me, you're going to need it for what's coming up!", objectives = "" }
WordHunterWoW_QuestEN[24947] = { title = "Momentum", description = "We can't just rest on our laurels here, babe. We've got to keep this momentum going! People are talking about us.\n\nUnfortunately, they're also talking about this air-headed gnome, Kelsey, who's apparently been running jobs right alongside us. If we're going to drive her out of what's rightfully a goblin town, we need to seal the deal here.\n\nWe're going to take care of Gadgetzan's pirate problem for them, for good. Head south to Lost Rigger Cove, I'll meet you there.", objectives = "" }
WordHunterWoW_QuestEN[24948] = { title = "Lifting the Siege", description = "We'll never be able to re-secure the fortress walls so long as Rageroar and his goons have access to artillery. I need you to fight your way across that chasm and take out his big guns.\n\nOrcs season their heavy machinery with coal tar, which makes them flammable. Take my torch and burn any catapults you see north of Northwatch.\n\nThen, torch those big blade-throwers in Rageroar's base camp! Those things have killed enough of our men. ", objectives = "" }
WordHunterWoW_QuestEN[24949] = { title = "Booty Duty", description = "Let's not be wasteful here, babe. These pirates have tons of valuable nonsense just sitting around, waiting to be fenced. Can you believe they just sit on this stuff?\n\nI mean, why do they even bother taking it if it's just going to sit around? Stolen goods should be sold off and used to buy shiny new things.\n\nAnyway, be a dear and go grab as much of their loot as you can carry while you're out busting heads. Ciao!", objectives = "" }
WordHunterWoW_QuestEN[24950] = { title = "Captain Dreadbeard", description = "Alright, babe, I've got something bigger for you to take on here.\n\nWe spotted the captain of the Southsea over on one of his boats to the south; that's to the south, and NOT the one we've been suicidally bum-rushing for the better part of several hours. He's sitting up there, smug and stoic, watching us war down here.\n\nI'll spare you the \"hostile takeover\" jokes. Get on his ship and beat the tar out of him, and we're done here! ", objectives = "" }
WordHunterWoW_QuestEN[24951] = { title = "A Great Idea", description = "Now that we've got a good pile of fresh chunks, we just tie it to this rope...and now you're ready to go catch me a silithid.\n\nWhat? Don't give me that look, it's perfectly safe. Well, mostly safe. Okay, you might die painfully. But it'll be easy! Just throw this meat out there, wait for a bug to pounce on it, and then drag 'em back here by the rope!\n\nGo after one of the swarmers. I haven't seen the other ones go for hyenas before, and you should find plenty of swarmers around the edge of the pit.", objectives = "" }
WordHunterWoW_QuestEN[24952] = { title = "Rocket Boot Boost", description = "You need to get those boots down into the caldera to Hobart Grapplehammer.\n\nNow that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot.\n\nWhen you're ready, activate the boots. Don't worry, they're automatically set to land you safely.\n\nI think.", objectives = "" }
WordHunterWoW_QuestEN[24953] = { title = "Just Trying to Kill Some Bugs", description = "Now it's time for my plan to go into full effect. We've got the captured bug strapped up with as many explosives as it can carry, and with Soothfancy's mostly amazing mental powers, we're gonna drive that sucker straight down into the center of the underground hive.\n\nAnd then...BOOM! No more bugs!\n\nYou get the personal honor of directin' the ugly thing. Go talk to Narain and get set up with your bug-pal.", objectives = "" }
WordHunterWoW_QuestEN[24954] = { title = "Children of a Turtle God", description = "Volcanoth is the turtle god in the cave that these primitives worship.\n\nIt's not really a god.\n\n<Hobart rolls his eyes.>\n\nBut it is tough enough that I'm going to have to devise a new weapon for you from the one functioning boot we have left.\n\nI think that the age-old motto of \"fight fire with fire\" applies here. Plus, I like fire!\n\nLet's get some fire glands from Volcanoth's children. That should give me time to modify the rocket boot into something more fitting.", objectives = "" }
WordHunterWoW_QuestEN[24955] = { title = "Un-Chartered", description = "As I may have mentioned, I'm trying to get these Dunemaul ogres to join the Horde..and  work for the Bilgewater Cartel as cheap local labor.\n\nTo pull this off, we've gotta pay lip service to the actual initiation process and all that, or I'm going to catch flak later on. So I've gotten this charter drawn up, and slapped the initiation rites onto our own limited time offer labor stipulation contract.\n\nI've got a disguise for you here, so suit up and get all these signatures filled out.", objectives = "" }
WordHunterWoW_QuestEN[24956] = { title = "Silencing Rageroar", description = "I have encountered the Rageroar clan before, {name}. They are led not by an orc, but by a monster - a war-gorged fiend without a shred of decency or compassion. He and his lieutenants must be killed, not just to save Northwatch, but for the good of all of Azeroth.\n\nKarga Rageroar wears a helm. Execute him, {class}, and bring the helm to me. It is of ... particular importance.\n\nRageroar has made his camp across the chasm, east of here.", objectives = "" }
WordHunterWoW_QuestEN[24957] = { title = "Get The Centipaarty Started", description = "Okay, babe. Like I said, the ogres are too dumb to know what signing that charter meant. Now we have to actually get them to come along with us, so we'll be procuring what is apparently beloved local flavor.\n\nBeloved local flavor for drooling idiots, I mean.\n\nJust pop on over to the Noxious Lair to the west, it's that big horrible pit full of dangerous silithid. Kill a bunch of the Centipaar silithid and bring back the pieces so we can hand 'em out, okay? Ciao.", objectives = "" }
WordHunterWoW_QuestEN[24958] = { title = "Volcanoth!", description = "It took a lot of blood, sweat, and tears, but the Bootzooka, patent-pending, is ready for use!\n\nThese no-good pygmies have been feeding our people to their \"god\", Volcanoth, and they're about to unleash it on our town!\n\nYou have to get into the cave and kill that thing before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[24959] = { title = "Fresh out of the Grave", description = "{name}!\n\nRise, {name}!\n\nWelcome back to the realm of the living.  With the blessing and power of the Dark Lady, I have freed you from death's grip.\n\nYou are no slave, {name}.  You are free to follow whatever path you choose from here.  If you choose to serve the Dark Lady Sylvanas, I recommend you speak with Undertaker Mordo.  You will find him behind me, in the graveyard.", objectives = "" }
WordHunterWoW_QuestEN[24960] = { title = "The Wakening", description = "King, peasant, or {class}... I don't care WHAT you were before.  I just need somebody with a working tongue.\n\nBeing raised from the dead is strenuous.  Not everyone copes with it as well as you did.  In particular, there are three newly-raised undead who are having trouble coping right now.\n\nI want you to find them and talk to them.  It might be that they just need someone that they can relate with.\n\nYou'll find them here in the graveyard.", objectives = "" }
WordHunterWoW_QuestEN[24961] = { title = "The Truth of the Grave", description = "Earlier on, I saw a young Forsaken woman running towards the old inn.  She was screaming for her life, pleading to be taken back home.\n\nNot all of us are as resolute as others, {name}.  Even so, we must accept our fate as undead if we are to rise up against those that would put us down.\n\nTake my hand mirror and show it to the young woman.  She needs to see what she really is, and join us in our cause.  Besides... we can use all the bodies that we can get.", objectives = "" }
WordHunterWoW_QuestEN[24963] = { title = "Maul 'Em With Kindness", description = "Okay, babe, listen up. There's two ways to get people to do what you want. You can provide goods, services, and things people want...or you can beat the living daylights out of them.\n\nI've often found it's useful to do both at the same time, and you're pretty familiar with both methods by now. Take these little silithid treats, go and beat some ogres dizzy, and then give them the treat before you knock them completely dead, 'kay?", objectives = "" }
WordHunterWoW_QuestEN[24970] = { title = "No Better Than the Zombies", description = "While you were inside that cave, your big friend Darnell came by with some alarming news.\n\nSince the val'kyr arrived, we've seen more and more undead that chose not to join our forces under the banner of the Dark Lady.  They've been gathering at a small camp here in the valley, and now they've organized forces.\n\nThey plan to attack Deathknell, {class}.\n\nDarnell is just down the road, to the east.  Be careful, {name}.  While those undead aren't completely brainless, they're still not quite right in the head.", objectives = "" }
WordHunterWoW_QuestEN[24971] = { title = "Assault on the Rotbrain Encampment", description = "While you were taking care of matters for Executor Arren, I went off on an assignment of my own.  Shadow Priest Sarvis asked me to peek in on the Rotbrain camp.\n\nThere's a reason why they're called Rotbrains.\n\nTheir leader goes by the name of Marshal Redpath, and he's an absolute beast.\n\nLook, {name}... the attack is starting.  You're better in combat than I am.  Get in there and help out!\n\nWhen you're done, meet up with Shadow Priest Sarvis in the chapel.  Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[24972] = { title = "Vital Intelligence", description = "<Sarvis produces a piece of paper from within his robes.>\n\nThese will need to be taken to my field agent, Deathguard Simmer.  This information contains the whereabouts of the last few holdouts from the Scarlet Crusade.  We will destroy these crusaders, once and for all.  And I have a feeling you'll be instrumental in that effort, {name}.\n\nTake the road north out of Deathknell.  Soon after entering Tirisfal proper, you'll see a large manse.  Simmer's inside.", objectives = "" }
WordHunterWoW_QuestEN[24973] = { title = "Night Web's Hollow", description = "One of our greatest struggles is obtaining the natural resources we need to survive.  Gold was scarce in Lordaeron, even in the height of the Alliance's power so many years ago.\n\nThere is a gold mine to the west that has been overrun with spiders.  We need gold from the mine, but we can't very well get it while the spiders are crawling around in there.  I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, {name}.", objectives = "" }
WordHunterWoW_QuestEN[24974] = { title = "Ever So Lonely", description = "You work hard your whole life, and what do you get?  Killed by a plague.  Then you work even harder in undeath, and what do you get?  Money, yes, and a small estate with a few pesky hangers-on, but happiness?  Not so much.\n\nI'm lonely in my old age, {name}.  I need a companion.  Use this leash on one of the murlocs at the Whispering Shore to the northwest.  You'll have to weaken it first before it can be leashed.  Then bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[24975] = { title = "Fields of Grief", description = "What have we here?  You look like a fledgling {class}.  If you hope to prove yourself to the Dark Lady, you need to learn the ways of the Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[24976] = { title = "Variety is the Spice of Death", description = "These pumpkins have a purpose, {class}.  They'll be the delivery mechanism for my latest batch of plague, which should be a particularly painful and virulent concoction.  However, the plague requires a few rare ingredients.\n\nWe'll need Marrowpetals, which grow at the bottom of Stillwater Pond, just to the east of here.  We'll also need Xavren's thorn, which grows on rocky cliffs to the northwest.  Finally, we need some briny sea cucumbers, found in the surf off of Whispering Shore.", objectives = "" }
WordHunterWoW_QuestEN[24977] = { title = "Johaan's Experiment", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat the Scourge advances from the North and the human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept outside, by the gazebo.  Take this pumpkin to the fool.", objectives = "" }
WordHunterWoW_QuestEN[24978] = { title = "Reaping the Reapers", description = "Humans are notoriously fickle creatures.  The farmers to the west are no exception.  Sure, they may be plowing their fields peacefully now, but tomorrow, they may be raising their scythes against us.  The Alliance looms close by in Gilneas, and the power of Stormwind looms to the south... any of these could recruit these tillers and use them as a wedge against us.\n\nI want them dead.  See to it that it's done.", objectives = "" }
WordHunterWoW_QuestEN[24979] = { title = "A Scarlet Letter", description = "Lieutenant Gebler:\n\nHow curious that you would decide to take a prisoner... an undead one at that.  What were you thinking?  Do you think that, just because of the prisoner's former status, that she would be above the edicts of the Scarlet Crusade?\n\nThis is most troubling, Gebler.  I would remind you that there are penalties for such behavior.  I command you to execute the prisoner at once.  She is no longer one of us.", objectives = "" }
WordHunterWoW_QuestEN[24980] = { title = "The Scarlet Palisade", description = "We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slaying 10 warriors of the Scarlet Crusade.", objectives = "" }
WordHunterWoW_QuestEN[24981] = { title = "A Thorn in our Side", description = "Information we've received from Executor Arren in Deathknell contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill 3 of his zealots and 3 of his missionaries.  And while you're there, see if you can dig up any other information about what they're up to.", objectives = "" }
WordHunterWoW_QuestEN[24982] = { title = "The New Forsaken", description = "Speaking frankly, the Forsaken of yesteryear were a sniveling, pathetic group.  We huddled together in decrepit old human buildings, hiding from the Scourge, cowering from the Alliance, and groveling at the foot of the Horde.\n\nLook before you now, and see the product of the new Forsaken.  We have made our mark here on Azeroth, and that mark will grow.  Our dominion will soon blanket the world!\n\nYou want my advice?  Speak with Magistrate Sevren in Brill, down this road.  He runs that town.", objectives = "" }
WordHunterWoW_QuestEN[24983] = { title = "Forsaken Duties", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", objectives = "" }
WordHunterWoW_QuestEN[24988] = { title = "The Chill of Death", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The mindless state will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five duskbat pelts, I could sew myself a blanket.  Help me, {name}, so that I can continue to serve the cause.", objectives = "" }
WordHunterWoW_QuestEN[24989] = { title = "Return to the Magistrate", description = "You should return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.", objectives = "" }
WordHunterWoW_QuestEN[24990] = { title = "Darkhound Pounding", description = "Lady Sylvanas has called upon the Royal Apothecary Society.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring our enemies - living and dead - to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Here, fill these vials with darkhound blood so I can test my theory. ", objectives = "" }
WordHunterWoW_QuestEN[24991] = { title = "Garren's Haunt", description = "As you're probably already realizing, the Royal Apothecary Society is a widespread organization.  We take our plague-alchemy seriously.  It is our belief that the more agents we have performing experiments, the sooner we will realize our objective.\n\nOne of our agents performs his work at a small encampment to the north of here.  His name is Jerrod, and he could use an apprentice of your... stature.", objectives = "" }
WordHunterWoW_QuestEN[24992] = { title = "Escaped From Gilneas", description = "As far as you know, a worgen rogue roaming in Tirisfal is a new development.  This is something that Executor Zygand would certainly be interested in.", objectives = "" }
WordHunterWoW_QuestEN[24993] = { title = "Annihilate the Worgen", description = "These worgen must be dealt with, and quickly.  Our first priority is to eliminate any which may have infiltrated Brill.\n\nI want you to be on the lookout for any suspicious activity here in Brill, {name}.  We know that these worgen can hide in the shadows, so look for any signs you can find... footsteps, kicked-up rocks... anything.", objectives = "" }
WordHunterWoW_QuestEN[24994] = { title = "Doom Weed", description = "My envoy just delivered me a bushel of gloom weed.  Gloom weed!  I don't need gloom weed, I need doom weed!  You can see the predicament that I'm in, {name}.\n\nI'll make it worth your while to gather what I need. Bring back to me enough doom weed and I'll give you a suitable reward.\n\nIt is my understanding that they like to plague the flora near the mass gravesite, to the north of the Brill graveyard. Hurry and be mindful of the gnolls in the area.", objectives = "" }
WordHunterWoW_QuestEN[24995] = { title = "Off the Scales", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly.  Poisoning some hapless victim is child's play.  Plaguing an entire world proves to be a bit more complicated.\n\nI will need several scales from murlocs in the vicinity.  You will find the creatures ambling brainlessly along the coast to the north.", objectives = "" }
WordHunterWoW_QuestEN[24996] = { title = "Holland's Experiment", description = "I am to understand that another one of those foolish Dwarven Mountaineers has just been captured.  The deathguard has him stored here in this building, and they've assigned one of their own to persuade him not to escape.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", objectives = "" }
WordHunterWoW_QuestEN[24997] = { title = "Graverobbers", description = "The mass graves within the forest to the west of us were made to accommodate the... impressive... number of deaths Tirisfal suffered when the plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the mass grave and Garren's Haunt, and gather from them the embalming ichor that gives them life.", objectives = "" }
WordHunterWoW_QuestEN[24998] = { title = "Maggot Eye", description = "Maggot Eye is a foul beast, even by gnoll standards.  He leads a band of renegade gnolls through the land, tearing up the glades and stealing whatever corpses he can find along the way.\n\nThose are our corpses!  We had plans for those!\n\nMaggot Eye resides just up the path from us.  Show him no mercy.  Mercy is for the weak.", objectives = "" }
WordHunterWoW_QuestEN[24999] = { title = "Planting the Seed of Fear", description = "It seems that Jerrod has you hunting the murlocs to the north.  That's good... we can use their parts for our poisons.  I get a little worried sometimes, though...\n\nThe Vile Fin spawning grounds are not far off Tirisfal's northern coast, so you'll probably notice several tadpoles among the adults on the shore.  If these impressionable young murlocs were to seek revenge against us... that could ruin us.  Go chase them, and show them that the Forsaken and the Horde are not to be trifled with.", objectives = "" }
WordHunterWoW_QuestEN[25000] = { title = "Teegan's People", description = "Hey, {class}!\n\nAre you headed to support Corporal Teegan? He's in charge of keeping the supply routes open.\n\nHe's got two of the most ornery dwarves I've ever met in charge of sundries. If you want to make an impression on those two crotchety hunters, you're going to need to show that you can hold your own against the predators around here.\n\nThe raptors west of the hold here are especially vicious. Bring Goucho some fresh hides and you'll make an impression while supplying the troops in one swoop.", objectives = "" }
WordHunterWoW_QuestEN[25001] = { title = "Sandscraper", description = "My other assistants are making sure our proud new comrades are put into comfy cages and shipped to where they're needed most. For the Horde. Meanwhile, we've got one last item on our agenda.\n\nSandscraper, the chief of the Dunemaul Clan, is probably too dumb to even be aware of what we're doing here. But I absolutely loathe unfinished business, babe. He's lurking in the den just over there to the west. Knuckle down, take him out, and we'll be good to sign off on this, 'kay?", objectives = "" }
WordHunterWoW_QuestEN[25002] = { title = "Scavenged", description = "<You discover a cargo manifest on the body, detailing a long list of sundries urgently needed on the front.>\n\n<A bloody trail in the dirt indicates bodies were dragged south of here, toward the raptor dens.>\n\n<The raptors may have dragged away the supplies, as well. Retrieving those supplies for Corporal Teegan could help salvage this disaster!>", objectives = "" }
WordHunterWoW_QuestEN[25003] = { title = "The Family Crypt", description = "The strongest point in the mills is the Agamand Family Crypt.  With necromancy, Captain Dargol has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.", objectives = "" }
WordHunterWoW_QuestEN[25004] = { title = "The Mills Overrun", description = "The Scourge are trying to form a base here at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nCollect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.", objectives = "" }
WordHunterWoW_QuestEN[25005] = { title = "Speak with Sevren", description = "I have destroyed the remains you've given me, {name}.  That is, all remains except for these...\n\nDevlin Agamand was weak and sharp-tongued in life, and was among the first to succumb to the plague.  He existed as a slave of the Scourge for a long time, longer than most.  As such, he may possess knowledge that would be of value to us.\n\nBring his remains to Magistrate Sevren, and tell him what I've told you.  He'll know what to do.", objectives = "" }
WordHunterWoW_QuestEN[25006] = { title = "The Grasp Weakens", description = "While the Frozen Throne lies dormant, the grasp that the Lich King once held over the Scourge grows ever-weaker.  His grip on a weakling like Devlin Agamand should be weak enough that we can remove it entirely.\n\nSpeak with Shadow Priestess Malia in the manor on the east side of town.  She will assist you in the procedure.", objectives = "" }
WordHunterWoW_QuestEN[25007] = { title = "East... Always to the East", description = "You've done much for us here, {name}, but men of your caliber are needed elsewhere.\n\nTo the east lies the Bulwark: a fortified barricade against the ravages of the Plaguelands.  The Bulwark protects us from Scourge invasions, and has allowed us enough sanctity to build up our forces here in Tirisfal Glades.\n\nGo, speak with High Executor Derrington.  He is an ally, and will doubtless appreciate whatever aid you can give him.", objectives = "" }
WordHunterWoW_QuestEN[25008] = { title = "Filthy Animals", description = "You probably caught wind of some of them Hecklefang scavengers on the way in - they reek worse than ol' Durty Pete here. Worthless animals! They steal our kills, rummage through our supplies, and worse... they ain't good for eatin'.\n\nGo kill some.\n\nThen kill some more, if you want to. ", objectives = "" }
WordHunterWoW_QuestEN[25009] = { title = "At War With The Scarlet Crusade", description = "Though the strength of the Scarlet Crusade wanes, we are still at war.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill 3 of his zealots and 4 of his friars. It should prove to be a devastating blow to the Crusade!", objectives = "" }
WordHunterWoW_QuestEN[25010] = { title = "A Deadly New Ally", description = "Shortly before you arrived at the Bulwark, I was approached by the most unusual young undead woman.  She swore enmity against the Scarlet Crusade, so I sent her to work on our enemies to the north.  You say you saw some dead crusaders earlier?  Those were probably her work.\n\nGo check up on her, and see if she can use any assistance in her vendetta against the Crusade... though I wouldn't be surprised if she's already killed them all.", objectives = "" }
WordHunterWoW_QuestEN[25011] = { title = "To Bigger and Better Things", description = "There isn't much more glory for you here on the Bulwark, {name}.  You've done enough already.  There may, however, be further adventures waiting in Silverpine Forest.\n\nSpeak with my bat man, Timothy Cunningham.  He'll give you a ride to Brill, free of charge.", objectives = "" }
WordHunterWoW_QuestEN[25012] = { title = "Take to the Skies", description = "If you're headed back to Brill, you'll want to stop by Executor Zygand on your way out.  I hear there's some excitement going on in Silverpine Forest, to the south.  He'll know more than I do.\n\nSpeak with me again when you're ready to head out.", objectives = "" }
WordHunterWoW_QuestEN[25013] = { title = "A Little Oomph", description = "<Dithers samples his latest concoction.>\n\nHmm... this isn't quite there.  It needs something to give it a little more zing.  I've got it!  The spiders to the north have a potent venom that'll do the trick.  See if you can extract some for me, {name}?", objectives = "" }
WordHunterWoW_QuestEN[25014] = { title = "Sandscraper's Treasure", description = "Inside this weathered stone chest at the back of Stonescraper's lair, you find a curious artifact.\n\nShaped like a beetle, its surface is a smooth, brilliant blue, lined with gold. It looks mechanical, but unlike anything you've seen crafted by mortal hands, and very old.\n\nMegs will probably be interested in this.", objectives = "" }
WordHunterWoW_QuestEN[25015] = { title = "Make 'em Squeal", description = "One of the native species in Kalimdor is the 'quilboar.' Prickly little buggers. Reason enough to hate this continent.\n\nThe raids started shortly after we established our forward camps. Worse, those spiny fiends seem to thrive in this thorny hell of a jungle. I need you to help beat them back so we can re-establish contact with Forward Command.\n\nWhile you're out there, acquire one of those twisted branches their casters seem to be using to manipulate the jungle growth...", objectives = "" }
WordHunterWoW_QuestEN[25017] = { title = "Ancient Obstacles", description = "For years, this valley has been sealed behind impenetrable gates. Now that the cataclysm has torn them down, the secrets within are ours to discover.\n\nThere are yet some obstacles in the way. From within the gates, the bygone creations of the titans have awoken. They wander aimlessly across the sand, attacking any who approach.\n\nSomeone needs to destroy the golems patrolling the valley; are you up to it?", objectives = "" }
WordHunterWoW_QuestEN[25018] = { title = "Andoren Will Know", description = "Listen carefully, {name}. I don't know how those ogres got ahold of it, but that thing's a titan artifact. I'm no expert, but just that fact alone makes it probably older than the sand we're standing on.\n\nI also know that things like this are nothing but trouble. I don't want anything to do with it. Take it south, to the Valley of the Watchers, and give it to a blood elf named Andoren Dawnrise there. And don't ask any questions, babe, please.", objectives = "" }
WordHunterWoW_QuestEN[25019] = { title = "Laying Claim", description = "We are not the only ones who have discovered the value of the Southmoon Ruins. The dwarves of the Explorers' League have swarmed there, taking artifacts and inscriptions for the Alliance.\n\nI don't think I have to explain much further. We will not allow the discoveries here to fall into the hands of the Alliance. Slay as many dwarves as you can, and drive them from the ruins!", objectives = "" }
WordHunterWoW_QuestEN[25020] = { title = "Fragments of Language", description = "At the Southmoon ruins, just east of here, we've made some finds. My colleagues have found stone shards, engraved with ancient writings, newly exposed by the shifting sands.\n\nThe writings are in no known tongue, though they bear resemblance to markings we've seen on other ruins of the titans. Deciphering them could reveal many more secrets.\n\nUnfortunately, my colleagues are also busy defending the tablets from the Alliance. I need you to go to the Southmoon ruins and retrieve the tablets yourself.", objectives = "" }
WordHunterWoW_QuestEN[25021] = { title = "Blood to Thrive", description = "To survive in de harsh desert, de Sandfury had to learn all de secrets of blood magic. You drink de blood, you get de power...darkest voodoo, yah? But dere be no room for holdin' back out here.\n\nIf we gonna find de sword, we need blood. Lucky for ya, Mazoga be a traitor, yah? And dere be plenty of Sandfury trolls wanderin' over de hills dere.\n\nGo an' get Mazoga blood...plenty of blood...and we make de ritual to find Jang'thraze. ", objectives = "" }
WordHunterWoW_QuestEN[25022] = { title = "A Failure to Communicate", description = "I told him he was a fool, but Ambassador Gaines insisted he could negotiate an alliance with the quilboar against the Horde. Even if he succeeded, I for one wouldn't want to fight with those ... pig-men at my side.\n\nWell, Gaines hasn't returned, and General Hawthorne will hold me accountable if I lose one of our best negotiators to these squealing savages.\n\nLocate the Ambassador in this steaming mess of a jungle and rescue him if he's still alive.", objectives = "" }
WordHunterWoW_QuestEN[25023] = { title = "Old Friends", description = "Alright then, grab onto the ladder. We gotta get outa here!\n\nWe'll make a flyby of the town, and then I'm gonna get you to some old friends!", objectives = "" }
WordHunterWoW_QuestEN[25024] = { title = "Repel the Paratroopers", description = "The Alliance have caught back up with us at just the wrong moment, my friend. We took care of their ships, but they still have planes that are dropping their vaunted 127th Paratroopers onto the coast below.\n\nIt's all that the battlesworn and scouts can do to hold the two ramps against their overwhelming numbers. I'm certain that if you were to aid them, the tide would quickly be turned.", objectives = "" }
WordHunterWoW_QuestEN[25025] = { title = "Sang'thraze the Deflector", description = "The blood speaks. I can feel its flow through the sand...drenched in death, a desert of suffering...\n\n<Mazoga's eyes roll back in his head.>\n\nThere! The blood flows to the south, in a valley of bones. Zakkaru! Zakkaru, spawn of Makkari, the dark one who demands sacrifice... his father forced from Zul'Farrak, his ascension interrupted... he will taste blood once more...\n\n<Mazora reels.>\n\nGo, {class}. Zakkaru has Sang'thraze. Ya not be wanting him to keep it, trust me.", objectives = "" }
WordHunterWoW_QuestEN[25026] = { title = "Darkest Mojo", description = "Jang'thraze eludes me, mon... de blood is not enough. We gonna need somethin' stronger to find it.\n\nWhen you need every troll you got to help out to scrape by, one o' them dyin' on ya is a big problem, mon, an' dat's why de Sandfury learned to raise our dead wit' da voodoo. You fall over, you just get back up again and keep workin'... forever!\n\nDe zombies we make be imbued wit' darkest mojo. You go on to de west an' find a whole mess o' dem, an' get me dat mojo, yah?", objectives = "" }
WordHunterWoW_QuestEN[25027] = { title = "You Flicked a Fine Vine to Leaf Me", description = "According to Gaines, \"Three-Tooth\" is what the quilboar call their matriarch. She's been twisting the thorns of this crazy jungle to her own ends, and it was her orders that Gaines be \"torn apart and fed to the overgrowth.\" Nice lady.\n\nLet's give her a taste of her own. Take the Bramblestaff you recovered, and use it on Three-Tooth to take her out of the picture. Then kill the crones she's been training, to ensure nobody else can take her place.", objectives = "" }
WordHunterWoW_QuestEN[25028] = { title = "Trouble From the Ground Up", description = "Teegan's a fool to think the quilboar caused this sudden overgrowth. Look around you. I've been watching these plants bloom and sprout daily - each generation is more mutated than the last. This isn't tribal magic - it's something primal. And dangerous.\n\nThe day before last a great druid passed through our camp. Seek out Naralex, somewhere in the midst of this jungle. He'll know what to do.\n\nAnd bring him some plant samples from around the overgrowth to help his studies.", objectives = "" }
WordHunterWoW_QuestEN[25029] = { title = "Deaths in the Family", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the plague.  Serve me by bringing me their remains.", objectives = "" }
WordHunterWoW_QuestEN[25030] = { title = "The Haunted Mills", description = "You sense a malign presence coming from within the skull of the beast.  Coleman Farthing may be interested in seeing this.", objectives = "" }
WordHunterWoW_QuestEN[25031] = { title = "Head for the Mills", description = "The Agamand Mills, to the west, have been lost to the Scourge.  The Agamand family has been slain, and the entire residence has been claimed by the Scourge.\n\nThis is probably the largest Scourge outpost in Tirisfal, {name}.  If you think you're enough of a {class}, head up there and speak with Coleman Farthing.  He's been doing his best to take the land back, and he'll need help.  Just follow this road, it'll take you right to him.", objectives = "" }
WordHunterWoW_QuestEN[25032] = { title = "Secrets in the Oasis", description = "Yes, I see the other half now, mon...to the south...\n\nWe be close now, mon. It's in an oasis, buried in de muck beneath de water. Don't delay!", objectives = "" }
WordHunterWoW_QuestEN[25034] = { title = "To the Front!", description = "I'd love to keep you here behind the lines, but it looks like you've been summoned to the front. Ambassador Gaines - remember him? - has relocated to Forward Command and in his latest missive he's requested you, personally, to assist him.\n\nYou'll find our Forward Command operation south of here, in what's become known as the \"Fields of Blood.\"\n\nBe careful, {name}. The Horde has taken to ambushing some of our officers en route.", objectives = "" }
WordHunterWoW_QuestEN[25035] = { title = "Breaking the Line", description = "Vol'jin be callin' for an all out attack on da naga that have taken over our northern isle. Many of our men were already engaged with their forces near da bridge, but several of us are breakin' through their lines ta assault their isle itself.\n\nSpeak to Jornun right 'ere to secure a ride to da isle. Once there, seek out Morakki, da Captain of da Watch. He will be tellin' ya how ya can aid in da battle.", objectives = "" }
WordHunterWoW_QuestEN[25036] = { title = "Teegan's Troubles", description = "The Admiral will be pleased that Northwatch is almost secured, but if we're to keep a grip on this continent we're going to need to maintain the supply lines to the interior.\n\nJust before the assault I received the strangest of reports from Corporal Teegan, who's in charge of maintaining our contact with Forward Command. Says he's having trouble with the \"jungle?\" There's no jungle in the Barrens!\n\nFollow the upper road out of Northwatch and see if you can render any assistance to our wayward Corporal.", objectives = "" }
WordHunterWoW_QuestEN[25037] = { title = "Crab Fishin'", description = "Perhaps me agin' body is just growin' too picky after all dese years, but boar meat just ain't goin' down easy no more. More for da new recruits I be thinkin'.\n\nWe just set out some crab traps, but if ya be willin' ta help an impatient old troll, I'd love ta have some fresh crawler meat right now. Dey're all around da island, but da best spot ta be huntin' them is off da eastern coast.", objectives = "" }
WordHunterWoW_QuestEN[25038] = { title = "Gordo's Task", description = "Master want weeds. Us gots big hands and not good at picking. You help us and we not hurt you. Us need gloom weed. Many weeds around here and near road.\n\nWhen you have gloom weed you take to Master Holland in Brill.\n", objectives = "" }
WordHunterWoW_QuestEN[25039] = { title = "Have You Seen Anything Weird Out There?", description = "{race}!  Listen up, I got somethin'... odd to discuss.\n\nI was out fishin' by Brightwater Lake when I saw the darnedest thing... some sorta wolf-man, running around Tirisfal.  Ya don't suppose that could be a... worgen, do ya?\n\nAnyway, I keep tellin' myself I should tell Executor Zygand about it, but I just get so scared when I talk to that guy.  Maybe you could talk with him?", objectives = "" }
WordHunterWoW_QuestEN[25041] = { title = "Lion's Pride", description = "Respect the lion, {name}! A ferocious killer. You gotta admire the elegance of the beast... Muscle and claws... Running down its food... So primal...\n\nI'm sorry, my mind wandered. As I was saying, I respect these lions, but they're just murder on our patrols. I mean that literally. The men are afraid to go to the bathroom alone at night. Can you help make our camp a little safer?\n\nBarrens lions like to linger under trees.", objectives = "" }
WordHunterWoW_QuestEN[25042] = { title = "Marching On Our Stomachs", description = "It's true what they say: An army marches on its stomach. And we've been marching a long way.\n\nI'm thinking if we barbecue up a few of those giant lumbering stormsnouts, we'll have enough meat to feed us for weeks.\n\nStormsnouts are big and slow, so they should be easy to kill. Except... Hey you're not carrying any metal on you are you?", objectives = "" }
WordHunterWoW_QuestEN[25043] = { title = "Fields of Blood", description = "The Horde has taken to calling this region the \"Fields of Blood.\" It's an apt name: these reeds run red with the blood of some of my best men.\n\nI've sent out recon patrols to crush the quilboar and report on the Horde troop movements, but not all of them return. They could use your support out there.\n\nPatrol the fields and seek out the Desolation Grunts that are causing us so much grief. Do not expect them to surrender; their Warchief has instructed them to fight to the death.", objectives = "" }
WordHunterWoW_QuestEN[25044] = { title = "Diplomacy By Another Means", description = "I have not forgotten my brush with death at the hands of the quilboar in that filthy jungle. The General here has ordered some tactical strikes, but he stops short of genocide. I have no such qualms.\n\nTake this horn that I 'borrowed' during my negotiations. Blow the horn within the Bristleback challenge ring west of our position - you can't miss it. I want you to challenge the champion of the Bristleback, Sabersnout, to single combat. His death in front of his followers will leave them in utter chaos.", objectives = "" }
WordHunterWoW_QuestEN[25045] = { title = "A Line in the Dirt", description = "Strategically, control of a region requires constant observation. See here on this map - I've identified a number of strategic hills, similar to this one, that the Alliance must acquire if we are to keep the enemy under our thumb.\n\nMy scouts have already marked their location on the field. What I need is someone to spearhead their capture, and you're the man for the job.\n\nSeek out neutral grey flags on hills to the north, east, and south of the Taurajo Ruins. Capture one and defend it!", objectives = "" }
WordHunterWoW_QuestEN[25046] = { title = "A Daughter's Embrace", description = "The whisper continues:\n\n<\"My name is Lilian Voss.  Before I died, I was a member of the Scarlet Crusade.  My father, High Priest Voss, raised me to be a weapon against the plagued.  I studied stealth, sorcery, martial arts, anything to make myself stronger.  I gave up my childhood for him.\">\n\n<\"Then, as fate would have it, I died and returned as... this.  My father instantly forgot me and, when I returned, ordered me executed.\">\n\n<\"Come.  We will speak with him now, in his tower to the northwest.\">", objectives = "" }
WordHunterWoW_QuestEN[25047] = { title = "Broken Panther Figurine", description = "This badly broken figurine was discarded by its last owner.  However, with the right materials and your skill in jewelcrafting, it could be completely restored.\n", objectives = "" }
WordHunterWoW_QuestEN[25048] = { title = "Seaside Salvage", description = "If we want to convince Mister Noggenfogger to let us move more gnomes here, we've got to show him just how nice we are! I know just the thing.\n\nGadgetzan's under blockade by pirates, but plenty of the goods that get blown off the ships survive intact... they just wash away. Most of them wash up in the shallows just south of town.\n\nIf you could go collect those supplies for them, it'd help us make friends! And it'll keep that mean goblin girl over there from taking them and selling them.", objectives = "" }
WordHunterWoW_QuestEN[25049] = { title = "Puddle Stomping", description = "There's a big problem here! It's great that the ocean came in so far, because now ships can get to Gadgetzan. But now there's a bunch of nasty old sea giants encroaching on the town! I'm sure Mister Noggenfogger would appreciate us taking care of them for him.\n\nDon't worry, I won't ask you to do it just out of the goodness of your heart! Take care of them and I'll give you a reward!", objectives = "" }
WordHunterWoW_QuestEN[25050] = { title = "Rocket Rescue", description = "When the water came in, Steamwheedle Port to the east was flooded, and a lot of poor goblins are still stuck there! Now those mean pirates are shooting at any boat that leaves the docks here.\n\nBut they won't expect us to fly! There's a hot air balloon by the docks. We can use that, fly over to rescue the goblins, and take care of the pirates, too. Mr. Noggenfogger will be so pleased!\n\nGo to the docks and hop in the balloon and I'll be right behind you, okay? I've got to get some rockets...", objectives = "" }
WordHunterWoW_QuestEN[25051] = { title = "Darkmist Extermination", description = "The spiders that occupy Darkmist Cavern to the northwest are another vicious threat to us here. They are nothing the ogres cannot handle, but splitting our attention to them when Theramore's forces lurk nearby is a deadly mistake.\n\nI need someone to destroy the eggs inside Darkmist Cavern, to cut off this infestation. You will find the eggs in the deepest part of the webbed mines... along with their guardians.", objectives = "" }
WordHunterWoW_QuestEN[25052] = { title = "Dead Man's Chest", description = "Well gosh, as you can plainly see there's this really big battle with these pirates here going on. We're doing our best to make sure they never bother Gadgetzan or our new gnomish homes there ever again!\n\nBy killing them.\n\nSo how about helping us? We really wanna make sure we kill more than green-nose over there and her awful thugs. I'd really appreciate it!", objectives = "" }
WordHunterWoW_QuestEN[25053] = { title = "To The Ground!", description = "You know, this place would probably make a great home for us gnomes if it wasn't so old and dirty and full of pirates! We're taking care of the pirates problem, but the awful and dirty problem needs fixing.\n\nI mean, no self-respecting gnome would ever live in such an ugly hovel like these buildings! So here, take this bottle of flaming rum and go burn those ugly shacks down for us!", objectives = "" }
WordHunterWoW_QuestEN[25054] = { title = "Lootin' Plunder", description = "It's just really so wasteful that all these pirates have golden treasures lying around. Some of this stuff could be used for practical things! Like melting into wire, or intrinsic shielding matrices, or selling to other stupid races that buy gold just to keep it around.\n\nAnd speaking of other stupid races, I bet those greedy goblins are going to be taking all of it. We can't let that happen! Go collect that treasure for Gnomeregan!", objectives = "" }
WordHunterWoW_QuestEN[25056] = { title = "Grisly Grizzlies", description = "Have you seen the plagued bruins that wander to the west of here?  Those hides... so hideous, so diseased, so... perfect!\n\nFetch me 5 of them.  I've got an idea for an anti-Scourge poison that's guaranteed to succeed!", objectives = "" }
WordHunterWoW_QuestEN[25057] = { title = "Clap 'Em In Irons", description = "Our policy of conscripting non-violent criminals from the Stormwind Stockades has come back to haunt us, {name}. Some of my less-scrupulous soldiers broke ranks after our victory in Taurajo and are looting the remains of the city.\n\nThis is a breakdown in discipline. Worse, the desecration of their homes only spurs the enemy to fight harder when our ultimate goal should be peace.\n\nTake these manacles and bring the Taurajo looters to justice. Speak to them first, but you may need force to subdue them.", objectives = "" }
WordHunterWoW_QuestEN[25058] = { title = "Mine Disposal, the Goblin Way", description = "The paratroopers have mined the beach!\n\nThe Warchief asked me if there's anything we can do about that. I told him, 'You bet we can!'. I was thinking maybe you could take this satchel of grenades and detonate the land mines from a safe distance?\n\nIt's how we do things, right?!", objectives = "" }
WordHunterWoW_QuestEN[25059] = { title = "The Taurajo Briefs", description = "The General is too preoccupied with the looters in Taurajo. Too soft! We ought to be focused on our next move against the Horde.\n\nThere's valuable intelligence that might be compromised if we allow the ruins of Taurajo to continue to burn. While you're running the General's errand, dig around for any maps or notes you can find. I can speak a little of the orcish tongue - I'll be able to make sense of what you find.", objectives = "" }
WordHunterWoW_QuestEN[25060] = { title = "Define \"Crazy\"", description = "We received reports that a goblin shipwreck occured on this beach some time ago, with the survivors left to fend for themselves. We expected there to be a modicum of survivors, perhaps some even suitable for interrogation.\n\nWhat we found was a crew of Bilgewater goblins who have all become insane, delusional, and maniacally violent...to further degrees than is normally observed, rather.\n\nIn short, they are useless and dangerous. Gnomeregan will be best served by cutting down as many as we can.", objectives = "" }
WordHunterWoW_QuestEN[25061] = { title = "Land's End", description = "Psst! Hey! Come closer, you fool, you expect me to read your mind or--oh. Come closer anyway!\n\nYou've done a wonderful job advancing the agenda of Gnomeregan here, friend! And an amazing job of pretending you were only in it for the coin, simply splendid. But now Kelsey Steelspark could use more of your direct help.\n\nShe's moved on yet again...she asked me to tell you to meet her far south, at Land's End Beach. I wouldn't keep her waiting, either!", objectives = "" }
WordHunterWoW_QuestEN[25062] = { title = "What We Came For", description = "Gnomeregan previously learned that the Bilgewater goblins of the Horde survived a crash on an uncharted island near Kalimdor before arriving in Durotar. We initially came here to investigate what techniques and technology could possibly allow a hopeless pack of imbeciles to survive such harsh conditions.\n\nWhile the goblins are at a loss, we still need to find out exactly what happened here. Search the beach for wreckage and belongings and bring anything that appears significant back to me.", objectives = "" }
WordHunterWoW_QuestEN[25063] = { title = "Terrapination", description = "We need to obtain the object described in this journal, for certain. Extracting it from a chest would be a feasible matter, but the object itself sounds compromised, and unstable. Attempting to forcefully open the chest could be disastrous.\n\nFortunately, we know where the key is...statistically speaking, at least. There's plenty of sea turtles at the east end of this beach. One of them may hold the key.", objectives = "" }
WordHunterWoW_QuestEN[25064] = { title = "Moraya", description = "Moraya has been lookin' for some help with tha raptors. Ya should talk to her on the other side of Darkspear Hold when ya get a chance.", objectives = "" }
WordHunterWoW_QuestEN[25065] = { title = "You Too, Brute?", description = "It's time to conclude this matter efficiently. From what we've determined, this mysterious object is in the possession of the \"smart\" brute described in the journal. We don't know exactly what's happened to this creature, obviously, so you should take caution.\n\nThis... \"Meatface\" is hiding in the hills, near where these goblins bury their dead. Look for the graveyard and he should be just past it.", objectives = "" }
WordHunterWoW_QuestEN[25066] = { title = "The Pride of Kezan", description = "This is ridiculous! Those gnomes just don't know when to stop!\n\nGoblin pride is on the line here! {name}, you gotta jump into the Pride of Kezan and show them what's what!\n\nLet me know when you're ready!", objectives = "" }
WordHunterWoW_QuestEN[25067] = { title = "Thunderdrome: The Ginormus!", description = "The rules are simple: Two men enter, one--wait. Sometimes there's women.\n\nTwo people enter, one--Wait, no, sometimes it's more than two...and that means more than two come out--\n\nAlright, only rule is stay in the drome! There are no other rules!\n\nYou're up against the biggest, baddest member of the Wastewander Bandits first. This'll either be a warmup or a bloodbath...it's up to you which!", objectives = "" }
WordHunterWoW_QuestEN[25068] = { title = "The Crumbling Past", description = "The creatures wandering these ruins are Earthen, the ancient ancestors of dwarves, made by the Titans to shape the world itself.\n\nThe original Earthen broke down and went awry thousands of years ago, and these freshly uncovered ones seem no different. We may as well make use of these confused and unstable constructs.\n\nEnter the ruins and destroy the Earthen, and collect the jewels embedded in them; their magical energies will be both valuable and worthy of study.", objectives = "" }
WordHunterWoW_QuestEN[25069] = { title = "The Secrets of Uldum", description = "We are ready to enter the antechamber itself, {name}. This is a momentous occasion.\n\nFrom the writings you've brought us, I believe these ruins were in fact once the grand entrance to Uldum itself. The quakes that ripped its doors open have probably collapsed the tunnels, but we may yet find amazing things hidden within.\n\nSearch the ruins for anything intact that may be studied.  The thrill of discovery awaits!", objectives = "" }
WordHunterWoW_QuestEN[25070] = { title = "What Lies Within", description = "As you lay your hand upon the chest, a faint rumbling can be heard. The sound of grinding movement echoes behind you as the chest begins to shut itself.\n\nSomething is approaching!", objectives = "" }
WordHunterWoW_QuestEN[25072] = { title = "A Few Good Goblins", description = "We haven't just been camped here singin' songs with gnomes and playing with dangerous machinery, you know. My men have been trying to clear this hive out for a week now! Problem is, we've taken so many losses by now that the bugs have the advantage.\n\nLucky for us, the bugs either don't like to eat goblins, or they like us so much they save us as treats, because nearly all my men are still cocooned up out there. I need you to go save 'em.", objectives = "" }
WordHunterWoW_QuestEN[25073] = { title = "Sen'jin Village", description = "You've be doin' quite well for one so young. I've no doubts you'll be makin' quite da name for yarself.\n\nGo now, northwest, across da shallows ta Sen'jin Village. Dere you'll be meetin' Master Gadrin. He'll likely have a task or two for ya before ya truly make ya way out into the Durotar wilds.\n\nPlease remember, {name}, we may disagree wit' the young Hellscream at times, but his intentions are noble, and it be very important that we remain united as one Horde. Make da Darkspear proud.", objectives = "" }
WordHunterWoW_QuestEN[25074] = { title = "Meet Me at Triumph", description = "Thanks in part to your efforts, we've stabilized the situation here. We need to turn our attention south, to Fort Triumph.\n\nFort Triumph is the keystone of our operation in the Barrens - the vital land-link between Northwatch and Theramore.\n\nI'll pack up and head out separately. Report to Commander Roberts at the fortress and I will see you there soon. Together, we will secure the frontier!", objectives = "" }
WordHunterWoW_QuestEN[25075] = { title = "Pick-a-Part", description = "These bulky dwarven siege engines aren't cut out for the close-quarters fighting of the Battlescar.\n\nI've got some new designs I'd like to try out, but first I'm going to need some spare parts. There's plenty of wreckage sitting in the Battlescar. All I need is an enterprising {class} to haul it back for me.\n\nThat's you, {name}. I'm talking about you.", objectives = "" }
WordHunterWoW_QuestEN[25079] = { title = "Powder Play", description = "Our shipments of saltpeter from Dustwallow have been held up, which means we can't manufacture our own gunpowder here.\n\nBut I can retrofit our armaments to use goblin Blast-O powder. It's unstable, dangerous, toxic to the skin, and harmful if swallowed... but I think I can make it work!\n\nGet me a keg of the stuff by attacking one of those goblin sapper specialists who've been storming our walls.", objectives = "" }
WordHunterWoW_QuestEN[25080] = { title = "Batteries Not Yet Included", description = "Okay! Using the spare parts you've found for me, I've got a framework roughed out for my versatile new assault vehicle. All I need now is a compact power supply.\n\nI've noticed that the indigenous wildlife here packs quite the punch, electrostatically speaking. Can you hunt down Thunderheads near the base here and get me an intact electrogizard? It might take a few kills to find a usable gland.", objectives = "" }
WordHunterWoW_QuestEN[25081] = { title = "Claim the Battlescar", description = "The Horde has fought us to a standstill from their stronghold west of here. The fighting continues, even as the land breaks open under our feet.\n\nSomeone's got to break the stalemate! I need you to venture into the Battlescar and help my men crush the Horde opposition there.\n\nIn the center of the scar you will find a flag marker designating who controls the area. Scout out the flag. It'll be worth your while to claim the scar for the Alliance if someone hasn't already done so.", objectives = "" }
WordHunterWoW_QuestEN[25082] = { title = "Working the Bugs Out", description = "Why high command decided that a silithid mound was the ideal place to build a fortress, I'll never know. Them lil' buggers are tunneling under our fortifications and setting back our timetables. We need to scorch 'em out!\n\nTake this here bucket of burning pitch and dump it on the silithid mounds right outside the main gate. They look like big piles of sand. Kill anything that comes out, but be careful, {name} - them nasties are likely to swarm you when you light those mounds up.", objectives = "" }
WordHunterWoW_QuestEN[25084] = { title = "A Growing Threat", description = "A moment there, {class}.\n\nWe've got more problems here than just the end of the world as we know it. Our vigil here's threatened by the quilboar. We've been content to leave them be when they stay in the Kraul, sure, but every day they press further and further out towards our camp.\n\nMahka, bless her green heart, wouldn't ever forgive me if I went out bashing heads in myself, but if you could help drive back those that're wandering near the camp, I'd appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[25085] = { title = "Mangletooth", description = "Una here used to spend time in Camp Taurajo. She's told me about a quilboar that used to be captured there, named Mangletooth. Quite the clever one, for a quilboar.\n\nI've been tryin' to think what got these quilboar riled up so much recently, and it might be that Mangletooth escaped Taurajo alive. If he has, he's certainly calling the shots.\n\nThere's a large hut up in the hills to the northwest. If you find Mangletooth there, cut 'im down.", objectives = "" }
WordHunterWoW_QuestEN[25086] = { title = "Firestone Point", description = "Can you do me a huge favor, {name}? My sister-in-law's uncle is in the Earthen Ring, and he's here in the Barrens studying the impact of the Cataclysm, down at Firestone Point. He says their camp is surrounded by quilboar and I worry that they might get overrun.\n\nCan you check in on Dorn Redearth for me? I'd hate for anything to happen to him, what with the close family bond and all. ", objectives = "" }
WordHunterWoW_QuestEN[25087] = { title = "Report to Twinbraid", description = "The Alliance owes a debt to the dwarves of Bael Modan, who built some of our earliest fortifications in the Barrens.\n\nTheir commander, General Twinbraid, is a real stalwart. One of our best. He's on patrol south of here, keeping the Horde on their toes.\n\nI definitely want to keep him appraised of the situation here so we can coordinate our next move. Can you deliver this frontline report to him in the field? ", objectives = "" }
WordHunterWoW_QuestEN[25089] = { title = "Beyond the Graves", description = "Darnell tells me that the two of you have already met.  That's good, because I'm sending you both into Deathknell.  Your work is done here.\n\nSpeak with Deathguard Saltain in Deathknell, to the north.  He will tell you more of what you must know.", objectives = "" }
WordHunterWoW_QuestEN[25090] = { title = "A Putrid Task", description = "Scourge have trickled into Tirisfal Glades and have infested this area.\n\nI need someone to beat back the rotting dead and ravaged corpses that have taken this small farm.  Scatter their bones and bring back their putrid claws.  The Deathguards will reward you.", objectives = "" }
WordHunterWoW_QuestEN[25091] = { title = "Sandsorrow Watch", description = "If you're looking for more work, I've got a line for you.\n\n I know an elf by the name of Trenton Lighthammer who's been obsessed with the sand trolls near here for years. He's dead-set on finding some kind of mythical sword made by them, and just a while ago he finally got a crew together to go to Sandsorrow Watch and look for it.\n\nLast I heard, they kicked the trolls out of one of their camps and set up shop there. Look for it to the west, near Zul'Farrak.", objectives = "" }
WordHunterWoW_QuestEN[25093] = { title = "The Heads of the SI:7", description = "These orcs were murdered in cold-blood by the Alliance down on the coast. We did nothing to provoke them.\n\nTheir deaths should not be in vain, {name}. Will you bring them justice?\n\n<Aggra appears as if she can barely contain her rage.>\n\nThere are three SI:7 leaders down there along the beach. Bring me each of their heads.", objectives = "" }
WordHunterWoW_QuestEN[25094] = { title = "Thunderdrome: Zumonga!", description = "Splendidly done! But you'll be fighting more than mere humans!\n\nYour next opponent's a mean one...watch out for his right hook. And his left. I'd be wary of his fists in general.", objectives = "" }
WordHunterWoW_QuestEN[25095] = { title = "Thunderdrome: Sarinexx!", description = "I hope you're ready for the next one, {name}. One mistake could mean instant, painful death! But that's what the people pay to see, isn't it?\n\nI hope you're not afraid of bugs...", objectives = "" }
WordHunterWoW_QuestEN[25098] = { title = "The Warchief Wants You", description = "True to his word, Thrall is going to get us going in the right direction to rescue our people. He asked to speak with you.\n\nGood luck, {name}. We're all depending on you.", objectives = "" }
WordHunterWoW_QuestEN[25099] = { title = "Borrow Bastia", description = "Head back down to the coast and tell Kilag that I'd like for you to borrow Bastia. The panther knows the way to where your friends are being held captive.\n\nGo now. I will see you again before we make our move against the Trade Prince.", objectives = "" }
WordHunterWoW_QuestEN[25100] = { title = "Let's Ride", description = "Bastia will make sure that you get to where you need to go, goblin.", objectives = "" }
WordHunterWoW_QuestEN[25102] = { title = "No Bull", description = "Twinbraid's patrols always throw us right into the thick of danger. If it's not Horde ambushes, it's a quilboar hit-and-run.\n\nThe problem is them lousy landquaker kodos. Big walkin' walls of fur, shakin' the ground... We can't see or hear an ambush creepin' up on our backside.\n\nGo scare 'em off from our patrol, here. Killing a few should drive the herd south and out of what's left of me hair.", objectives = "" }
WordHunterWoW_QuestEN[25103] = { title = "Bootlegger Outpost", description = "We've done a bang up job here. I'm gonna make sure these mooks finish properly and then head back to Gadgetzan for a bit.\n\nIf you want to keep making a good impression on our Steamwheedle friends, or just make more money, you should head southwest of here. Bootlegger Outpost is set up on the edge of the gaping chasm.\n\nTalk to Zeke Bootscuff. I'd bet good money he'll need help.", objectives = "" }
WordHunterWoW_QuestEN[25104] = { title = "Digsite Status", description = "The patrol's been quiet today. And that's got me worried, {name}.\n\nEver since the Alliance sacked Taurajo, none of our positions are secure. You look like you can handle yourself - can you scout around for me?\n\nCheck in with my son Marley outside the Bael Modan excavation, southeast of here. The site's exposed and susceptible to raids, and my son's too proud to signal for help if he needs it.", objectives = "" }
WordHunterWoW_QuestEN[25105] = { title = "Nibbler!  No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", objectives = "" }
WordHunterWoW_QuestEN[25106] = { title = "Hands Off Me Dig!", description = "Look at the chaos down there, {name}! I've instructed the foremen to save what artifacts they can. Who knows what treasures these tauren animals are like to make off with.\n\nCan you help get a handle on things? Kill the raiders and save what artifacts you can.\n\nWhile you're at it, look for my missing tools. A few quick repairs and I can get this flying machine up and running again.", objectives = "" }
WordHunterWoW_QuestEN[25107] = { title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Andoren would probably like to see this.", objectives = "" }
WordHunterWoW_QuestEN[25108] = { title = "Feegly the Exiled", description = "Saddest story I ever heard told, {name}. Feegly was one of our fastest diggers, until he got a hold of that - thing. \"The Tear of the Moons\" we called it. It changed him. Remade him. I wish it had stayed buried.\n\nFeegly was banished from Bael Modan but I've heard reports he's come sniffing around the dig site again. He's suffered enough, the wretched thing. If you find him down there, put ol' Feegly out of his misery.", objectives = "" }
WordHunterWoW_QuestEN[25109] = { title = "The Gallywix Labor Mine", description = "We barely escaped with our hides intact!\n\nThe Trade Prince has a whole bunch of us enslaved and performing manual labor inside the cavern.\n\nGreely helped the seven of us to get out, but she was recaptured in the process.\n\n{name}, you're the only one crazy enough to walk into an exploding volcano! The assistant will be able to help you free the others.\n\nHurry! This place is about to blow for good!", objectives = "" }
WordHunterWoW_QuestEN[25110] = { title = "Kaja'Cola Gives You IDEAS! (TM)", description = "Assistant Greely is clearly bewildered and intimidated. How will she help you to find a way to rescue everyone in this condition?\n\nMaybe if she were to drink one of those Kaja'Cola Zero-One drinks you saw, she'd be able to have a bright idea?", objectives = "" }
WordHunterWoW_QuestEN[25111] = { title = "Scavengers Scavenged", description = "Now that I know you're not squeamish, I've got another job for you. Have you seen the red-feathered birds swarming around the bones out there? Those are fire rocs. They'll light you up good if you're not careful.\n\nThey're also pretty darn valuable thanks to their unique anatomy. Most of the hunters loafing around here aren't up to the task of killing fire-spitting buzzards for money... think you can handle it?", objectives = "" }
WordHunterWoW_QuestEN[25112] = { title = "Butcherbot", description = "I make my money around here selling animal parts. I've been perfecting a foolproof method of maximizing profit: The butcherbot!\n\nThese little guys are programmed to harvest every scrap of usable material from the wildlife around here, on a case-by-case basis. He does all the work, and best of all, only I know how to get the goods back out of him.\n\nIf you're interested in making some coin, take one of these guys for a spin. I need some glasshide basilisk parts; you'll find a bunch of them to the south.", objectives = "" }
WordHunterWoW_QuestEN[25115] = { title = "Blisterpaw Butchery", description = "The hyenas wandering the wastes here might look scrawny, but they've got some of the strongest jaws you'll find! If you're not careful, they'll take a leg off in one bite. That kind of bone strength is a valuable resource, my friend, just waiting to find a buyer!\n\nTake one of my Butcherbots with you. Jaw separation isn't an easy task, and this little guy has been set up to know exactly what to do. Just bring him back when he's full.", objectives = "" }
WordHunterWoW_QuestEN[25118] = { title = "Looking for Lurkers", description = "I don't know about you, but I'm not much a fan of spiders, much less the kind that come bigger than me. Loch Modan's a gorgeous place, but I'd say it could do without those horrid things waltzing around.\n\nTell you what, I've got some spare coin, and you look like a tough one. If you head out and off some of those things for me, I'll pay you for your time.", objectives = "" }
WordHunterWoW_QuestEN[25120] = { title = "Marley's Final Flight", description = "Okay, {name}! Let's take these artifacts to my father and give him our report firsthand.\n\nThanks to your help my flying machine is ready to roll. We can fly there together and share in the glory.\n\nTalk to me when you're all set to move out!", objectives = "" }
WordHunterWoW_QuestEN[25121] = { title = "Momentum", description = "It looks like we've got more work to do! Having Mr. Noggenfogger ask us to take care of the rest of the pirates is a true honor.\n\nSince you've been SO helpful, why don't you meet me at Lost Rigger Cove? I've just got to slip into something a bit more comfortable, so don't wait on me. I'll beat you there, promise!", objectives = "" }
WordHunterWoW_QuestEN[25122] = { title = "Morale Boost", description = "You've got to get all the Kaja'Cola Zero-One that you can and make the goblins drink it to boost their morale and free them!", objectives = "" }
WordHunterWoW_QuestEN[25123] = { title = "Throw It On the Ground!", description = "This nightmare will never be over while Blastshadow the Brutemaster still breathes. There are a couple of problems though.\n\nOne, being a warlock, he's got a succubus named Delicia Whipsnaps. If you kill Blastshadow quickly, the demon will go back to where it was summoned from.\n\nThe second problem, since Blastshadow is a warlock, he has a soulstone that allows him to resurrect. You have to get his soulstone and destroy it so that he'll be dead forever!", objectives = "" }
WordHunterWoW_QuestEN[25125] = { title = "Light at the End of the Tunnel", description = "Okay, we have got to get out of here before she blows for good!\n\nLet's head out the other end of the tunnel on the north side of the mine. We should be able to use one of the mine carts for a quick ride down the side of the volcano.", objectives = "" }
WordHunterWoW_QuestEN[25126] = { title = "Cutting Teeth", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you'll be of more use to us slaughtering the boars you'll find in the farms to the north and northeast of here.", objectives = "" }
WordHunterWoW_QuestEN[25127] = { title = "Sting of the Scorpid", description = "I must send you back into the fields again, {class}. You will find large numbers of scorpids northwest of here. Bring me eight of their tails.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", objectives = "" }
WordHunterWoW_QuestEN[25128] = { title = "Hana'zua", description = "Hey mon, take a knee and hear me out. We got a problem.\n\nA good friend of mine, Hana'zua, has gone out into the valley and he hasn't returned. Last I seen, he was headin' north, where the scorpids hunt. Maybe you go take a look for him? The spirits be tellin' me that he's not well.", objectives = "" }
WordHunterWoW_QuestEN[25129] = { title = "Sarkoth", description = "{class}! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", objectives = "" }
WordHunterWoW_QuestEN[25130] = { title = "Back to the Den", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to our settlement unassisted. Please, {name}, return and tell Gornek of my situation. Perhaps he can help me.", objectives = "" }
WordHunterWoW_QuestEN[25131] = { title = "Vile Familiars", description = "I trust the Valley of Trials will teach you much, young {class}.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nOne of the Burning Blade - a foul, demon-worshipping cult - has made camp here in the Valley of Trials. He skulks in a cave to the north, and his vile familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", objectives = "" }
WordHunterWoW_QuestEN[25132] = { title = "Burning Blade Medallion", description = "Through my divinations, I see that an item of power--a medallion--hides deep within the Burning Blade Coven, guarded by beasts and black magic. We must have it.\n\nFor too long these demon-worshippers have defiled our homelands. Cleanse the coven of its demonic taint by slaying the fel beasts and their leader. Return with this medallion as proof of your deed.\n\nGo, {name}. You will find the coven in a cave to the north.", objectives = "" }
WordHunterWoW_QuestEN[25133] = { title = "Report to Sen'jin Village", description = "Your trials against the Burning Blade are finished... here in the Valley. But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin. Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials. Discover from him if they have yet reached Sen'jin.\n\nGo, {name}, and be swift. I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", objectives = "" }
WordHunterWoW_QuestEN[25135] = { title = "Thazz'ril's Pick", description = "{name}, you are a dependable {race}. Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind. When I later returned to retrieve it I found the cave was filled with vicious beasts! Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls. My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", objectives = "" }
WordHunterWoW_QuestEN[25136] = { title = "Galgar's Cactus Apple Surprise", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, {name}. If you bring me six cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", objectives = "" }
WordHunterWoW_QuestEN[25151] = { title = "He Needs Ale!", description = "<Marley grasps the side of your head with a shaking, bloody hand.>\n\nAle... Must... have ale...\n\nOl' Barkerstout from inside. <He coughs.> That should ... do the trick.", objectives = "" }
WordHunterWoW_QuestEN[25152] = { title = "Your Place In The World", description = "Finally, you are of age, {name}... of age to battle in the name of the Horde. To conquer for the glory of the Warchief.\n\nYes...\n\n<Kaltunk looks you over.>\n\nYou will do nicely.\n\nNo doubt you wish to find a great dragon or demon and strangle it with your bare hands, but perhaps it would be wise to start on something less... dangerous.\n\n<Kaltunk laughs.>\n\nReport to Gornek, he should be able to assign a task better suited to a young {class}. You will find him seated at the fire behind me.", objectives = "" }
WordHunterWoW_QuestEN[25153] = { title = "Bael'dun Rescue", description = "Help - Help! You've got to do something!\n\nSome dwarves are still inside - so many - they're trapped in the debris. Buried alive. The flames! It's a nightmare in there. We don't know how much longer until the roof collapses...\n\nPlease, {class}, you've got to save them!\n\nRun inside. Use the emergency fire valves to protect yourself from the flames. You're the only hope they have...", objectives = "" }
WordHunterWoW_QuestEN[25154] = { title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Curver last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Curver didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", objectives = "" }
WordHunterWoW_QuestEN[25155] = { title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", objectives = "" }
WordHunterWoW_QuestEN[25156] = { title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Barnsworth Elemental Glue!  The professor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", objectives = "" }
WordHunterWoW_QuestEN[25157] = { title = "The Latest Fashion!", description = "Professor Barnsworth has been working on this new stardust - what with the fashion in Stormwind this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some humanoid testing - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on some humanoid subjects.", objectives = "" }
WordHunterWoW_QuestEN[25158] = { title = "Nibbler!  No!", description = "Lila's pet Nibbler got into my workshop again!\n\nI was making a bracelet, to be delivered today.  The work was almost done, except for the gems.  I spent all night cutting them, but when I stepped out for a bit of breakfast, the little beast came into my workshop and swallowed every gem in sight!  The thing can digest ANYTHING, and trust me, you'd break your back trying to pick up its leavings.\n\nI need to get replacement gems fast; the courier is coming in tonight.  Help!", objectives = "" }
WordHunterWoW_QuestEN[25159] = { title = "The Latest Fashion!", description = "Dr. Vernstrom has been working on this new stardust - what with the fashion in Orgrimmar this season being about all things sparkly, I'm sure if we can get it to the market it will be all the rage!  The Jewelcrafter's Association, however, won't let us market it until we've completed some \"live testing\" - something about tinkering with magical dust being dangerous or some such nonsense.  Well, I suppose we need to humor them.  Take this bag and test out Stardust No. 2 on humanoid subjects.", objectives = "" }
WordHunterWoW_QuestEN[25160] = { title = "A Present for Lila", description = "I'm trying to impress this trade ship captain Lila.  I've been working on a necklace to match her lovely purple hair, but the gems have gone missing!  They were there when I was showing them off to my good friend Bonder last evening.  We were drinking moonshine and I blacked out - when I woke up the gems were gone!  They must have been darn good thieves, because Bonder didn't see anything.\n\nHer ship is coming in tonight, and I really need three nightstones to get her present done.  Help me out here!", objectives = "" }
WordHunterWoW_QuestEN[25161] = { title = "Ogrezonians in the Mood", description = "I was supposed to receive a shipment of jasper from Azeroth Express, but I just heard their ship crashed into some tiny island called Ogrezonia.  I worry about the crew, as the giant female ogres on the island are rumored to perform horrible rituals on men who happen upon their island.  My work must go on, though, and we need those gems.  I've heard great things about your skill as a jewelcrafter - could you deliver three jagged jaspers by the end of the day?", objectives = "" }
WordHunterWoW_QuestEN[25162] = { title = "Elemental Goo", description = "Instead of using the tired old method of setting gems into rings and such, I use an innovative new method.  I simply glue on the gems with Vernstrom Elemental Glue!  The doctor needs more elemental goo for another batch, though, and I have a whole bunch of setting to do.  Can you go get me some?", objectives = "" }
WordHunterWoW_QuestEN[25163] = { title = "Who Did This?", description = "Sabotage! It had to be. The whole fortress magazine exploded. The Horde must've gotten someone inside...\n\n{class}, if you've the stones to rush into that burning nightmare... look for some clues as to who did this to us. The General will want to know! Look for a Horde corpse in the wreckage and get to the bottom of this disaster...", objectives = "" }
WordHunterWoW_QuestEN[25164] = { title = "Backed Into a Corner", description = "The naga are upon us, {class}. Aid us in fightin' dem off!", objectives = "" }
WordHunterWoW_QuestEN[25165] = { title = "Never Trust a Big Barb and a Smile", description = "Next, we gonna get some poison from the scorpions that be runnin' around here.  But don't you worry, Bom'bay's not gonna let you get hurt!\n\nBom'bay's got a big totem that you gonna stick in the ground when the scorpion strikes.  The totem gonna suck up all the poison, and you gonna walk away still breathing.  Sound good?", objectives = "" }
WordHunterWoW_QuestEN[25166] = { title = "Captain Dreadbeard", description = "This is getting pretty fun, but let's not forget we're here for Gnomeregan!\n\nWe spotted the captain of the Southsea over on one of his boats to the south, past where all the fighting is. He's all alone on his little boat, undefended!\n\nIf you go take care of him, we'll have the rest of these pirates mopped up in no time.", objectives = "" }
WordHunterWoW_QuestEN[25167] = { title = "Breaking the Chain", description = "Aw man, this ain't good.  Not one bit, mon.\n\nThrall's off to sea, Vol'jin's taking care of business in Echo Isles, and old Master Gadrin is left behind to take care of Sen'jin.  And then what happens?  Those humans come outta Northwatch Hold and set up camp in our backyard!\n\nLucky for us, they just got here, and they're still setting up their base.  You can help out old Gadrin by destroying those big supply crates they carry, and by killing the laborers carryin' them. You'll find'm to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[25168] = { title = "Purge the Valley", description = "Northwatch is a highly-defended stronghold southwest of here, across the harbor.  It's a strategically-located stronghold that the Horde still struggles to overtake.  We don't need the humans setting up another Northwatch here in Durotar.\n\nSweep through the valley to the west and slay these humans, {name}.  Let them know the power and the fury of Sen'jin.", objectives = "" }
WordHunterWoW_QuestEN[25169] = { title = "The War of Northwatch Aggression", description = "These humans in the west, they don't just wanna camp out in Durotar, mon.  They got bigger plans, and those plans involve takin' our home and leavin' our skulls on pikes.\n\nWell I'm not havin' it.  Nope!  Not Lar!  I've got family here in Sen'jin, and I'll be damned if I let one of those brutes put my Tai'tasi's head on a stick!\n\nThey've got their plans written down in there, mon.  Big scrolls, real important-lookin'.  We gonna burn those scrolls before they burn us.", objectives = "" }
WordHunterWoW_QuestEN[25170] = { title = "Cleaning Up the Coastline", description = "Heya mon!  Bom'bay be workin' on some new mojo.  You wanna try a piece of it?  Well, before ya do, Bom'bay's gonna need ya to pick up some jujus.\n\nFirst, Bom'bay needs ya to get some o' the goop from the crabs down by the water.  Let me see your hands!\n\n<Bom'bay examines your hands closely.>\n\nBom'bay gonna need 5 handfuls.  Go on now!", objectives = "" }
WordHunterWoW_QuestEN[25171] = { title = "Riding On", description = "We gotta pass the word on to Razor Hill.  These humans may be defeated today, but tomorrow they'll come again, and when they do, we'll need help from the orcs.\n\nSpeak with Jhash, outside the gates of Sen'jin.  He'll give you a ride to Razor Hill.  His wolves know the path well.", objectives = "" }
WordHunterWoW_QuestEN[25172] = { title = "Invaders in Our Home", description = "You're not just another grunt - you seem to be a serious {class}. Good, because that's exactly what I need.\n\nTry not to let the word out, since I don't want to cause a panic... but there have been reports of more humans nearby. This is an egregious betrayal of the peace that we negotiated with that miserable Jaina Proudmoore! We can't allow humans here in Durotar, and especially not here in the Valley.\n\nYou will find them to the south. Slay them quickly, before their numbers increase any more.", objectives = "" }
WordHunterWoW_QuestEN[25173] = { title = "From Bad to Worse", description = "Tiragarde Keep lies to the southeast of here, on Durotar's eastern shore.  You probably passed it on your trip from Sen'jin Village.  This castle has been a thorn in my side for too long.\n\nHumans from Kul Tiras lived in the castle for years, thwarting my every attempt to crush them.  When the cataclysm hit us, the shore was wiped out, along with the castle and all the humans.  However, these upstarts from Northwatch have moved in to take their place!\n\n<Gar'Thok roars in aggravation.>", objectives = "" }
WordHunterWoW_QuestEN[25174] = { title = "Twinbraid Needs to Know", description = "<General Twinbraid will want to know the details of this cowardly attack. You gather up the evidence.>", objectives = "" }
WordHunterWoW_QuestEN[25175] = { title = "The Bad News", description = "<You gently close Marley's eyes.>\n\n<Someone is going to have to tell General Twinbraid that the Horde has killed his only son.>\n\n<That someone is you.>", objectives = "" }
WordHunterWoW_QuestEN[25176] = { title = "Exploiting the Situation", description = "Hey there, handsome!  I've had my eye on those big, beefy biceps ever since you stepped into town.\n\nListen, I've got something for you to do.  I hear Gar'Thok's got you headed over to Tiragarde.  While you're there, think you could find some abandoned Kul Tiras knicknacks?\n\nThanks sweetie!", objectives = "" }
WordHunterWoW_QuestEN[25177] = { title = "Storming the Beaches", description = "Now that those humans are out of our hair for a bit, we can move on to more pressing matters.\n\nThe cataclysm utterly decimated Durotar's eastern coast.  You saw the wreckage that it made of Tiragarde.  The devastation was even worse on the coast to the east of here.\n\nAfter the first wave, the beach was overtaken by angry elementals that came from the sea.  I sent grunts to take care of it, but the onslaught was too much.  I'm guessing you'll have a little more luck than they did.\n\nBeware the tides!", objectives = "" }
WordHunterWoW_QuestEN[25178] = { title = "Shipwreck Searching", description = "Hey handsome, welcome back!  You wouldn't mind running another errand, would you?  I'd be EVER so grateful...\n\nI hear you're headed off to the shore east of here.  The beach is filled with crashed ships, and those ships have gnomish tools in them... tools that I can use.\n\nSee you soon, beefcake!", objectives = "" }
WordHunterWoW_QuestEN[25179] = { title = "Loss Reduction", description = "You've got to help us.  The elementals... they're stronger than they look, and they come in waves.  They took us completely by surprise, and we were overcome.\n\nMany of my fellow grunts lay dying on the beach.  If you could save them... I would be grateful, as would Gar'Thok back in Razor Hill.", objectives = "" }
WordHunterWoW_QuestEN[25180] = { title = "Tablets of the Earth", description = "Some time ago, Brann sent King Magni an urgent message from Ulduar. He said he'd found an ancient titan cache with mysterious and important relics. King Wrynn dispatched one of his fastest ships to Northrend to transport the courier. I was to meet him here and examine the tablets, but the courier is nowhere to be seen.\n\nMagni is worried, {name}. I haven't heard anything about the courier's arrival. Would you be willing to travel to Stormwind Harbor and see if he's arrived?", objectives = "" }
WordHunterWoW_QuestEN[25181] = { title = "Tablets of Fire", description = "I'm expecting the arrival of a courier traveling from Northrend. He's carrying a collection of ancient titan treasures, ones I'm hoping will shed light on my troubling visions. The shaman should've arrived on one of the recent zeppelin flights and I'm starting to get worried.\n\nHe was to meet me by the zeppelin tower southwest of Orgrimmar's gates, but I don't want to miss my audience with the warchief. Would you be willing to look for the courier and see what's delaying him?", objectives = "" }
WordHunterWoW_QuestEN[25182] = { title = "Kill 'em All!", description = "I want to see some dead goblins, {name}! Just west of here you'll find a whole warren of those little insects burrowing into the mountain.\n\nLet's see to it that they're digging their grave.\n\nDestroy them. Lay waste to their whole grubby operation. They've sown their own demise in Bael'dun, {class}, and it is time to meet the reaper. ", objectives = "" }
WordHunterWoW_QuestEN[25183] = { title = "...And Bury the Rest", description = "It's not enough to kill 'em - after Bael'dun, I want to give those goblins a taste of their own.\n\nGo into Frazzlecraz's mine and arm a pile of the explosives inside.\n\nAt the entrance to the mine you should see some sort of switch or plunger. Once the explosives are armed, use the plunger to blow that place sky-high. Put the fear in 'em, {class}! ", objectives = "" }
WordHunterWoW_QuestEN[25184] = { title = "Wild Mine Cart Ride", description = "All you have to do is jump in and speak with Assistant Greely when you get to the bottom.", objectives = "" }
WordHunterWoW_QuestEN[25185] = { title = "The Deed Is Done", description = "<You shield your eyes from the blast and the debris as the mine implodes onto itself.>\n\n<General Twinbraid will be pleased, but somehow you doubt it'll be enough to quench his thirst for vengeance.>", objectives = "" }
WordHunterWoW_QuestEN[25186] = { title = "Futile Resistance", description = "{name}, I certainly don't want to deliver my report to Commander Singleton without at least a little bit of good news. We've got to wrestle control of these roads back from these Horde holdouts.\n\nFrom what we can gather, Kona Thunderwalk is the name of the ringleader. He's got a camp just north of here. A Stonetalon native, he knows these roads better than his own hide. If we can wipe him out, resistance from the west might vanish.\n\nFind and kill Kona Thunderwalk, then report to Commander Singleton!", objectives = "" }
WordHunterWoW_QuestEN[25187] = { title = "Lost in the Floods", description = "The recent cataclysmic events have done more than wash a few boats onto our shore, {class}.  The Southfury River has overflowed, and Durotar's entire western basin is now flooded.\n\nThere are still people out there.  I've been searching for a while, but haven't been able to find anything.  Would you mind using my telescope and taking a look for yourself?", objectives = "" }
WordHunterWoW_QuestEN[25188] = { title = "Watershed Patrol", description = "My post is here on the tower, {name}, and I cannot leave it.  I need someone to go out there and help the people who are still trapped in the river's overflow.\n\nCan I count on you?", objectives = "" }
WordHunterWoW_QuestEN[25190] = { title = "Raggaran's Rage", description = "The quilboar are a stain on the land that not even the river can wash away.  They told me to evacuate, but I told them that my job was not yet done.\n\nHrrrraaagh!  I hate quilboar so much!  Will you help me kill them?", objectives = "" }
WordHunterWoW_QuestEN[25191] = { title = "Survey the Destruction", description = "I had heard of enormous seismic anomalies here in Kalimdor, but I had no inkling that the geological chaos would be so profound!\n\nI need an up-to-date survey of the destruction while I stay here to study the seismographic readings. Could you gather some data via my automated survey craft? I'll take care of all the flying.\n\nWhen the survey is complete, present the data to my colleague Horton Gimbleheart in Northwatch.", objectives = "" }
WordHunterWoW_QuestEN[25192] = { title = "Raggaran's Fury", description = "I will not rest until they're defeated!  Slay them all!\n\n<Raggaran catches his breath.>\n\nTheir stinking lairs are to the north, or to the southwest!  ", objectives = "" }
WordHunterWoW_QuestEN[25193] = { title = "Lost But Not Forgotten", description = "Today marks the anniversary of my son Kron's passing.  As long as I refused to admit it, I recognize now: Kron is not returning from his crocolisk hunt.\n\nI've been working on a project... something that will memorialize Kron's passion for the hunt.  It's a crocolisk-tooth necklace... rows and rows of teeth, suitable to be worn by only the bravest young orc.  I will place it on his grave.\n\nKron was brave, but he was not strong, like you.  Will you bring me the teeth for my necklace?", objectives = "" }
WordHunterWoW_QuestEN[25194] = { title = "Unbidden Visitors", description = "Don' worry, Zen'Taji's not in any trouble.  He just been studyin' what happens when the river overflows.\n\nYa see the big tall birds that stand on the riverbank?  Zen'Taji thinks they're in trouble.  The earthquake and the flood pushed the plainstriders over to this side of the water, but they can't fly back, and they're too scared to swim.\n\nThey'll die if they stay here.  Zen'Taji doesn't like violence, but maybe YOU can attack them and scare them over to the other side.  Yes?", objectives = "" }
WordHunterWoW_QuestEN[25195] = { title = "That's the End of That Raptor", description = "Many creatures died when the water came rushin' into the valley.  The raptors, however, thrived.  They're clever predators, and they've been living off the misfortune of the other creatures.\n\nOne of the raptors is particularly cruel.  He's killing the little animals and letting them rot in the water without even eating them!  He goes by the name of Screamslash, and if we're not careful, he could seriously disrupt the balance of nature.\n\nTravel north, slay him, and give his body back to nature.", objectives = "" }
WordHunterWoW_QuestEN[25196] = { title = "The Dranosh'ar Blockade", description = "You should head north from here, {name}.  Speak with Gor the Enforcer at the Dranosh'ar Blockade.  He's been placed in charge of securing shipping lanes for Orgrimmar, and Skull Rock sits right next to his precious dock.  I'm certain he'll be interested in picking up where we left off.", objectives = "" }
WordHunterWoW_QuestEN[25197] = { title = "The Admiral Won't Back Down", description = "What? You want to stay here to fight? Typical {class}, wanting to stay and fight off the Horde while there's still a chance to run for it.\n\nLook, if you really want to save Northwatch, you should report to Admiral Aubrey in the tower behind me. He's keeping his ships here to fight, instead of ferrying us all away like I begged him to.\n\nNow if you'll excuse me, I've got to finish packing!", objectives = "" }
WordHunterWoW_QuestEN[25198] = { title = "Winnoa Pineforest", description = "While we've accomplished much here, it would be a tragedy if part of this corruption has escaped our notice.  The corridors of the Wailing Cavern stretch throughout the entire Barrens, and if another spot of wild energy has made its way to the surface...\n\nYou've done enough for me, though. I would simply ask that you let a fellow druid of mine know of what's happened here. You will find Winnoa Pineforest at the Fields of Blood, southwest of here.", objectives = "" }
WordHunterWoW_QuestEN[25199] = { title = "Basic Orders", description = "Hey! You look like you could give us a hand!\n\nIf you're willing to help our cause, we have to get you through training.  Gnome training is brutal and rigorous, so I hope you're ready.\n\nHead over to Drill Sergeant Steamcrank and he'll walk you through what you need to know.  Make sure you follow his orders when he gives them, or else you'll never make it\n\nI'm warning you though, it's tough over there.  Come back to see me, if you make it.", objectives = "" }
WordHunterWoW_QuestEN[25200] = { title = "Shredder Shutdown", description = "That no-good Trade Prince Gallywix somehow managed to stow the whole Steamwheedle Sharks footbomb team away on the yacht. I didn't even see any of them!\n\nNow he has them doing his dirty work here at the lumber yard. {name}, you're the guy who won the championship for us back home on Kezan. You've got to get rid of them!", objectives = "" }
WordHunterWoW_QuestEN[25201] = { title = "The Ultimate Footbomb Uniform", description = "Look, kid, I'm here to see to it that you've got a fighting chance at the end game. Thrall's going to need your help in the fight against the Trade Prince.\n\nGreely, Hobart, and I have a plan to put together the ultimate footbomb uniform for you so that you can win the game, but I'm going to need some things first.\n\nLucky for us, this lumber yard is sick with spare shredder parts. Now get out there and give me 110%!", objectives = "" }
WordHunterWoW_QuestEN[25202] = { title = "The Fastest Way to His Heart", description = "Oh, man! You're never going to guess who's out on the oil platform to the north.\n\n<Izzy shakes her head sadly at you.>\n\nChip's out there, and he's working for the Trade Prince. That cold-hearted snake dropped you like a bad habit and now he's working for the other team. I even heard he's got something goin' on with Candy Cane!\n\nI don't know about you, but if he was my former definitely-real boyfriend, I'd rip his still-beating heart out of his chest.", objectives = "" }
WordHunterWoW_QuestEN[25203] = { title = "What Kind of Name is Chip, Anyway?", description = "Dude! You're never going to guess who's out on the oil platform to the north.\n\n<Ace shakes head in disbelief.>\n\nChip's out there, and he's working for the Trade Prince. That traitor's now working for the other team. But worse, I heard he's got something goin' on with Candy Cane!\n\nI don't know about you, but if he was shmoozin' up to my former definitely-real girlfriend, I'd do something about it.", objectives = "" }
WordHunterWoW_QuestEN[25204] = { title = "Release the Valves", description = "We have to stop Trade Prince Gallywix's oil supply and bring his machines to a grinding halt.\n\nWe're going to need you to go out to the KTC Oil Platform and release the valves to overload the coolant system. After you do that, head to the platform control panel on the platform and set it to blow.", objectives = "" }
WordHunterWoW_QuestEN[25205] = { title = "The Wolf and The Kodo", description = "My \"associate\" here has some plans for you that I don't agree with.  His actions are hasty, uncontrolled, and irresponsible, and you may end up paying for them with your life.\n\nBefore you work with Gor, first listen to the tale that I have to tell.  It's a moralistic story - a fable - but I believe its lesson will prove valuable.  Speak to me when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[25206] = { title = "Ignoring the Warnings", description = "Ignore the shaman, soldier.  Certain powers-that-be within the Horde demand that I keep him with me, but I assure you, that Thrall-loving farseer truly sees no farther than the borders of this hut.\n\nElementals war against one another to the west of here.  I normally wouldn't mind, but I need that land clear to secure a broader shipping route to and from the Barrens.  The elementals are normally quite strong, but they are weakened by their attacks against one another.  Use this knowledge to destroy them.", objectives = "" }
WordHunterWoW_QuestEN[25207] = { title = "Good-bye, Sweet Oil", description = "There is single big, red button on the platform control console. Clearly if ever there were a button to cause massive explosions, that is it!", objectives = "" }
WordHunterWoW_QuestEN[25208] = { title = "Tell Silvia", description = "It seems we've found an infestation far worse than the one we expected. Cho'gall is no doubt trying to use the Gordok to gain access to the remnants of Eldre'thalas within Dire Maul, full of the forbidden powers that brought the downfall of the Shen'dralar...\n\nI am rambling. Leave me, {name}. Tell Silvia of what you've learned. Whatever is occuring in Dire Maul must be stopped.", objectives = "" }
WordHunterWoW_QuestEN[25209] = { title = "The Gordunni Threat", description = "Within the High Wilderness to the south lay countless ancient ruins. It's there that the ancestors of the night elves fooled about with arcane magic, and it's there that the Gordunni ogres wander, searching for leftover scraps.\n\nYou'll notice the forest is completely destroyed in that area; the ogres leave only useless muck in their wake, depriving the Horde of valuable resources.\n\nGo and slay the Gordunni there, {name}. Secure the area for the Horde, and only for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[25210] = { title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", objectives = "" }
WordHunterWoW_QuestEN[25211] = { title = "Cleaning Hovel", description = "Don't listen to Rharen. He's as addled as they come. It's his fault that the ale got captured!\n\nAnd what's more, I figure there's a bigger issue here than the ale being stolen. The fact that there's a bunch of orcs runnin' about Dun Algaz after all these years is ridiculous!\n\nTell you what, {class}. You head in there and be sure to drive as many orcs out of those ruins as you can. Dun Algaz isn't good for much anymore, but I'll be damned if we let them just sit in there.", objectives = "" }
WordHunterWoW_QuestEN[25212] = { title = "Vent Horizon", description = "We thought that we could wait for the radiation to subside around Gnomeregan, but it doesn't appear to be getting better.\n\nIf we want to take back our city, we need to make sure it's safe for our troops to enter.\n\nTake these Radiageigatrons, hop in 'Thunderflash' here,  and toss them at the ventilation shafts outside of Gnomeregan. They'll report the radiation levels directly to me.", objectives = "" }
WordHunterWoW_QuestEN[25213] = { title = "The Slave Pits", description = "Sassy's over at the Slave Pits. She's there with the orcs getting ready to execute the final play on the Trade Prince.\n\n{name}, take the footbomb uniform up the road to the southwest and find her. I know she's going to want you to lead the charge!\n\nAck, I'm starting to talk like the coach now!", objectives = "" }
WordHunterWoW_QuestEN[25214] = { title = "Escape Velocity", description = "We really don't have time to rescue those that are incompetent enough to get themselves captured over and over. Still, since I have some extra rockets leftover, this problem should be a snap.\n\nTake these single-stage booster rockets down into the Slave Pits to the north and put them on the cages.\n\nThe cage will lift off into orbit and those idiots will be freed.", objectives = "" }
WordHunterWoW_QuestEN[25215] = { title = "A Distracting Scent", description = "Predators will smell these dead naga from nearly a mile away. Soon we'll find ourselves fighting just to get in and out of the cave. Care to help me clean up?\n\nJust over the ridge to the south is Glimmerdeep Gorge. If you drag the corpses from the eastern exit of the cave over there to the gorge and cut them loose, the wildlife will pick them clean before they hit the sea floor. Just steer clear of the sharks as much as you can.", objectives = "" }
WordHunterWoW_QuestEN[25216] = { title = "The Great Sambino", description = "If you're heading down the trench, I'd like you to check in one of our novice members for me.\n\nHis name is Sam, but he's likely to embellish it a bit. He doesn't really understand how members of the Earthen Ring work, but he tries hard, so we try to give him the benefit of the doubt.\n\nDon't get too wrapped up in helping him with his crazy schemes. Just make sure he's still in one piece and let me know so that I can have a little peace of mind.", objectives = "" }
WordHunterWoW_QuestEN[25217] = { title = "Totem Modification", description = "Okay, I'll let you in on the real work, since you're looking at me so desperately.\n\nThis rock is untapped! It's probably richer than a trade prince during a great war! I need samples. More samples. Samples from everywhere!\n\nI've modified my earth totems to drill through the sand and store samples of the rock underneath. Go find a nice spot and plant one.\n\nThe shaking and rumbling will probably attract all the cute, curious wildlife, so maybe you can make some friends while you're at it.", objectives = "" }
WordHunterWoW_QuestEN[25218] = { title = "Undersea Inflation", description = "Fine! Fine. You argued me into it. You can help.\n\nI'm leaking air worse than a zeppelin stuffed with quilboar! My air valve must have come loose somewhere in the trench.\n\nI brought spare air balloons - make yourself useful and go fill one up, will ya? And find my valve! I'll need that too.\n\nI bet the crabs snatched it up... pinchy, greedy little things.", objectives = "" }
WordHunterWoW_QuestEN[25219] = { title = "Don't be Shellfish", description = "I'm researching snails.\n\nYes. Snails. When you're done laughing, maybe you can help.\n\nI'm sure you noticed the gigantic shellfish across the ridge... well, I'm pretty sure there's something inside it. It has several points that can only be mouths or entrances of some kind, and I've seen those sifting snails squeezing in and out.\n\nI'm thinking that we might be able to use the snails to gain entrance ourselves. That's the theory anyway.", objectives = "" }
WordHunterWoW_QuestEN[25220] = { title = "Slippery Threat", description = "Been attacked by any of the eels along the ridges yet? If not, you will. They are vicious, bloodthirsty little monsters. They don't seem to show much of any preference in what they're biting.\n\nIf you're going out into the valley, I'd appreciate if you thinned their population a bit. Not everyone here is as well equipped as you - we might not come back with just scratches.", objectives = "" }
WordHunterWoW_QuestEN[25221] = { title = "Rundown", description = "They're getting away!\n\nThese are the same naga that attacked the boats and carried away our friends. We cannot let them escape!\n\nTake these spears and run them down with that seahorse of yours... don't waste your time dismounting, just keep after them and kill all that you can with the spears.\n\nI will try to hunt down that Fathom-Lord. Meet me at the far end of the ledge when you're done.", objectives = "" }
WordHunterWoW_QuestEN[25222] = { title = "Silver Tide Hollow", description = "Most of the other Earthen Ring that escaped the massacre on the boats have taken shelter in a cave a short swim down from the ridge. It's tucked midway up a huge rock formation, west of Nespirah, the gigantic shell on the horizon.  I need you to make sure they're okay. There's no telling how many naga might have attacked them as well.\n\nI'm going to hunt down that Fathom-Lord. I'll send word if I find the rock he's hiding under.", objectives = "" }
WordHunterWoW_QuestEN[25223] = { title = "Trial By Fire", description = "I'd love to say that with the tides turning against us in Hyjal, every recruit helps our cause and so on... but to be perfectly blunt, most of you are nothing but a burden.\n\nIf I had a copper for every peasant who got too scared when the cataclysm hit and now wishes to join our side... well, let's just say I'd be a rich woman.\n\nFortunately we have checks in place to separate the wheat from the chaff.  Go and prove yourself to the fiery instructors below.  Hopefully you'll do better than the others.", objectives = "" }
WordHunterWoW_QuestEN[25224] = { title = "In Bloom", description = "It is customary for new recruits to be sent on a difficult or sometimes impossible task.  I was sent to obtain a black dragon's scale; last year's instructors demanded a feather from a phoenix.\n\nYour lot has it relatively easy.  Find me a handful of flame blossoms.\n\nThey grow around here in relative abundance.  Oh, right.  There will be a gigantic core hound roaming the fields to keep things interesting.  Do your best to avoid him.", objectives = "" }
WordHunterWoW_QuestEN[25227] = { title = "Thonk", description = "Oh, sweetie, I just remembered!\n\nMy VERY good friend Thonk works in the guard tower on that cliff, just to the northwest of Razor Hill.  He said something about a river overflowing, lots of work to be done, and so on.  I wasn't really paying attention... I was staring into those deep brown eyes of his.\n\nWhat, we can't see other people?", objectives = "" }
WordHunterWoW_QuestEN[25229] = { title = "A Few Good Gnomes", description = "Our engineers have been working on getting our battle machines ready for our assault on Gnomeregan, but we're out of pilots!\n\nWe've developed a device called the Motivate-a-Tron, which prevents distraction from other sources and gives the gnome the courage to enlist.\n\nAfter motivating a few Gnome Citizens, lead them out to Captain Tread Sparknozzle out at Steelgrill's Depot, just south of Ironforge.\n\nOh, and be careful. The device is still a little experimental.\n", objectives = "" }
WordHunterWoW_QuestEN[25230] = { title = "More Than Illness", description = "We've found a brood of dragon whelps gathered off the road to the north, and they show the same illness as the stags.\n\nGreen dragons are not simple beasts of nature, but the very guardians of the wild. They are magical creatures, and to see them ill as well implies this is a dangerous threat.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", objectives = "" }
WordHunterWoW_QuestEN[25232] = { title = "The Burning Blade", description = "I've been sent to investigate the presence of more Burning Blade agents here in Durotar.  To the northeast, you'll find a cave where the organization trains their new recruits.  I'm interested in what exactly they are teaching these neophytes.\n\nI only tell you this because you seem to be looking for work.  If you're interested in a little coin, sack the cave and return with their spellscrolls.\n\nThe cave is somewhat hidden: exit Razor Hill from the east, and follow the canyon's eastern ridge.", objectives = "" }
WordHunterWoW_QuestEN[25233] = { title = "End of the Supply Line", description = "Cho'gall's Twilight Proveditors swear a blood oath that they will get their supplies through to the front, pledging a pound of their own considerable flesh for every pound of supplies they fail to deliver. They would rather die than fail.\n\nSee to it that they do both.", objectives = "" }
WordHunterWoW_QuestEN[25234] = { title = "In the Rear With the Gear", description = "Prisoners of the Twilight's Hammer are forced to lug around sundries for the war effort, like common pack animals. I want those supplies, and if we can free a few poor souls from the Hammer's shadowy grip, all the better.\n\nKill the slave drivers along the road to our south and nearby slaves should make a break for it.\n\nSearch the packs they leave behind for anything valuable, and destroy anything you can't carry.", objectives = "" }
WordHunterWoW_QuestEN[25235] = { title = "Vulgar Vul'Gol", description = "Hail, {class}. Care to lend a hand for the people of Darkshire?\n\nThere's a huge ogre mound just down the hill there. The Splinter Fist ogres usually keep to themselves, but they've got a bad habit of attacking travelers. Just the other day I saw one drag off a poor man's horse for food... he was lucky it left him behind!\n\nThe Night Watch wants to only risk its few members in the defense of more immediate threats, me included. But if you kill some of those ogres for me, I'll pay you for your deed.", objectives = "" }
WordHunterWoW_QuestEN[25236] = { title = "Thunder Down Under", description = "Our army needs water, and luckily the elements gave us plenty of that when the cataclysm hit.  The water that filled up the canyon to the southwest should do the trick.\n\nUnfortunately, the corpses of thunder lizards still sit at the bottom of the canyon, and their electrical discharges are a bit too dangerous.  I've got grunts that can lift them out of the water, but we need someone agile enough to attach the other end of the rope.  Are you my man, {name}?", objectives = "" }
WordHunterWoW_QuestEN[25237] = { title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nWeeks ago, in the glade to the west, I saw the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to; a source of nature's purity. We must gather them.", objectives = "" }
WordHunterWoW_QuestEN[25239] = { title = "Path of Might", description = "You seek to continue down the path of might?", objectives = "" }
WordHunterWoW_QuestEN[25240] = { title = "Path of Might", description = "You seek to continue down the path of might?", objectives = "" }
WordHunterWoW_QuestEN[25241] = { title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nIf the corruption has spread to them, they will lash out at the wildlife and their own kind, causing great destruction. You must destroy any corrupted giants you come across.", objectives = "" }
WordHunterWoW_QuestEN[25242] = { title = "Path of Might", description = "You seek to continue down the path of might?", objectives = "" }
WordHunterWoW_QuestEN[25243] = { title = "She Loves Me, She Loves Me NOT!", description = "Oh, sweetie! You're never going to guess who's down in the slave pits to the north.\n\n<Sassy shakes her head sadly at you.>\n\nCandy's down there, and she's working for the Trade Prince. She dropped you like a bad habit and now she's working for the other team. but it gets worse. Since you \"dealt\" with Chip, she's shmoozin' up to the Trade Prince!\n\nI don't know about you, but if she were my absolutely-not-fake girlfriend, I'd rip her fickle heart right out of her chest.", objectives = "" }
WordHunterWoW_QuestEN[25244] = { title = "What Kind of Name is Candy, Anyway?", description = "Can you believe that Candy Cane! You know up until you \"dealt\" with Chip, she was tryin' to start a partner brand with him. Now she's shmoozin' up to the Trade Prince!\n\nI just can't get over the fact that she betrayed you like that with your absolutely-not-fake boyfriend. Maybe you should head down into the Slave Pits and take care of her once and for all?", objectives = "" }
WordHunterWoW_QuestEN[25250] = { title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the east, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the World Tree itself. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave. May the Earth Mother watch over you.", objectives = "" }
WordHunterWoW_QuestEN[25251] = { title = "Final Confrontation", description = "{name}, this is it! Thrall's down at the Gallywix Docks fighting the Trade Prince right now!\n\nYou gotta jump into your Ultimate Footbomb Uniform and get over there!", objectives = "" }
WordHunterWoW_QuestEN[25252] = { title = "Rulers of Dire Maul", description = "Now that we've put the hurt on them at the ruins, it's time to attack the ogres in their own territory.\n\nThe Gordok are the \"upper class\" of the Gordunni clan, chosen to defend Dire Maul. They'll know we mean business once we start taking out their strongest members.\n\nNothing fancy here, {name}. Just get out there and crack some Gordok skulls.", objectives = "" }
WordHunterWoW_QuestEN[25255] = { title = "Harrying the Hunters", description = "Twilight's Hammer has revealed itself as more than a mere cult. They're a war machine - a swarm of locusts moving up the mountain, devouring anything in their way.\n\nThe parts of the forest they're not setting ablaze are being scoured of life in order to feed the mortal cultists.\n\nWe've got to put a stop to the hunters canvassing Wolf's Run, not only to preserve what wildlife remains but to force the cult to march on empty stomachs. Look south of here, as well as up the road to the east.", objectives = "" }
WordHunterWoW_QuestEN[25256] = { title = "Sent for Help", description = "You, {race}, stop a minute.\n\nMy boss Spiketooth sent me to look for help and supplies.  You don't appear to be a merchant, but you can probably still help him out.  He's just to the southeast of here, next to the crashed cart.  Oh, and tell him I sent you... I want to make sure that he knows I'm not just slacking off over here.", objectives = "" }
WordHunterWoW_QuestEN[25257] = { title = "Ghislania", description = "I own a couple gladiators that I put into competitions around Kalimdor.  You can see most of them chained up around here... we were lucky to rein these ones in after the cart broke down.\n\nGhislania, that naga over there... she's lost her last three fights.  She could use a tune-up, or maybe just a little bit of thrashing.  Go challenge her, I'll bet even YOU are stronger than she is.", objectives = "" }
WordHunterWoW_QuestEN[25258] = { title = "Griswold Hanniston", description = "Griswold, chained up over there on the cliffs, is my newest gladiator.  We found him just south of here, sniffing around with Northwatch soldiers.  I had my men nab him up, and now he works for me.\n\nHe looks tough enough, but he hasn't really been battle-tested yet.  Go pick a fight with him so I can see if he's worth keeping around.", objectives = "" }
WordHunterWoW_QuestEN[25259] = { title = "Gaur Icehorn", description = "I wouldn't normally keep a taunka as a captive, due to their close relationship with the Horde... but this one is a traitor, and a criminal to boot.  Exiled by his own tribe, he canoed down to Azshara and was found stealing supplies from Valormok.  He would have been put to the axe had I not been standing by, wallet in hand.\n\nGaur is my winningest gladiator, {class}.  I'll bet you a fist full of silver that you can't beat him.", objectives = "" }
WordHunterWoW_QuestEN[25260] = { title = "Fizzled", description = "The flood to the southwest wiped out one of the few Burning Blade camps that still pockmark Durotar.  This one was led by a goblin named Fizzle Darkclaw, and believe me, we're better off without him.\n\nDarkclaw, however, did possess an orb that the Horde is interested in procuring.  Who knows why... I leave that to the warlocks.  All I know is that I need that orb.", objectives = "" }
WordHunterWoW_QuestEN[25261] = { title = "Margoz", description = "One of our more useful shaman, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains, just outside Orgrimmar, that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock, speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the southeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, {name}, I still want you to crush those cultists!", objectives = "" }
WordHunterWoW_QuestEN[25262] = { title = "Skull Rock", description = "{name}.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", objectives = "" }
WordHunterWoW_QuestEN[25263] = { title = "Arnak Fireblade", description = "The Searing Collars you brought me are powerful demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Arnak Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Arnak in Orgrimmar in the Cleft of Shadow.", objectives = "" }
WordHunterWoW_QuestEN[25264] = { title = "Ak'Zeloth", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade.\n\nYour role in this tale is nearly complete, {name}.  Go to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  Pass on to him this information.", objectives = "" }
WordHunterWoW_QuestEN[25265] = { title = "Victory!", description = "We just can't thank you enough for all that you've done. Now we can all get off of this island before it kills us!\n\nThrall is going to want to speak with you first, {name}. I'll rocket you over there.\n\nSee you on the ship!", objectives = "" }
WordHunterWoW_QuestEN[25266] = { title = "Warchief's Emissary", description = "The goblins and the Horde have accomplished too much together to part ways now, {class}. I intend for the Bilgewater Cartel to become part of the Horde.\n\nI have something that I want you to deliver to the new warchief. Give this package to my Darkspear friend on the dock at Bladefist Bay in Durotar. She will help you to get into Orgrimmar safely.\n\nSpeak with Sassy Hardwrench on the ship when you are ready to set sail.\n\nUntil we meet again. Aka'Magosh, a blessing on you and yours, {name}!", objectives = "" }
WordHunterWoW_QuestEN[25267] = { title = "Message for Saurfang", description = "<The Darkspear loyalist opens the package and reads the letter within. As she finishes the note from Thrall, a hint of a fanged smile appears on her face.>\n\nYa should take dis directly to Saurfang inside Orgrimmar. Be sure ta let him know dat de package be from Thrall.\n\nTake me raptor. Hurry, little one, dere be no time ta waste!", objectives = "" }
WordHunterWoW_QuestEN[25268] = { title = "The Voice of Goldrinn", description = "Southwest of here lies the shrine of Goldrinn, a memorial erected in honor of the ancient wolf spirit and his contribution during the War of the Ancients.\n\nOur new worgen allies have been drawn to the memory of the wolf god - go figure! - and were in the process of cleaning up the shrine.\n\nI haven't heard anything from my contact, Ian Duran, in days. Can you fly down there and find him? I've got a bad feeling that Goldrinn's shrine is in trouble...", objectives = "" }
WordHunterWoW_QuestEN[25269] = { title = "The Voice of Lo'Gosh", description = "Have you heard of Lo'Gosh, the wolf ancient? In the Alliance tongue, he is known as \"Goldrinn.\"\n\nI don't need to tell you how important the wolf god has been to the Horde - his tenacity under adversity has been an inspiration to all of our disparate races.\n\nSouthwest of here, down in the valley, lies a shrine to Goldrinn. My friend Takrik Ragehowl was refurbishing the shrine when I stopped hearing from him. I fear the worst.\n\nPlease find Takrik and make sure the shrine is okay!", objectives = "" }
WordHunterWoW_QuestEN[25270] = { title = "Howling Mad", description = "The shrine has been taken, {name}. We need the tenacity of Lo'Gosh now more than ever.\n\nThese defilers - the lice-ridden wolf-men running rampant over the shrine - dishonor the memory of the wolf god. They arrived with the Twilight's Hammer, howling with their own twisted religion. They seek to corrupt noble Lo'Gosh to fit their own warped pantheon.\n\nKill them! Kill them and bring me the tools of their worship, a kind of polluted incense. I must understand what they want with the shrine...", objectives = "" }
WordHunterWoW_QuestEN[25271] = { title = "Goldrinn's Ferocity", description = "The beasts you see here, they're no longer my brothers from Gilneas. They've been corrupted by some kind of madness, and they've taken over the shrine.\n\nThey came when the Twilight's Hammer arrived in Hyjal, and they howl the name of some blasphemous mockery of our beloved Goldrinn. Forget about me - destroy these vandals before they continue to defile the shrine.\n\nAs you destroy them, look for the incense they carry and bring me some samples.", objectives = "" }
WordHunterWoW_QuestEN[25272] = { title = "Lycanthoth the Corruptor", description = "The actions of these feral dogs are beginning to make sense. The Twilight's Hammer fears the power of the ancients. They do not want Lo'Gosh to return.\n\nSo they've summoned their own wolf god - a perversion of what once was. \"Lycanthoth,\" the corruptor.\n\n{name}, Lycanthoth is but a shadow of Lo'Gosh's power, but the beast must be destroyed so that the true ancient can return. Take this incense, and burn it in the Maw of Lycanthoth east of here. Slay the monstrosity and free the spirit of Lo'Gosh!", objectives = "" }
WordHunterWoW_QuestEN[25273] = { title = "Lycanthoth the Corruptor", description = "I think I understand what's happening here. The Twilight's Hammer fears that the ancients may someday rise up to oppose them. They'll do anything to stop the return of Goldrinn.\n\nThis \"Lycanthoth\" is a twisted version of our beloved wolf god, summoned by the Twilight's Hammer to replace him.\n\nBah! It is but a shadow of Goldrinn's power. {name}, kill this beast so that the true ancient can return. Take this incense and burn it in the Maw of Lycanthoth east of here. Slay that beast and free Goldrinn!", objectives = "" }
WordHunterWoW_QuestEN[25274] = { title = "Signed in Blood", description = "You're here at last, {name}.  Just in time as well.\n\nNews of Ragnaros' emergence has spurred a large wave of recruits to seek membership in the Twilight's Hammer.\n\nIf you're to infiltrate the cult, the time is now.  We will need recruitment papers -- signed in blood by a referring Twilight member.  Lure one of the new recruits away from the group and hit them with this blackjack.\n\nIf you're lucky, you'll be able to steal his recruitment papers.  Bring them back to me and we'll do our best to alter them.", objectives = "" }
WordHunterWoW_QuestEN[25275] = { title = "Report to the Labor Captain", description = "Your people are working on the terraforming of Azshara. The land will be remade in the image of the Horde so that all will know that Kalimdor belongs to us!\n\nGo north through the city. On the far side of the Valley of Honor you will find the Orgrimmar Rear Gate. Report to Labor Captain Grabbit outside the gates.\n\nFor the Horde!!!", objectives = "" }
WordHunterWoW_QuestEN[25276] = { title = "Your New Identity", description = "There.  Not my best work, but certainly not my worst.  You will be known as \"{name}damus\" among the cultists.\n\nThese papers will bump you ahead of the other recruits and allow you to speak directly to the Twilight instructors.\n\nGo to the proving grounds and show these to Condenna the Pitiless.  She's separating the wheat from the chaff.\n\nShow her what you're made of.", objectives = "" }
WordHunterWoW_QuestEN[25277] = { title = "Cleaning House", description = "We are well on our way to returning the shrine to its former glory, {name}. But there is some housecleaning to take care of. On the other side of this meadow, some ogre squatters are setting up camp, led by a thick-headed chunk of ugly by the name of Gar'gol.\n\nKill Gar'gol's minions and see if we can't send him packing.", objectives = "" }
WordHunterWoW_QuestEN[25278] = { title = "Cleaning House", description = "Thanks to your efforts, we may soon be able to return this shrine to its former glory. But first we've got to secure this valley. South of here, a group of ogres led by Gar'gol has set up camp in a stinking hovel.\n\nI wouldn't characterize Gar'gol as a 'threat' so much as an enormous fleshy obstacle thrown into our path to distract us from the real danger. Nonetheless, he and his goons will have to be dealt with.\n\nKill Gar'gol's minions in Goldrinn's name!", objectives = "" }
WordHunterWoW_QuestEN[25279] = { title = "The Shrine Reclaimed", description = "Yes, {name}. I am Goldrinn, the one called \"Lo'Gosh\" in your tongue. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Takrik and continue your work here in Hyjal. I will have need of you again soon.", objectives = "" }
WordHunterWoW_QuestEN[25280] = { title = "The Shrine Reclaimed", description = "Yes {name}, I am Goldrinn. Your persistence in the face of fear has unbound me from twilight's grasp.\n\nMy shrine has been purified, and my worshippers have returned to their rightful place at my right paw.\n\nReturn to Ian and continue your work here in Hyjal. I will have need of you again soon.", objectives = "" }
WordHunterWoW_QuestEN[25281] = { title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", objectives = "" }
WordHunterWoW_QuestEN[25283] = { title = "Prepping the Speech", description = "High Tinker Mekkatorque asked me to write a speech that he could give before the battle starts, but I can't tell which draft is good and which ones just stink.\n\nCould you try some of them out on some of the local gnome residents?  This device creates an image of Mekkatorque saying a few lines from each of my speech drafts.\n\nLet me know which one works, okay?", objectives = "" }
WordHunterWoW_QuestEN[25284] = { title = "Feeding the Fear", description = "Our resources are limited, {class}, but that doesn't mean we can't make some trouble down below. Use the ropes here to sneak down the hillside, then slay the human prison wardens.\n\nKilling a couple scrawny guards won't turn the tide of battle, but  imagine the fear and chaos we'll reap as the humans discover the mutilated bodies...\n\n<Holgom grins a yellowed grin, his eyes glinting.>", objectives = "" }
WordHunterWoW_QuestEN[25285] = { title = "In and Out", description = "We've gotta get these new mechano-tanks ready for the assault.  You ready to help test these bad boys out?!  Of course you are!\n\nFirst, we need to make sure that once you're in, you can get out.  In battle, if you think your tank is going to explode, get out!  I've seen many a gnome stay in 'til the bitter end... the tank blows up, and them along with it.\n\nWell, I've upgraded this tank with an ejection seat.  Try it out for me, will ya?", objectives = "" }
WordHunterWoW_QuestEN[25286] = { title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and get some transportation to High Tinker Mekkatorque!", objectives = "" }
WordHunterWoW_QuestEN[25287] = { title = "Words for Delivery", description = "All right, soldier. Time to prove your worth!\n\nTake the speech and board the flying machine \"Thunderflash\".  It's the fastest ship to High Tinker Mekkatorque and this speech is the only thing he's waiting on before starting Operation: Gnomeregan.\n\nGo! Now!", objectives = "" }
WordHunterWoW_QuestEN[25289] = { title = "One Step Forward...", description = "With the ejection system working, I think we're ready to test out movement.  This tank has an extra special feature: Automatic Evasive Maneuvers!\n\nI want you to check out the servos on the left leg, the right leg and the Automatic Evasive Maneuver system.\n\nThis is easy stuff, so it shouldn't take too long.", objectives = "" }
WordHunterWoW_QuestEN[25291] = { title = "Twilight Training", description = "You've proven you're worthy of at least participating in our most basic training.\n\nYou'll find one of our settlements east of here.  Speak to instructor Mylva there.", objectives = "" }
WordHunterWoW_QuestEN[25292] = { title = "Next of Kin", description = "<Nato pulls you aside and speaks in a whisper.>\n\n{name}, I have removed the bullet from Gann's chest, but the bubbles in his blood tell me all I need to know. His lungs are punctured, and the wound grows septic. He is not long for this world.\n\nTake this. It's the bullet that killed him. His family will want to know what became of their youngest warrior.\n\nSeek out Alto Stonespire. He is posted in Dustwallow Marsh. Go northeast, and follow the roads to Brackenwall Village.", objectives = "" }
WordHunterWoW_QuestEN[25294] = { title = "Walking the Dog", description = "Hmmmphh.... it seems they'll let anyone in these days.\n\nVery well.  You doubtlessly became acquainted with Smolderos in the proving grounds.\n\nWell, I've been entrusted with the care of one of his pups.  Quite the little terror -- if he grows up to be anything like his father he shall serve our cause well.\n\nCollect meat from the basilisks around the area and feed them to him.", objectives = "" }
WordHunterWoW_QuestEN[25295] = { title = "Press Fire", description = "Safety systems, online!  Motor functions, functioning!  Now all we need is to make sure that the guns will fire.\n\nThis shouldn't be too hard, {name}.  The mechano-tank on the hill behind us has been loaded with harmless pellets. Just fire off a couple rounds at the nearby targets and report back to me.", objectives = "" }
WordHunterWoW_QuestEN[25296] = { title = "Gather the Intelligence", description = "It's me, {name}, Ortell!\n\nDon't look directly at the outhouse... you'll give away my position.\n\nEverything's going according to plan then?  Excellent!\n\nI'm going to need you to obtain some intelligence while you're here.  It might not seem like much to get our hands on a map or a letter, but it may mean saving a hundred lives on our side if we can anticipate our enemy's next move.", objectives = "" }
WordHunterWoW_QuestEN[25297] = { title = "From the Mouth of Madness", description = "I know of a draught that should jolt these gibbering former slaves back to reality. Gather some stonebloom from the rocks around Gar'gol's hovel, some bitterblossom from the shores of the nearby lake, and a darkflame ember from one of the braziers at the hovel entrance. The draught won't last long, so combine the ingredients at a twilight cauldron by the entrance to the hovel.\n\nOne sip of that draught should knock some sense into the brainwashed slaves!", objectives = "" }
WordHunterWoW_QuestEN[25298] = { title = "Free Your Mind, the Rest Follows", description = "<Rio said that the draught would not remain effective for long.>\n\n<You'd better hurry into the hovel and administer it to as many Twilight Servitors as you can find.>", objectives = "" }
WordHunterWoW_QuestEN[25299] = { title = "Mental Training: Speaking the Truth to Power", description = "You might think you're ready to receive the knowledge we're to impart on you.  But you are not.\n\nThink of your mind as a box inside a series of other boxes.\n\nEach step of our training will open one of those boxes, until you are ready to achieve direct communion with the elements.\n\nTake the Core of Ascension and answer all questions it asks of you, truthfully.  Failing to do so could be... fatal.", objectives = "" }
WordHunterWoW_QuestEN[25300] = { title = "The Eye of Twilight", description = "The ogre clan across the lake is led by Gar'gol. I use the term loosely; Gar'gol has the intelligence of raw beef.\n\nSo far as I can tell, Gar'gol is taking orders from a magical instrument: \"The Eye of Twilight.\" He follows its commands unquestioningly.\n\nIf we can sabotage the eye, we can cause unimaginable havoc.\n\nGo to Gar'gol's hovel and seek out the Eye of Twilight near the entrance. Study it. Find a way to subvert it. Ah, marvelous chaos...", objectives = "" }
WordHunterWoW_QuestEN[25301] = { title = "Mastering Puppets", description = "<During your brief communion with the Eye, you felt that its power source lay deep within the hovel. You felt the weight of a powerful tome, binding together four elements.>\n\n<Mastering the Eye will require you to search the hovel for this tome.>", objectives = "" }
WordHunterWoW_QuestEN[25303] = { title = "Elementary!", description = "<You can't read the text, but diagrams seem to indicate that the devices around you should be activated in a set order.>\n\n<One passage of the Apocrypha has been translated to modern text:>\n\n   In the beginning was shadow eternal.\n   Hate blazed forth, and FIRE was born.\n   Wounds scabbed, and so begat EARTH.\n   Cries of anguish birthed howling WIND.\n   Wherein the skies wept seas of TEARS.\n      We live in the shadow,\n      The world we know\n   Built of rage, hurt, anguish and sorrow.", objectives = "" }
WordHunterWoW_QuestEN[25304] = { title = "The Battle of Sardor", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Find our Ancient of War along the shore. He will take you to the front lines, where Tambre leads the offensive.", objectives = "" }
WordHunterWoW_QuestEN[25305] = { title = "Never Look Back", description = "Our settlement on Sardor Isle was lost to the Hatecrest naga. Overwhelmed by their numbers, we fell back to the mainland. While they coveted their newly-gained sandbar, we raised New Feathermoon on the shore and amassed an even greater army.\n\nNow, the Hatecrest will be driven back into the sea. Speak with Sentinel Ranadae to join our forces at Sardor. Slay the naga, and make sure whichever foul snake they take orders from is killed as well.", objectives = "" }
WordHunterWoW_QuestEN[25306] = { title = "You're In The Army Gnow!", description = "[ph] War!", objectives = "" }
WordHunterWoW_QuestEN[25308] = { title = "Seeds of Discord", description = "According to the intelligence you acquired, there is major friction between the ogres and non-ogres in the cult.\n\nHigh Cultist Azennios and the ogre mage Karr'gonn are meeting at the Seat of the Chosen in an attempt to ease the conflict.\n\nThere is an outhouse like this one at the Seat of the Chosen.  Go there and put on this ogre disguise.  Find a way to kill Azennios while he's in this mission of peace.\n\nWe must exploit this division as much as we can!", objectives = "" }
WordHunterWoW_QuestEN[25309] = { title = "Spiritual Training: Mercy is for the Weak", description = "You've made it this far.  Others haven't.\n\nGo to Doom's  Vigil, just north of here.  We've rounded up all the... failures.  I want you to help take care of them.  It'll be good for your spiritual growth.\n\nIf this cold-blooded act gives you trouble, think of it as their second chance.  Should any of them manage to kill you... well, they'll take your spot.", objectives = "" }
WordHunterWoW_QuestEN[25310] = { title = "The Greater of Two Evils", description = "We took Darkwhisper Gorge from the demons of the Burning Legion by force.  We've held on to our territory pretty well so far, with one exception.\n\nWe recently lost the Gates of Sothann to a pit lord and his army.  We cannot allow this to stand.\n\nUse this talisman when you're near him.  You'll gain the powers of a flame ascendant temporarily.  Make it count.", objectives = "" }
WordHunterWoW_QuestEN[25311] = { title = "Twilight Territory", description = "The demons of the Burning Legion think they can just walk up here and take whatever territory they want.  Sure -- the territory was previously theirs, but that's beside the point.\n\nWe'll teach them not to cross the Twilight's Hammer.\n\nHead to the Gates of Sothann and wipe out the contingent of Horrorguards that roam the area.", objectives = "" }
WordHunterWoW_QuestEN[25312] = { title = "Return to Duskwhisper", description = "<You force your own image into the Eye, manipulating it to give the ogres different orders. As you do so, you feel another presence within the Eye, probing you, seeking out a weakness. A distant being fumes with rage. You've made some enemies today!>\n\n<Your work here is done, and the ogres will be friendly to you. Return to Royce Duskwhisper at the Shrine of Goldrinn and let him know what you've accomplished.>", objectives = "" }
WordHunterWoW_QuestEN[25314] = { title = "Speech Writing for Dummies", description = "Listen, {name}.  I found out what they're doing with Jarod Shadowsong.  He's scheduled to be sacrificed by the ogres of the Twilight's Hammer as part of this year's initiation.\n\nI heard that the initiate charged with delivering the speech ahead of the sacrifice is an ogre named Okrog, but get this: you were a close second.\n\nWe need you to deliver that speech if we're to free Jarod.  Don't worry -- I'll write you some cue cards -- just make sure Okrog has an \"accident\" as he leaves the Seat of the Chosen.", objectives = "" }
WordHunterWoW_QuestEN[25315] = { title = "Graduation Speech", description = "You're finally ready, {name}damus.\n\nI am so proud of you and all you've accomplished.\n\nToday you will deliver a speech in front of your peers and inspire them to crush our enemies until Hyjal is nothing but a pile of ash.\n\nRemember, {name}damus.  It'll be important to read your audience's emotions and use words that best address those emotions.", objectives = "" }
WordHunterWoW_QuestEN[25316] = { title = "As Hyjal Burns", description = "{name}!  We've heard much about you and your previous accomplishments.\n\nIt is good that you've come here just as Azeroth finds itself in a time of great need.\n\nDeathwing's minions are attacking Hyjal and seek to bring the destructive Ragnaros back into our world.\n\nAronus will take you to join Malfurion's forces in Hyjal. Lend them what help you can.", objectives = "" }
WordHunterWoW_QuestEN[25317] = { title = "Protect the World Tree", description = "<Ysera's eyes look distant, as if not fully acknowledging you.>\n\nI feel it as well, {class}. Ragnaros has arrived.\n\nWe must defeat his minions before he can join them and lend them his strength.\n\nSeek Malfurion Stormrage at the Tranquil Grove, west of here, and aid his forces in any way you can.\n\nI must seek answers from within the Emerald Dream.  You must protect the World Tree until I return.", objectives = "" }
WordHunterWoW_QuestEN[25319] = { title = "War on the Twilight's Hammer", description = "Make no mistake about this, {name}.  The outcome of this war will determine the very survival of our world as we know it.\n\nThe Twilight's Hammer has become more powerful than ever with Deathwing's return.  Should they succeed in taking over the World Tree, they might strike a blow from which we will never recover.\n\nIt is time we beat back the enemy.  It is time we crushed the Twilight's Hammer.", objectives = "" }
WordHunterWoW_QuestEN[25320] = { title = "The Captured Scout", description = "I've heard about you, {name}, and the news you brought from the south.  The battle has reached a stalemate.\n\nOne that I fear is about to be broken by the Firelord's reawakening.\n\nThat is unless we tip the scales in our favor in some way.\n\nThere is a scout that was captured by the Twilight's Hammer.  I believe she was in possession of valuable intelligence. Find her in the Twilight camp to the west.", objectives = "" }
WordHunterWoW_QuestEN[25321] = { title = "Twilight Captivity", description = "I'd been scouting behind enemy lines for nearly a day when they caught me.\n\nThis attack on our frontlines is not what it appears, {name}.\n\nI'll give you all the details, but first let's find a way to get me out of here.\n\nOnly the overseers carry keys to these cages.\n\nFrom what I recall, they're in the middle of the crater, in the thick of it.\n\nSee if you can get a key off of one of them.", objectives = "" }
WordHunterWoW_QuestEN[25323] = { title = "Flamebreaker", description = "The large elementals that besiege us are not a singular entity.\n\nThey are an amalgamation of lesser spirits bound together by the Twilight's Hammer cultists' magic.\n\nThe rebuilt flameseer's staff will give us enough power to shatter its bonds.\n\nDestroy the smaller elementals once you've broken up the more dangerous large ones.", objectives = "" }
WordHunterWoW_QuestEN[25324] = { title = "A Prisoner of Interest", description = "The Twilight's Hammer wants to free Fandral Staghelm?\n\nMalfurion suspected his corruption ran deep... this just cements it.\n\nAt any rate we cannot allow our enemies to get their hands on such a powerful arch druid.\n\nI've a plan, {name}.  We will move the prisoner through the Emerald Dream.  It will be risky, but with all the cultists present here it might be the only way to guarantee our success.\n\nSpeak to Saynna Stormrunner inside the Barrow Dens to the northeast.  ", objectives = "" }
WordHunterWoW_QuestEN[25325] = { title = "Through the Dream", description = "Alysra's plan might be necessary, {name}.  I don't know how much longer we can hold off the cultists.\n\nFandral Staghelm is bound by powerful spells.  He won't be able to escape you, even inside the Emerald Dream.\n\nBeware, though, for all we know the nightmare has spread to this part of the world inside the dream.\n\nTake Fandral to the surface and hand him to Alysra.  Let us hope he's more secure in Moonglade than he is here.", objectives = "" }
WordHunterWoW_QuestEN[25328] = { title = "Gar'gol's Gotta Go", description = "<Kristoff cranes his neck, trying to look you in the eye.>\n\nListen, you gotta get me outta here. They're either going to eat me or turn me over to the Twilight's Hammer. Maybe both.\n\nThey've padlocked me in, and Gar'gol keeps the key in his personal treasure chest. Kill Gar'gol if you have to - but get that key!\n\n<Kristoff flails his limbs, helplessly.>", objectives = "" }
WordHunterWoW_QuestEN[25329] = { title = "Might of the Stonemaul", description = "So the Twilight's Hammer thinks it can just raise its own army of ogres here? In the middle of Horde territory? \n\nWe'll see about that.\n\nOgres only respect one thing: strength. I want you to lead the assault on Cho'gall's sermon, {name}. Throw wide the doors of Dire Maul, leap into the arena, and cut down his attendants.", objectives = "" }
WordHunterWoW_QuestEN[25330] = { title = "Waste of Flesh", description = "Look at these fools.  Half of them won't even make it past this trial.\n\nThey are not worthy of ascending into our inner circles.  But perhaps... perhaps they are worthy of menial service.\n\nTake this gem and utilize its power to save some of the less competent supplicants.  Those who have no chance of succeeding.  Those already on fire, preferably.", objectives = "" }
WordHunterWoW_QuestEN[25332] = { title = "Get Me Outta Here!", description = "<You reach up to unfasten Kristoff's bonds.>\n\nGood! Make a break for the exit, and I'll follow.\n\nIf we get separated, check back here to make sure I haven't been recaptured.", objectives = "" }
WordHunterWoW_QuestEN[25333] = { title = "Might of the Sentinels", description = "The Twilight's Hammer? Here?\n\nThis is far more serious than I expected. We've got to put a stop to this. I don't know if I'm ready to lead such an offensive, but I'm not about to let my fears get in the way of what needs to be done!\n\nI will rally our forces from Feathermoon Stronghold. Head to Dire Maul, make your way to the arena, and disrupt Cho'gall's activities; we will launch our attack during the confusion.", objectives = "" }
WordHunterWoW_QuestEN[25334] = { title = "The Looming Threat", description = "Can ya feel how angry the elements be? They be wantin' to attack us and consume us even as we just arrive. We need ta calm dem, but that kinda wisdom only comes from knowin' what's riling them up in da first place.\n\nCome sit with me by da fire. Let yaself get lost in da flames... let ya spirit peer into the true threat.", objectives = "" }
WordHunterWoW_QuestEN[25336] = { title = "Testing the Vessel", description = "Master Uzer'i's taught me in the ways of making spirit weapons of great power. I'll help you set on the path to make some, and you'll give me the chance to practice my craft.\n\nThis vessel can shrink and trap a defeated creature inside of it. We'll need the muisek of beasts first; ironfur bears and longtooth wolves. Kill them, and use the muisek vessel to shrink and capture them before their spirits can escape.", objectives = "" }
WordHunterWoW_QuestEN[25337] = { title = "Hippogryph Muisek", description = "The next step is hippogryphs.\n\nAs Master Uzer'i always said, hippogryphs have been loyal companions to the night elves for many years, an' their spirits are loyal and steadfast.\n\nI don't think they'll miss a few, and I don't care if they do. We need the muisek of 10 frayfeather hippogyphs in the wilderness to the south.", objectives = "" }
WordHunterWoW_QuestEN[25338] = { title = "Treant Muisek", description = "The wandering forest walkers that can be found meandering through the forest are our next target, {name}. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind three wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", objectives = "" }
WordHunterWoW_QuestEN[25339] = { title = "Vengeance on the Northspring", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. {name}, get my revenge. ", objectives = "" }
WordHunterWoW_QuestEN[25340] = { title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", objectives = "" }
WordHunterWoW_QuestEN[25341] = { title = "The Gordunni Orb", description = "While you're down there cracking skulls...\n\nI've gotten reports that make me think these ogres may be more than the usual lumbering threat. The Warlocks among them have been seen carrying orbs, possibly items of empowerment.\n\nIt would be easy to dismiss them as crude trinkets, but I need to make sure we're not surprised. Bring me back one of these orbs.", objectives = "" }
WordHunterWoW_QuestEN[25342] = { title = "Talk to Swar'jan", description = "We're lucky and unlucky here, grunt. Lucky that I had you bother to bring this back, and unlucky that my suspicions turned out to hold water. This thing's full of corrupted stench.\n\nIt's far too new to be something fished out of the ruins, either. Someone is supplying these ogres, and we need to know who before this becomes a situation.\n\nGet that filthy thing upstairs to Swar'jan, the warlock on top of the guard tower. He's good for a few ideas; I'd listen to his suggestions, if I were you.", objectives = "" }
WordHunterWoW_QuestEN[25344] = { title = "Ogre Abduction", description = "There's no way the Gordunni made these. They're being supplied. Someone is giving them gifts of power, and we need to find out who.\n\nThe upper-class Gordok that guard Dire Maul will know more about this. Orhan is no doubt having you thin their numbers, but I'll need one alive.\n\nTake the orb back. It's similar to a Soulstone, so I've made some...adjustments. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[25345] = { title = "Faerie Dragon Muisek", description = "{name}, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, {name}. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", objectives = "" }
WordHunterWoW_QuestEN[25346] = { title = "Mountain Giant Muisek", description = "The mountain giants left the mountains to aid the night elves when the Burning Legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", objectives = "" }
WordHunterWoW_QuestEN[25349] = { title = "Twisted Sisters", description = "I have heard of your battle against the corrupted dragons, {name}, and I thank you for your courage... but I have disturbing news.\n\nThe dryads of the forest, though allies of the Night Elves, have always passed us by in peace. But they have become cruel and twisted, attacking any who wander the eastern wilds.\n\nI fear for the safety of the refugees here, {name}. Please, put a stop to these twisted dryads.", objectives = "" }
WordHunterWoW_QuestEN[25350] = { title = "The Lost Apprentice", description = "If you have a moment, {class}...\n\nOne of the students I was teaching has gone to explore the darkmist ruins to the south by himself. I warned him that it was too dangerous, but he was too excited to listen.  I had spoken with him earlier about an amulet that is concealed within those ruins.  Now, I fear that he may have run off in search of it, because of me...\n\nEstulan has forbidden us to pursue him. If you go there, could you please look for him?", objectives = "" }
WordHunterWoW_QuestEN[25352] = { title = "Sweeping the Shelf", description = "Wonderful work in the hovel, {name}. I prayed at the shrine while you were away, and in my visions, Goldrinn was watching you closely.\n\nBut we've been on the defensive too long: it's time to foil the Twilight's Hammer directly.\n\nFly up to the Lightning Ledge and disrupt their operation. Kill the stormcallers and the monstrosities they're preparing to unleash!", objectives = "" }
WordHunterWoW_QuestEN[25353] = { title = "Lightning in a Bottle", description = "When I prayed at the shrine, Goldrinn granted me another vision. I saw you standing astride the Lightning Ledge, with lightning in your hands. Goldrinn seems to feel that this is of the utmost importance, but I don't understand what the ancient has planned...\n\n{name}, go to the Lightning Ledge. Twilight's Hammer has been running experiments with something called a \"Lightning Channel.\" Investigate these channels, then use this totem to summon the Spirit of Goldrinn and see what he has in mind... ", objectives = "" }
WordHunterWoW_QuestEN[25354] = { title = "Sweeping the Shelf", description = "The shrine is secure, the ogres in disarray. Enough. The time has come to go on the offensive.\n\nSomething sinister is underway above us, on the Lightning Ledge. It is time to unleash the fury of the ancients!\n\nFly up to the Lightning Ledge and demolish the Twilight's Hammer there. Crush them, {name}, slay their creations and hurl their bodies from the mountainside!", objectives = "" }
WordHunterWoW_QuestEN[25355] = { title = "Lightning in a Bottle", description = "Lo'Gosh granted me a vision while you were in the hovel, {name}. I saw you striding across the Lightning Ledge, with lightning bolts in your hand. The vision was powerful: Lo'Gosh feels this is of utmost importance. We must not fail the ancient.\n\nUpon the Lightning Ledge, Twilight's Hammer has been experimenting with devices they call \"Lightning Channels.\"\n\nInvestigate one of these channels, then use this totem to summon the Spirit of Lo'Gosh and learn what the ancient is planning...", objectives = "" }
WordHunterWoW_QuestEN[25356] = { title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. Shyn will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "" }
WordHunterWoW_QuestEN[25357] = { title = "Buy Us Some Time", description = "So many good men have been lost today. Without you, that number would be even higher.\n\nYou have our gratitude.\n\nIf what the shaman says is true, then there is no time to spare. The naga are scouring these waters looking for survivors.\n\nWe are not yet ready to fight. You must buy us time to make preparations. Find the naga that hunt us and delay their efforts.", objectives = "" }
WordHunterWoW_QuestEN[25358] = { title = "Nerve Tonic", description = "How am I feelin', you ask?\n\nWell, after bein' yanked from the deck of our ship by a giant sea monster and then left to drown in the sea... not so good!\n\nMy nerves are gettin' the best of me, to be honest.\n\nIf you could round up some of the supplies that are sure to be floatin' around the nearby wrecks, I could likely whip up somethin' that'll take the edge off...", objectives = "" }
WordHunterWoW_QuestEN[25359] = { title = "Toshe's Vengeance", description = "You met Toshe back in Damplight Cavern, didn't you? He followed some of the fleeing naga to a set of ruins to the east and then sent for help.\n\nFind Toshe at the ruins as soon as you can. If you find out anything about what the naga want, please let us know.", objectives = "" }
WordHunterWoW_QuestEN[25360] = { title = "Crabby Patrons", description = "These crabs are not friendly. Not. Friendly.\n\nSam's endless drilling is riling them up. I know from experience that there's no stopping Sam, so let's look into the other side of things, shall we?", objectives = "" }
WordHunterWoW_QuestEN[25361] = { title = "A New Cloak's Sheen", description = "Well met, {class}. I've traveled with my companions down to Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with the gorgeous wings I want are west of Camp Mojache.", objectives = "" }
WordHunterWoW_QuestEN[25362] = { title = "A Grim Discovery", description = "The Grimtotem clan! Those gutless traitors are still lurking around here, eh...\n\nYou have to go back, {class}. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", objectives = "" }
WordHunterWoW_QuestEN[25363] = { title = "War on the Woodpaw", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", objectives = "" }
WordHunterWoW_QuestEN[25364] = { title = "Alpha Strike", description = "Gnolls are unfortunately as resilient as they are brutish and stupid. I have driven back the gnolls time after time from our camp, and it is only our chieftain's mercy that prevents them from being wiped out entirely.\n\nOver the years, it has fallen into a dance of strength and dominance. When their numbers surge and they threaten the camp, the alphas, the strongest gnolls, must be slain.\n\nThis will drive them back into the forest, and leave us is peace until they forget their lessons.", objectives = "" }
WordHunterWoW_QuestEN[25365] = { title = "Woodpaw Investigation", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity. If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans. They have to have something--their attacks have been too coordinated to be done without them. Find them, and return to me when you have them.", objectives = "" }
WordHunterWoW_QuestEN[25366] = { title = "The Battle Plans", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", objectives = "" }
WordHunterWoW_QuestEN[25367] = { title = "Zukk'ash Infestation", description = "From what scouting we have managed to muster, we believe that the foe south of the gnolls is an insect-like race.  Frankly, it is irrelevant whether or not they're sentient.  If they are driving the gnolls to frenzy against us, then they are as big of a threat - if not more - than the gnolls.\n\nDive deep into where these Zukk'ash insects dwell; it is known as the Writhing Deep.  Thin their numbers and report back to me what you find, bringing back their carapaces as evidence of your handiwork.", objectives = "" }
WordHunterWoW_QuestEN[25368] = { title = "Verinias the Twisted", description = "The other spirits and I are bound here by a cruel demon named Verinias. He is our captor, a twisted, mindless beast who devours our souls over millennia.\n\nThe lure of the souls and arcane magic you've brought me should let you draw him out. Take this condensed essence to the dead tree at the far north of the ruins. Use it to lure Verinias and slay him, that I may finally be free...", objectives = "" }
WordHunterWoW_QuestEN[25369] = { title = "Stinglasher", description = "In surveying the Writhing Deep, one of our scouts reported seeing a giant insect - much larger than the other insects spotted - wandering about the twisted terrain.  Not only is it larger, it also seems to secrete some sort of aura that the other insects don't.  We've given it a name - Stinglasher.\n\nThe innards of this beast would be invaluable to study as we figure out the best way to deal with this new threat.  Cut out its secretion glands and bring it back to me immediately!", objectives = "" }
WordHunterWoW_QuestEN[25370] = { title = "Inciting the Elements", description = "This is no mere natural occurrence, {name}.  There must be a twilight presence behind our lines that we haven't accounted for.\n\nIt's possible that whoever is instigating the elemental disturbance is using foul magic to hide themselves from our sight.\n\nSeek the aid of the faerie dragons that roam near the World Tree; they can see through any of our enemy's illusions.\n\nFeed them the juniper berries that grow nearby to gain their trust.", objectives = "" }
WordHunterWoW_QuestEN[25371] = { title = "The Abyssal Ride", description = "If you are going to be making it anywhere in this kelp forest, we need to get you a reliable mount. I think I've come up with a better plan than the sea turtle, and it's not far.\n\nTie off a lure at the rope just west of us, and then mount the seahorse that it will attract.\n\nBe warned, you may need to work hard to break the beast.", objectives = "" }
WordHunterWoW_QuestEN[25372] = { title = "Aessina's Miracle", description = "<The finger-like branches of one of Nordu's burning limbs part, revealing an untouched, glimmering seed.>\n\nThis is the Heart of the Forest. The seed of life.\n\nTake this to your Arch Druid at Aessina's Grove - Hamuul Runetotem will know how to invoke its power. I promise you, the wilderness spirit will be silent no longer. New life will bloom from the ashes of old.\n\nThank you, {race}. My time is done.", objectives = "" }
WordHunterWoW_QuestEN[25373] = { title = "The Hilltop Threat", description = "I am proud of Mojache's reputation as a safe haven in the wilds of Feralas, but the camp faces many threats. The Gordunni ogres gather nearby in the northern foothills, claiming their territory and despoiling the wildlife.\n\nWith the arrival of our brothers and sisters seeking shelter, I cannot let them linger any more. Go north and drive the ogres out.", objectives = "" }
WordHunterWoW_QuestEN[25374] = { title = "Sasquatch Sighting", description = "You may have seen this with your own eyes, but my longrunners have reported something disturbing to me. The gordunni in the hills have captured an enormous sasquatch from the wilds.\n\nI don't know how long it's been held, but ogres are not ones for hobbies. I fear they plan to unleash the tortured beast on Camp Mojache.\n\nReturn to the deepest corner of the Gordunni Outpost and slay the sasquatch, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25375] = { title = "Taming The Tamers", description = "The gordunni are not known to tame animals. If they're learning, this is cause for alarm. While the sasquatch they've tamed may be the major threat to our camp, the gordunni who captured him should be dealt with as well. If left, they may simply capture another.\n\nKill the gordunni tamers, and make sure the ogres know their efforts will not be tolerated!", objectives = "" }
WordHunterWoW_QuestEN[25377] = { title = "The Horde's Hoard", description = "It is unclear what manner of creature scrawled the seemingly random markings on this piece of parchment, but upon close inspection, some of the obscure shapes begin to look like landmarks.\n\nScanning the sea floor, you think you recognize a few points of reference, one being a nearby sunken ship. If your guess is correct, there appears to be treasure of some kind near the wreck.\n\nYou cannot help but wonder what the scaly, serpentine figure on the map might represent....", objectives = "" }
WordHunterWoW_QuestEN[25378] = { title = "Ysondre's Call", description = "The dragons of nature... Heed her call, {name}. Do not linger here. Her request for your aid is both a great honor and an omen of terrible danger.\n\nThe place she spoke of is called the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; you will find a small shrine at the top.\n\nAll of Feralas may rest upon your shoulders. May the Earth Mother watch over you.", objectives = "" }
WordHunterWoW_QuestEN[25379] = { title = "Taerar's Fall", description = "Emeriss and Lethon are gone. It's only us left now. I can hide from this no longer. All I did while a part of that brood...all the suffering I've caused...must be repaid today.\n\nI am still weak, {name}. I cannot assume my true form even if I dare try. But I will still stand beside you in battle.\n\nIf you are prepared, I will call Taerar to us. He will be unable to resist the temptation of revisiting corruption upon me.", objectives = "" }
WordHunterWoW_QuestEN[25381] = { title = "Fighting Fire With ... Anything", description = "The inferno raging up ahead marks the front line between us and the forces of the Fire Lord. The fire elementals unleashed here are unlike any I've ever encountered.\n\nCan you help us stem the tide of destruction? Slay the raging firestorms... before they engulf Aessina's Grove and erase all hope of someday reclaiming this mountain!", objectives = "" }
WordHunterWoW_QuestEN[25382] = { title = "Disrupting the Rituals", description = "The firestorms up ahead are unbound elementals in the purest form - something I didn't think could exist outside their own plane. Only very skilled summoners could unleash something like this.\n\n{name}, head into the Inferno and seek out Twilight Inferno Lords. They've got to be summoning in reinforcements as we speak. Silence them... For good!", objectives = "" }
WordHunterWoW_QuestEN[25383] = { title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", objectives = "" }
WordHunterWoW_QuestEN[25384] = { title = "Raw Materials", description = "Thank you, {class}. We owe you our lives.\n\nBut if we're ever to see the surface again, we'll have to fight our way out of here. That means I'm going to need to craft some weapons and armor.\n\nBefore you found me, I saw a soldier eaten by one of those orca up there.\n\nI'll wager that if you cut a few of them open, you'll find plenty of scrap metal for me to work with.\n\nIf you don't want to swim up to them, I bet you could lure one down to you with some entrails...", objectives = "" }
WordHunterWoW_QuestEN[25385] = { title = "Save the Wee Animals", description = "Help us, {class}! The forest is aflame, and the wee animals can't find their way out. They can't fight for themselves, with their teeny-tiny little teeth and their soft furry paws! They're fluffy and sweet.\n\nThey have wet little noses!\n\nIf you don't save them, I don't want to even THINK about it.\n\n<She slaps her palms over her eyes.>\n\nI'm not thinking!", objectives = "" }
WordHunterWoW_QuestEN[25386] = { title = "To Stonemaul Hold", description = "You must send word of what has happened here, {name}. To the south is Stonemaul Hold. There, our allies have gathered the few ogres of the horde to fight against those despoiling these forests.\n\nSpeak with Orhan Ogreblade. She leads the Stonemaul clan here, and will need to know of all that has occured. And be wary, lest some of this corruption remain...", objectives = "" }
WordHunterWoW_QuestEN[25387] = { title = "To Camp Mojache", description = "You've done a hell of a job here, {name}. With the Twilight's Hammer shamed and the Gordunni left bleeding and broken, we'll be able to set our sights on the true battle with the Alliance here.\n\nIt'll take time to build our forces enough to match the night elves infesting this place. I'm sending you ahead to Camp Mojache to the east; they've got problems of their own, and we can't let any Horde territory fall here.\n\nLok'tar!", objectives = "" }
WordHunterWoW_QuestEN[25388] = { title = "Crate of Crab Meat", description = "This crate, labeled 'Crab Meat', seems to have fallen from a recently sunken cargo ship.\n\nAdarrah would surely welcome such a find, considering the ordeal she's had to endure.", objectives = "" }
WordHunterWoW_QuestEN[25389] = { title = "A Taste For Tail", description = "It could be days before we're ready to make our way to the surface, and to be honest, I'm already beginning to get hungry.\n\nI hate to be picky, but when it comes to seafood, I'm afraid there are very few things I can stomach.\n\nIf you come across any lobster types, I would happily pay you what coin I have with me for their tails.", objectives = "" }
WordHunterWoW_QuestEN[25390] = { title = "A Girl's Best Friend", description = "Let's just get it out in the open. I'm no stranger to love, {name}.\n\nOver the years, if there's one thing I've learned, it's that love's tangible treasures last longer than the flames of passion.\n\nI've managed to collect my fair share of these gifts - gemstones, rings, necklaces, and the like, and I carry them with me wherever I go.\n\nAt least I used to...\n\nWhen I was swept from the ship, my valuables were scattered across the sea. Help me recover them and I promise to make it worth your trouble.", objectives = "" }
WordHunterWoW_QuestEN[25391] = { title = "Weapons of Spirit", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", objectives = "" }
WordHunterWoW_QuestEN[25392] = { title = "Oh, Deer!", description = "Do you speak deer? It's all in the nose.\n\n<She points to her nose.>\n\nThe does have fled the fires, but their little fawns - Some of them are still trapped in the burning and the hurt!\n\nGo back into the Inferno and escort three injured fawns back here to their mothers right here beside me.\n\nPlease save the little fawns, or I'll give you the big eyes!\n\n<Her eyes grow big and dewy.>", objectives = "" }
WordHunterWoW_QuestEN[25393] = { title = "Operation: Gnomeregan", description = "Momentarily, the multi-phased assault upon Gnomeregan will begin and Mekgineer Thermaplugg and his men will be brought to justice!  Too long has Thermaplugg festered in the depths of our home, defended by a corrupt and irradiated army.\n\nThe assault begins in but a moment! Be ready recruit, this fight will not be for the faint-hearted.", objectives = "" }
WordHunterWoW_QuestEN[25394] = { title = "More Than Illness", description = "I've discovered a brood of dragon whelps gathered off the road to the north with a similar affliction. Green dragons are sacred custodians of nature. The fact that this disease is capable of spreading to them is cause for great alarm.\n\nWe must stop this from spreading further through any means. Slay the infected whelps, {name}, and return to me.", objectives = "" }
WordHunterWoW_QuestEN[25395] = { title = "The Stolen Keg", description = "You've got to help us, lad. We were tasked with escorting a precious cargo to our fellow dwarves...a keg full of the finest ale you can get out here!\n\nUnfortunately, bird-brain over here fell asleep on the job! Those blasted orcs took our keg, and hauled it up into Dun Algaz where they're hiding.\n\nThis can't stand! Now, while I stay here and try to convince this idiot that it was his fault, I'd like you to go in there and get our keg back. For Khaz Modan!", objectives = "" }
WordHunterWoW_QuestEN[25396] = { title = "Tears of Stone", description = "As you witnessed, the dragon Ysondre has told us that the tears of the land can seal the portal from which this corruption stems.\n\nHer words ring true; in the glade to the west, I have seen the mountain giants distraught. They raged in frustration and wept, and their tears fell upon the stones as shining crystals.\n\nThough the giants weep no more, these stonetears must be what Ysondre referred to. We must gather them.", objectives = "" }
WordHunterWoW_QuestEN[25397] = { title = "The Land, Corrupted", description = "The cliff giants of Feralas are extensions of the earth itself, {name}. When nature thrives, they are benevolent protectors and peaceful guardians.\n\nBut as the forest is tainted, so too are they.\n\nShould they be corrupted by this malady, they will lash out in violence against trees, wildlife, and the very boulders they were shaped from.\n\nBe wary in your tasks. Should you find any corrupted giants, destroy them, for the sake of those still spared.", objectives = "" }
WordHunterWoW_QuestEN[25398] = { title = "Sealing the Dream", description = "It is ready. Take this, {name}; a beacon of natural essence, blessed by the will of Ysondre.\n\nTo the north, on the other side of the flowing brook, is Dream Bough. There stands the Great Tree, the tallest in Feralas, a sapling of the very World Tree. A portal to the heart of the Emerald Dream sits in its trunk, and it is this portal you must seal.\n\nThe portal will be guarded, but you must be brave.", objectives = "" }
WordHunterWoW_QuestEN[25399] = { title = "Hatecrest Forces", description = "The Hatecrest are fighting fiercely! Their leader is a priority, but we need to kill as many of them as we can.\n\nGo ahead of me, I'll meet you on the battlefield. Show them no mercy!", objectives = "" }
WordHunterWoW_QuestEN[25400] = { title = "The Gordunni Threat", description = "Estulan, the Highborne up in the tower, is reclusive. I haven't been able to speak to him very much. He has, however, told me that the ruins of the High Wilderness to the south are full of Gordunni ogres.\n\nThe ogres are not only a threat, they're destroying any forest and wildlife nearby. Estulan has also warned me of what might happen if they discover any artifacts of Highborne power among the ruins...\n\nHead south, {name}, and slay any Gordunni you find!", objectives = "" }
WordHunterWoW_QuestEN[25401] = { title = "The Gordunni Orb", description = "In addition to clearing out the ogres...\n\nEstulan mentioned something else about the ogres. He said the ogre warlocks may have some sort of orb, or other item of power\n\nHe was terse about it, but seemed upset...he said there was \"no way they could be Highborne\", so I think he wants to know just where they got them. Bring me back one of these orbs.", objectives = "" }
WordHunterWoW_QuestEN[25402] = { title = "Estulan's Examination", description = "He's right. I haven't been among the night elves long, but I can tell these markings are completely unlike any kaldorei decorations...\n\nEstulan needs to see this. Take this up the tower to him. He may be surly, but don't be dissuaded; once he sees the orb, he'll realize it's an important issue.", objectives = "" }
WordHunterWoW_QuestEN[25403] = { title = "Ogre Abduction", description = "This is neither a crude ogre trinket, nor an ancient relic made by my kind. Its specific construction is new to me...and this fact disturbs me greatly.\n\nThe wolf-girl will be sending you to Dire Maul soon, to fight the Gordok elite. They are the leaders of the Gordunni, and would know who is supplying these.\n\nTake the orb back, I've cast a few enchantments on it. Hold it up in front of a weakened Gordok ogre, and once you've captured him, bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[25404] = { title = "If You're Not Against Us...", description = "South of here you'll find a solitary tower, known as \"Blackhorn's Penance.\" Upon it is bound a demon: Tyrus Blackhorn.\n\nYou may think me mad for turning to an old foe for help, but Blackhorn was once a mortal, and I can't imagine he wants to watch Twilight's Hammer triumph.\n\nSpeak with Blackhorn, and see if you can convince him to help us in our fight. He may yet redeem himself.\n\n...Just don't set him free!", objectives = "" }
WordHunterWoW_QuestEN[25405] = { title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", objectives = "" }
WordHunterWoW_QuestEN[25406] = { title = "Gordok Guards", description = "With the nearby ogres dealt with, we should take the offensive and press our attack into their territory.\n\nThe Gordok ogres are the head of the Gordunni clan, ruling them from the ruins now called Dire Maul. They are stronger than the lesser Gordunni, but I have no doubt you can handle them, {name}. They won't know what hit them.", objectives = "" }
WordHunterWoW_QuestEN[25407] = { title = "Forces of Nature: Wisps", description = "The Sentinels make up the bulk of our forces here, but a well-rounded night elf army requires more than just night elves. The creatures of this forest, our ancestral home, have protected us for centuries. We simply need to rally them.\n\nTake this whistle. Our allies know this sound, and you'll be using it to recall them.\n\nBefore you start gathering creatures, I'd like you to recall a few of our wisps, just for practice. You can find them just outside the fortress, among the trees.", objectives = "" }
WordHunterWoW_QuestEN[25408] = { title = "Seeds of Their Demise", description = "We will decimate the Twilight's Hammer by corrupting and subverting them. \n\nSeeing that you have no intention of releasing me from my bonds, I require you to collect some reagents for me. My own demonic essence has corrupted the plant life around my shrine here. I need you to harvest some bileberries from the wailing weeds that surround this tower.\n\nMy little pets will attempt to harvest YOU in return. Try not to let them agitate one another.", objectives = "" }
WordHunterWoW_QuestEN[25409] = { title = "Forces of Nature: Hippogryphs", description = "Hippogryphs are majestic creatures. Some say they were created by Cenarius himself as a gift for the night elves. They're wary of other races, but they're intelligent enough to recognize a friend of a friend.\n\nI need more hippogryphs here so we can begin training some of our newer archers to ride them. Take the whistle again and rally the Frayfeather hippogyphs in the grove just south of the Tower of Estulan.", objectives = "" }
WordHunterWoW_QuestEN[25410] = { title = "Forces of Nature: Treants", description = "Some people think treants are good for little more than fetching drinks in a war. Most of them haven't seen an entire defensive line scattered by what they thought was cover.\n\nAnd have you ever seen a peon try to chop one down and get surprised? I was in tears...\n\nAt any rate, they're immensely valuable allies. You'll find some wandering just outside  the Tower of Estulan and more in forest to the east, just southeast of Dire Maul. Be on the lookout for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[25411] = { title = "A New Master", description = "The potion you created is vile enough to wake the dead. Which is its intended purpose.\n\nSlay a Twilight Inferno Lord and force the brew down his throat. He will revive, if only briefly, and be completely under your dominance.\n\nSpeak with him and learn the true name of the fire elemental he is channeling into the world to burn down your precious forest.", objectives = "" }
WordHunterWoW_QuestEN[25412] = { title = "The Name Never Spoken", description = "We called upon the fury and flame of the One, my former master.\n\nThe Inferno is by His design.\n\nHis true name is never uttered, it holds His power.\n\nEach of us was told but a piece. Each piece engraved on a firestone.\n\nThe One's true name is here, in the Inferno. Seek the three stones...", objectives = "" }
WordHunterWoW_QuestEN[25413] = { title = "Change of Plans", description = "Alright, kid. Slight change of plans...\n\nI think I've figured out a way to finish off that monster and you're going to assist me.\n\nThe way I see it, you owe me until my work is done here, and I ain't leaving without that artifact.\n\nFirst I need you to search those old wrecks for some good rope and a serviceable harpoon.\n\nThen... well, I'll fill you in on the rest later.", objectives = "" }
WordHunterWoW_QuestEN[25419] = { title = "Lady La-La's Medallion", description = "Dozens of crude gold links make up this heavy chain.\n\nDangling from the center link is an opalescent fragment of what must have once been a large shell-shaped medallion.\n\nYou wonder if the other fragments might be nearby, and if the medallion might be reassembled into its original state.", objectives = "" }
WordHunterWoW_QuestEN[25420] = { title = "Ancient Obstacles", description = "I've studied the gate here for years, trying to find a way of entry that wouldn't disturb any of the ancient architecture just behind it. It figures a few overgrown earthquakes decided to muck the whole thing up! But what's done is done, and the entrance to Uldum is revealed.\n\nI wasn't expecting anything to come out of the ruins before we went in, though. A whole mess of golems are running amok in the valley now, let loose from inside. Someone needs to clean them up if we're gonna get in there!", objectives = "" }
WordHunterWoW_QuestEN[25421] = { title = "The Grand Tablet", description = "At the bottom of the chest, you find a large tablet. Made of a material resembling stone, but completely smooth and flawless, it is covered in strange writing.\n\nWhile some resembles the writing on the walls, other scripts appear completely different. Gunstan would probably like to see this.", objectives = "" }
WordHunterWoW_QuestEN[25422] = { title = "The Darkmist Legacy", description = "I am chained to this place...it takes so much effort just to speak to you. I can barely maintain this shape.\n\nI could help you, but please, help me pull myself together first. Once I'm more focused on this plane, I should be able to do it...\n\nIf I could just leave this tomb, the soil itself outside is full of ancient arcane deposits, laying forgotten for centuries. Could you bring me some?", objectives = "" }
WordHunterWoW_QuestEN[25423] = { title = "Ancient Suffering", description = "You must be careful when you venture forth. Other spirits are bound to this place, malevolent and hateful ones. They've all suffered so much.\n\nNone of what they used to be remains, only suffering and a will to live. We will need that will to summon the overlord that keeps me bound here. Please, gather the essence of the spirits, and bring it back to me.", objectives = "" }
WordHunterWoW_QuestEN[25424] = { title = "Return to Alysra", description = "I thank you for freeing me, {name}.  I will tell our allies of my findings.\n\nI suggest that you return to the emerald dragon that sent you.\n\nThe Twilight's Hammer does not just seek to gain territory with this particular attack.  They're also after a prisoner.\n\nFandral Staghelm is being held in the Barrow Dens.  The attack doubles as a distraction to free him.  To what end, I cannot tell.  Perhaps our dragon ally can shed some light on this.", objectives = "" }
WordHunterWoW_QuestEN[25426] = { title = "War on the Woodpaw", description = "The first of Shandris's direct orders is to deal with the Woodpaw gnolls here. They've been spreading too far, too fast, and are becoming a threat to both the forest and our war effort.\n\nThey know we're here. After we took this camp, we've been leading covert strikes against them. It's time to make a major blow; bring back ten of their manes, and we'll be ready for the next phase.", objectives = "" }
WordHunterWoW_QuestEN[25427] = { title = "Alpha Strike", description = "Never underestimate a threat. These gnolls may seem like simple brutes, but there's animal cunning even among them.\n\nThe gnolls run as a pack, and every pack has Alphas: The biggest, strongest, and most ruthless members that claw their way to dominance. They're the ones giving orders, so they're the ones we're going to slay now.\n\nThey reside mostly around the Woodpaw Den, pushing the others around. Get out there and push harder.", objectives = "" }
WordHunterWoW_QuestEN[25428] = { title = "Black Heart of Flame", description = "Now you will use our newfound knowledge to pull Thol'embaar into the mortal plane like a babe screaming from the womb. Then you will crush him.\n\nThe ritual is simple: take this charred branch, tap it on the ground three times, and utter his name aloud.\n\nYou must call him from within the heart of the Inferno. Destroy him, and bring his black heart back to me.", objectives = "" }
WordHunterWoW_QuestEN[25429] = { title = "Zukk'ash Infestation", description = "With the gnolls out of the way, we're ready to take care of other foes. Our scouts have discovered what appears to be a hive nearby, extending deep beneath the ground.\n\nThe insects of the hive are large and ferocious, and most likely pose an even greater threat than the gnolls. I want you to proceed to the hive with caution. Cut down a good portion of the bugs and bring back their carapaces for further study.", objectives = "" }
WordHunterWoW_QuestEN[25430] = { title = "Emerald Allies", description = "The druids of Hyjal are not the only ones sworn to defend this land.  The emerald dragons have once again become a powerful ally to our cause.\n\nSpeak to Alysra at the Ruins of Lar'donir, to the north, and see what you can do to help.", objectives = "" }
WordHunterWoW_QuestEN[25431] = { title = "Stinglasher", description = "Most of the insects we've seen wandering the hive have been enormous enough, but my scouts reported an especially huge one. It's supposedly a massive wasp, and it seemed to be directing the workers on the surface.\n\nI don't know much about these things, but if they're starting to wander beyond that pit in the ground, we need to put a stop to it. Kill this giant wasp and return to me.", objectives = "" }
WordHunterWoW_QuestEN[25432] = { title = "It's Not \"Ogre\" Yet", description = "We dealt the Gordunni ogres a large blow at Dire Maul, but we haven't quite finished the job. My scouts have reported a group of them amassed in the hills to the north, gathering for some reason.\n\nIt's possible they're interested in the Horde settlement nearby, but I don't want to take any chances. Scout the area, kill any ogres you come across, and report back.", objectives = "" }
WordHunterWoW_QuestEN[25433] = { title = "Sasquatch Sighting", description = "You may have seen it yourself, but other scouts have discovered an enormous beast being held by the ogres. Reports say it looks like a sasquatch, but if it is, it's the biggest ever seen in Feralas.\n\nThe ogres are most likely trying to teach it to obey them. While that's almost comical, I'm not going to sit by and let them train that thing to roll over at their command. Return to the hills and slay it.", objectives = "" }
WordHunterWoW_QuestEN[25434] = { title = "Taming The Tamers", description = "The sasquatch may be a larger threat, but we also need to wipe out the ogres. The Gordunni have been a nuisance to us for too long, and Lady Shandris wants them completely gone.  Let's hope these are the last ones.\n\nKill the Gordunni tamers that keep the beast chained, and make sure they know the price of their meddling.", objectives = "" }
WordHunterWoW_QuestEN[25435] = { title = "Pressure is Mounting", description = "G'day, laddie.\n\nThe name's Rendel.\n\nSeems ol' Moanah and I got here in the nick of time, eh?\n\nErunak wasn't kiddin' when he said it was life or death!\n\nWhile he's tryin' to find us a safe place to hole up, I'm gunna take a stab at securin' you a critter to ride.\n\nNow, I may not be up on all the ins an' outs of life in the sea, but it looked to me like them naga know how to get around down here.\n\nYou round up a few widgets for a bridle and I'll work up an enchantment.", objectives = "" }
WordHunterWoW_QuestEN[25436] = { title = "Spiteful Sisters", description = "Something truly disturbing has occured. While on patrol, several of my scouts were ambushed by dryads.\n\nThe dryads are close allies of the night elves and guardians of the forest. I assumed they were just frightened by the sight of worgen, but the sentinels I sent out afterwards were also attacked.\n\nWhatever is going on, I don't like it. I want you to go investigate as well. If even the dryads have been corrupted...put them to the sword.", objectives = "" }
WordHunterWoW_QuestEN[25437] = { title = "Ysondre's Call", description = "A dragon of the emerald dream... what have you gotten yourself involved in, {name}?\n\nI wouldn't keep her waiting if I were you. The place she spoke of is what we call the Emerald Summit. A path off the main road through the Lower Wilds leads up one of the high stone plateaus; there's a small shrine at the top.\n\nGood luck, {name}. I hope to see you back safe.", objectives = "" }
WordHunterWoW_QuestEN[25438] = { title = "Ysondre's Farewell", description = "With that, I am the only one left.\n\nEven if I choose to remain in this world, I cannot rejoin the green flight. But this victory gives me hope. Perhaps, in time, I can find peace in a simple life among mortals.\n\nYou must return to your people. Tell them that the dragons of nightmare are gone, and will no longer threaten these lands.", objectives = "" }
WordHunterWoW_QuestEN[25439] = { title = "Vengeful Heart", description = "These are the naga that took our people. I only need one to interrogate, kill the rest.\n\nShow no mercy, {class}, for they would surely show us none.", objectives = "" }
WordHunterWoW_QuestEN[25440] = { title = "Fathom-Lord Zin'jatar", description = "The Fathom-Lord is here, at the far side of the ruins. He's still injured from our last battle.\n\nI'll leave this pleasure to you. Make sure he doesn't get away this time.", objectives = "" }
WordHunterWoW_QuestEN[25441] = { title = "Vortex", description = "I have no fondness for snakes, and even less so down here. Fortunately for us, the watery elements still bend to my will for now.\n\nTake these globes and throw them at the ground to send the nearby water into a vortex, pulling in all the nearby serpents. The naga will most certainly turn the snakes against us, so keep the orbs close at hand.", objectives = "" }
WordHunterWoW_QuestEN[25442] = { title = "A Pearl of Wisdom", description = "This pearl is unlike anything you've ever seen before. It radiates light, and if you are not mistaken, it radiates powerful magic as well.\n\nEarthmender Duarn back in Silver Tide Hollow will surely be interested in this.", objectives = "" }
WordHunterWoW_QuestEN[25443] = { title = "The Name Never Spoken", description = "Did my drought work? You spoke with one of them?\n\nThen you know what to do. The name of their elemental master is written on three firestones scattered throughout the Inferno. Examine each of these stones and we will have the name we need.\n\nHurry! Your precious forest burns!", objectives = "" }
WordHunterWoW_QuestEN[25444] = { title = "Da Perfect Spies", description = "Now, it would be foolish to go in blind 'ere, so I be creatin' some tiny spies to gather information for Vol'jin. He got to know what's goin' on over on de islands.\n\nI could use da help, if you be feelin' up to it. I tell ya how it's done. First, ya gotta catch de frogs. Dey like to stay in de shade of da palm trees around Sen'jin.\n\nOnce ya have de frogs, bring 'em over here to my sentry totem an' attune dem to me sight.", objectives = "" }
WordHunterWoW_QuestEN[25445] = { title = "Zalazane's Fall", description = "De time for battle is now!  We'd be headin' ova to da islands soon, so you'd betta be ready.\n\nZalazane doesn't have much time left.", objectives = "" }
WordHunterWoW_QuestEN[25446] = { title = "Frogs Away!", description = "Wit de frogs ready to go, I be needin' ya to help me send 'em out to the isles.\n\nOn de eastern side of Sen'jin Village, ya can find Handler Marnlek. He be handlin' all the bats for Vol'jin's scouts and he can loan ya a bat to get ya out to de isles.\n\nTake dis sack' o frogs with ya. I been askin' de spirits for guidance. Dey've sent smoke to show ya where I need de eyes most. While ridin' de bat, reach into de sack and toss de frogs toward de white smoke.", objectives = "" }
WordHunterWoW_QuestEN[25447] = { title = "Signs of Change", description = "A severe illness has fallen over the creatures of this forest. While at first I hoped it was part of nature's course, it has refused to pass.\n\nThe forest stags, normally strong and serene, have suffered the worst. Some waste away in weakness; others froth and rage dangerously. If I am to consult the spirits to learn more of this sickness, I will need the stags' antlers.", objectives = "" }
WordHunterWoW_QuestEN[25448] = { title = "The Northspring Menace", description = "My duty here is to watch over Telaron. Even without his meditation leaving him vulnerable, there's enough threats in this forest to keep both of us on our toes.\n\nThat's why it maddens me so much that I don't have the opportunity to leave camp. More harpies than I've ever seen infest the northwest...foul creatures, spreading their filth across the ancient ruins uncaringly.\n\nThey're a threat to this camp, and have no place in these lands. I'll pay you well if you get rid of them.", objectives = "" }
WordHunterWoW_QuestEN[25449] = { title = "The Mark of Quality", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises. Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides. The Yeti are native to Feralas, with many found in Rage Scar Hold to the northeast. I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair, then we're in business.", objectives = "" }
WordHunterWoW_QuestEN[25450] = { title = "Improved Quality", description = "It's funny how things change. The northern yetis used to yield the best hides, but these...there's been a decline in quality, it seems. Maybe something nearby is making them sick.\n\nLuckily, the Feral Scar yetis to the southeast have flourished. I bet their hides are even better than they used to be!\n\nI would reward you handsomely for a stack of ten of their hides; bring them to me here, and we'll finish our business.", objectives = "" }
WordHunterWoW_QuestEN[25451] = { title = "Pristine Yeti Hide", description = "You have found a pristine yeti hide that is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Pratt McGrubben at the Feathermoon Stronghold is in the market for yeti hides, this particular one may be of considerable interest to him.", objectives = "" }
WordHunterWoW_QuestEN[25452] = { title = "The Mark of Quality", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found north of here in Rage Scar Hold.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", objectives = "" }
WordHunterWoW_QuestEN[25453] = { title = "Improved Quality", description = "I'm a bit confused. The Rage Scar yeti used to be the finest source of leather in these lands... but these pelts are weak and even rotted in spots. Some sort of illness must be plaguing the creatures.\n\nI'll have to rely on a different source. The yeti of Feral Scar Vale to the south have hides nearly as strong. They are also a great deal fiercer; do not hunt them without caution, {class}.", objectives = "" }
WordHunterWoW_QuestEN[25454] = { title = "Perfect Yeti Hide", description = "You have found what may very well be a perfect yeti hide.  You easily note that it is exceptionally thick and sturdy - more so than even the ones you've seen from the yeti in Rage Scar.\n\nConsidering that Jangdor Swiftstrider at Stonemaul Hold is in the market for yeti hides, this particular one may be of considerable interest to him.", objectives = "" }
WordHunterWoW_QuestEN[25455] = { title = "A Test of Wills", description = "Arright, laddie here we go.\n\nYou just need to sneak up on one 'a them naga while they ain't lookin' and use this bridle on 'em.\n\nDon't get too close, now! Ya gotta surprise 'em.\n\nDo it right an' get 'em under your control, and it'll be time ta show 'em who's boss!\n\nJust keep yankin' the reins 'til their will is broken, and you'll have yerself a fancy ride!\n\nGo on, now. Go git you one! I think I can see one just north 'a here...", objectives = "" }
WordHunterWoW_QuestEN[25456] = { title = "Back in One Piece", description = "Yeah yeah, I'm sure Felora wants you back. That woman has no respect for innovation. When I told her about the modifications I was making for my Earth Elemental, she nearly threw a fit.\n\nGo tell her everything's all well and dandy. And tell her she's not getting a share of my inevitable fortune either.\n\nShe probably likes sleeping on the rock anyway.", objectives = "" }
WordHunterWoW_QuestEN[25458] = { title = "General Skessesh", description = "The leader of these forces must fall! The naga's offensive will be broken with no one to command them.\n\nI saw the coward retreat into one of the abandoned buildings here. Cut your way through the others and take his head! Lady Shandris will want to see it for herself.", objectives = "" }
WordHunterWoW_QuestEN[25459] = { title = "Ophidophobia", description = "If there's one thing I can't stand, it's snakes. Any kind of snake - doesn't matter.\n\nWhile I was out searching for salvage, I saw a nest of sea serpents surrounding the nearby wreckage.\n\nI simply can't relax knowing that those awful creatures could slither up in here at any moment.\n\nPlease, {class}! Do something about them!", objectives = "" }
WordHunterWoW_QuestEN[25460] = { title = "The Earth Rises", description = "The effects of the Twilight's Hammer attack can be felt even here, this close to the world tree.\n\nAs our forests burn, the very earth turns against us in a crazed frenzy.\n\nWe can't allow the elementals to go unchecked.  Go and help our men take care of them.", objectives = "" }
WordHunterWoW_QuestEN[25461] = { title = "Trollin' For Volunteers", description = "Vol'jin has given me his war drums and put  me in charge of trainin' da new recruits here. Only problem is we be short on new recruits.\n\nSupposin' I loaned ya dis drum, would ya use it to sound de call to war on Vol'jin's behalf in Razor Hill? If ya could even inspire just a few trolls to join da cause, it would make a difference. Once ya've convinced dem to volunteer, bring dem back to me for trainin'. Go over an' talk to Handler Marnlek to de south. He can lend you a bat for de ride to Razor Hill.", objectives = "" }
WordHunterWoW_QuestEN[25462] = { title = "The Bears Up There", description = "Do not fear the bears in this grove, {class} - I have pacified them for the moment.\n\nMy concern at present is for the welfare of the bear cubs. The fires drove the little ones up the trees, where they've gotten stuck. We've got to get those bears safely to the ground!\n\nFlying creatures frighten them, so you'll have to climb the trees yourself. Look for footholds at the trunks. Climb the trees, grab the bear cubs, and toss them - GENTLY! - onto the target here.\n\nNothing can go wrong with this plan.", objectives = "" }
WordHunterWoW_QuestEN[25463] = { title = "Report to Silvia", description = "A Highborne mage named Estulan, estranged from his surviving brothers, has built a tower to the east where he trains young night elves in arcane magic.\n\nWere it not for Lady Tyrande's recent mercy towards his kind, his execution would be my duty under the law. He will be watched closely, but I will not deny aid to my Sentinels simply out of pride.\n\nI've sent Silvia ahead to the Tower of Estulan to begin an offensive against the ogres infesting the nearby forest. Report to her for further orders.", objectives = "" }
WordHunterWoW_QuestEN[25464] = { title = "The Return of Baron Geddon", description = "Ragnaros is not the only powerful elemental that has re-emerged into our world.\n\nThe dreaded Baron Geddon is leading the onslaught and we must put an end to this rampage.\n\nThe Flameseer's Staff has proven powerful.  Perhaps it is powerful enough to weaken him to the point where our arch druids can bind him where he stands.\n\nGo, {name} and be careful.  Baron Geddon is a vengeful and treacherous being.", objectives = "" }
WordHunterWoW_QuestEN[25465] = { title = "Still With The Zapped Giants", description = "Hey pal! I'm still working on a variant of a gnomish shrinking ray, using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on some of the sea giants along the coast here.  You should find miniaturization residue on them after you shrink them - bring me back some!", objectives = "" }
WordHunterWoW_QuestEN[25466] = { title = "Even More Fuel for the Zapping", description = "If I bet against my own better judgment and stay to run an engineering shop along the Forgotten Coast, I will need to deal with these pesky elementals.  Curse the powers of elementalism unchecked, I say!\n\nFortunately for me, and now for you my hopeful agent provocateur, the elementals represent an ideal source of raw power for my Ultra-Shrinker refinement - give them the what-for I say!  When doing this though, be sure to save me the water elemental cores!", objectives = "" }
WordHunterWoW_QuestEN[25467] = { title = "Kliklak's Craw", description = "You are pleasantly surprised to find that after being mangled and masticated by a sea crab, this map is still quite legible.\n\nIt clearly indicates that a footlocker was buried in the Kelp'thar Forest behind a gigantic mollusk.\n\nA well-drawn sketch on the back of the map shows that the owner, along with his key, was eaten by an overgrown crustacean named Kliklak.", objectives = "" }
WordHunterWoW_QuestEN[25468] = { title = "Forces of Nature: Faerie Dragons", description = "You wouldn't know it from looking at them, but the lovely faerie dragons that inhabit this forest can be truly fearsome if trained properly. They can do amazing things to magical energy...absorb it, redirect it, even nullify it entirely.\n\nThey're nearly harmless alone, but in large numbers, they can have a stunning effect on a battle. You can find some in the fields to the northwest, but be careful, the Horde is nearby.", objectives = "" }
WordHunterWoW_QuestEN[25469] = { title = "Forces of Nature: Mountain Giants", description = "The mountain giants are our most powerful allies of the forest. They're carved from the land itself.\n\nNot many of our enemies are willing to fight off a walking hillside. It only takes a few of these to turn the tide of a battle completely.\n\nThe mountain giants here have been afflicted by some illness lately, but I've seen a healthy group of them to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[25470] = { title = "Lady Of Da Tigers", description = "Remember de frogs ya made into me eyes and ears? Well, dey've found somethin' interestin'.\n\nOn an island to de southeast, dey've spied a tiger even de other cats seem to fear. Dis tiger, I've never seen anythin' like it.\n\nIt hunts wit' da instincts of a cat, but de mind of a person. It could be a powerful spirit and a strong ally.\n\nI'll be callin' down the spirit o' the tiger upon ya. Use its gifts to locate this cat and challenge it. See if ya can win its aid in our battle for the isles.", objectives = "" }
WordHunterWoW_QuestEN[25471] = { title = "Across the Great Divide", description = "We will need to press deeper into Vashj'ir if we want to uncover what the naga are doing here.\n\nGo to the Lightless Reaches, the giant chasm bordering the Kelp'thar Forest to the west.  If you look across it, you should see a cluster of plant-life surrounding the entrance to Damplight Chamber.\n\nOnce you're inside the cave, it's a bit of a ride up until you break surface, but I have friends there that should provide you a warm welcome.", objectives = "" }
WordHunterWoW_QuestEN[25472] = { title = "The Flameseer's Staff", description = "A powerful artifact known as the Flameseer's Staff was lost during the initial onslaught by the enemy forces.  It was an ancient bone staff that granted its wielder power over the elements of fire.\n\nIts fragments litter the area around us.  Find them and bring them to Malfurion.  Perhaps the artifact's power will still be of use.", objectives = "" }
WordHunterWoW_QuestEN[25473] = { title = "Kaja'Cola", description = "Sassy's been riding me to supply some Kaja'cola for the party that's being thrown in your honor later today.\n\nOops, was it supposed to be a surprise? You didn't hear it from me!\n\nAnywho, with production down these last few days, this is all that I managed to get made. Would you take it to her?", objectives = "" }
WordHunterWoW_QuestEN[25474] = { title = "Once More, With Eeling [DEPRICATED]", description = "Eels are among the creepiest of Azeroth's creatures.\n\nSure, there are those who pretend that they don't mind them - and others who actually claim to favor them.\n\nThey are lying.\n\nTruth be told, no one likes eels. Eels don't even like eels.\n\nAzeroth would be a better place if no one ever had to envision an eel slithering out from the murky depths and biting them.\n\nIn the face.", objectives = "" }
WordHunterWoW_QuestEN[25475] = { title = "Find OOX-22/FE!", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", objectives = "" }
WordHunterWoW_QuestEN[25476] = { title = "Rescue OOX-22/FE!", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the main road!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", objectives = "" }
WordHunterWoW_QuestEN[25477] = { title = "Better Late Than Dead", description = "Greetings, friend.\n\nIt is good to see that you survived your battle in one piece.\n\nWhile Erunak tries to scry a place of safety for us all, I shall assist you in securing a less strenuous means of transport.\n\nI have prepared this baitstick to use near a sea turtle. It is crude, but it should serve to bring one under your control.\n\nOnce you've become comfortable with the animal, simply guide it back here to me.", objectives = "" }
WordHunterWoW_QuestEN[25478] = { title = "To the Summit", description = "We are staging a relief effort at Westreach Summit for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my wind rider to safely get you there. Speak with Kanati Greycloud when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "" }
WordHunterWoW_QuestEN[25479] = { title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. The goblin, Dyslix Silvergrub, will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "" }
WordHunterWoW_QuestEN[25480] = { title = "Dance Of De Spirits", description = "De time has come to start thinkin' about when to make our move. Champion Uru'zin tells me his men be ready. You and Vanira done good work gatherin' information on de enemy and findin' us new allies.\n\nNow, we read de omens. We find out when to launch de attack.\n\nFind Witch Doctor Hez'tok near the circle of ritual dancers. He be startin' de ritual as soon as ya be ready.", objectives = "" }
WordHunterWoW_QuestEN[25481] = { title = "To New Thalanaar", description = "We are staging a relief effort at New Thalanaar for all of Thousand Needles. Seyala Nightwisp will lend you my hippogryph to safely get you there. Speak with Caryssia Moonhunter when you land.\n\nYou must go quickly if lives are to be saved!", objectives = "" }
WordHunterWoW_QuestEN[25486] = { title = "The Grimtotem are Coming", description = "This is going to take a while, but I'm sure we'll beat them back.\n\nYou're more good to Thousand Needles elsewhere. We have reports that the gnomes and goblins out on the flooded salt flats somehow survived on a giant barge! Rendow is on the dock. She'll get you a boat to go there.\n\nMind helping us out a little on your way to her?", objectives = "" }
WordHunterWoW_QuestEN[25487] = { title = "The Grimtotem are Coming", description = "The cowardly Grimtotem have attacked us by surprise when we were least prepared!\n\nYou will be of most help to Thousand Needles elsewhere, {class}. We have heard rumors that the goblins and gnomes somehow survived in a giant barge out on the salt flats.\n\nMotega Firemane is at the base of the summit. He can get you a canoe to take you there.\n\nDo you mind helping us fight off the Grimtotem on your way to him?", objectives = "" }
WordHunterWoW_QuestEN[25488] = { title = "Two If By Boat", description = "Are you ready to go, {class}? One of the sentinels will take you out to the Mirage Raceway.\n\nIf there's anyone left alive out there, please help them.\n\nGoddess watch over you!", objectives = "" }
WordHunterWoW_QuestEN[25489] = { title = "Two If By Boat", description = "Are you ready to go, {class}?\n\nOne of our braves will row you out to the Mirage Raceway. If anyone has survived out there, they'll desperately need your help.\n\nMay the Earth Mother smile upon you.", objectives = "" }
WordHunterWoW_QuestEN[25490] = { title = "Smashing Through Ashes", description = "{name}, these fiends from the Twilight's Hammer are attempting to scourge this whole mountain clean of all life. Even now they trail behind this inferno, leaving death and ash in their wake.\n\nArch Druid Hamuul Runetotem is behind the fires, trying to salvage the wilderness before it's blotted permanently from the map. Travel southeast, through The Inferno and down the road beyond. Find and aid the Arch Druid.\n\nOn your way there, clear the roads by killing any Charbringers that you find.", objectives = "" }
WordHunterWoW_QuestEN[25491] = { title = "Durable Seeds", description = "This land has been scourged by fire, but it may yet renew itself.\n\nSome seeds deep in the soil may have withstood the scorching heat here in The Flamewake. These durable plants are the key to this forest's regrowth. Please, collect some of these seedlings for me.", objectives = "" }
WordHunterWoW_QuestEN[25492] = { title = "Firebreak", description = "In their efforts to decimate Hyjal, Twilight's Hammer has elementals scouring the earth in the wake of the fire.\n\nThey're pulverizing the soil, rooting around in the ash, digging up any scrap of plantlife that survived and destroying it. It's like they're paving the way for... I don't even want to imagine.\n\nStop them before Hyjal is devoid of life. Kill the lava surgers!", objectives = "" }
WordHunterWoW_QuestEN[25493] = { title = "Fresh Bait", description = "I was stunned to discover that Twilight's Hammer had located - and imprisoned - the great turtle ancient Tortolla. As we speak he is chained above the murky waters of the Ashen Lake.\n\nFreeing Tortolla from his bonds will not be easy. But we will take it one step at a time.\n\nHead into the Flamewake and collect for me heaps of core hound entrails. I will explain why later.\n\nAnd beware of Nemesis the Usurper while you are there! His time will come, but we are not yet prepared.", objectives = "" }
WordHunterWoW_QuestEN[25494] = { title = "A Champion's Collar", description = "This little guy is a true menace now, isn't he?\n\nWe're going to have to give him a nice spiked collar if he's going to be a fighting pup.\n\nThe basilisk matriarch has made her lair off of the road to Winterspring.  Bring me her spiked hide and we'll fashion a collar for our little killer here.", objectives = "" }
WordHunterWoW_QuestEN[25495] = { title = "Preparin' For Battle", description = "Vol'jin be gatherin' his gear and readyin' de warriors. He ask me to tell ya to meet with him an' Vanira on de island to de east.\n\nFrom dere, he and de warriors will launch de attack on Zalazane. May de ancestors go wit' you, {name}. Without ya, dis campaign would only be a shadow of what it become. Speak to Handler Marnlek, just to de south, an' he give you a bat to fly out to de stagin' area.", objectives = "" }
WordHunterWoW_QuestEN[25496] = { title = "Grudge Match", description = "I don't know if you've picked up on this, but there's a bit of a rivalry between the ogre members of the Twilight's Hammer and the rest of us.\n\nFor me... it's personal.\n\nThis one ogre called Gromm'ko has a pet raptor named \"Butcher.\"  He's taken out the last three of my corehound pups.\n\nI think this last one will fare differently.  He's got a real killer's instinct.\n\nGo to the Seat of the Chosen and challenge Gromm'ko to a match between our two beasts.  Humiliate him for me, {name}damus.", objectives = "" }
WordHunterWoW_QuestEN[25497] = { title = "Back in the Saddle", description = "Our situation is growing a bit desperate, {race}.\n\nWe must focus our attention on the naga and their prisoners, but it would be folly to do so without being prepared, and down here that means finding a way to travel more quickly.\n\nThese sharks are clearly fond of sea turtle. Let's see if we can turn that into our advantage.", objectives = "" }
WordHunterWoW_QuestEN[25498] = { title = "Shark Bait", description = "<Erunak speaks as he places the turtle meat into a porous sack.>\n\nReady yourself, {name}. There's no telling how this might end up, but we don't have much choice if we are to rescue your friends.\n\nTake this sack and use it at the sunken anchor southeast of here. Once you've attracted a shark, do your best to ride it back to me here.\n\nIf you can do that, you will have a most intimidating means of transportation.", objectives = "" }
WordHunterWoW_QuestEN[25499] = { title = "Agility Training: Run Like Hell!", description = "Before we go any further, we're going to have to get you into shape.\n\nDevotion to the Old Gods is not going to save you when some emerald dragon comes chasing after you.  You need to be fleet of foot, if you catch my drift.\n\nEnough said.  We'll summon your trainer... your job is to run away from him without leaving this camp.\n\nGo!", objectives = "" }
WordHunterWoW_QuestEN[25500] = { title = "Words for Delivery", description = "Here we go.  This is the speech, {name}!\n\nIt has everything to be a great battle starter: It's inspirational, has eloquent language and speaks directly to gnomes.  Never has a finer speech been written!\n\nTurn this in to Captain Tread Sparknozzle and see if there's anything else he needs of you.", objectives = "" }
WordHunterWoW_QuestEN[25502] = { title = "Prepping the Soil", description = "The Arch Druid has tasked me with setting up a series of flamewards around the perimeter of the area. Once these are active, we can prevent further attacks from the fire elementals that left this valley in ruins.\n\nThese will also protect and nourish the soil for whatever Hamuul has planned.\n\nIt's time to begin. Find one of the five flamewards I've marked on your map, activate it, and defend it from counterattack until its magic kicks in. It won't take more than a minute.", objectives = "" }
WordHunterWoW_QuestEN[25503] = { title = "Blackfin's Booty", description = "<A torn page precedes the latest entry, which reads:>\n\nOur self-proclaimed king will stop at nothing to acquire my family fortune. He has threatened and harassed me to no end.\n\nI can't take it anymore!\n\nI've buried the treasure and fed the map to Blackfin.\n\nThat should keep my cousin's grubby little mitts off of our precious heirlooms!", objectives = "" }
WordHunterWoW_QuestEN[25504] = { title = "Do Me a Favor?", description = "Hello there. Pleased to meet you! I'm Fizzle Brassbolts. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Jinky Twizzlefixxit in her shop, you'll be well on your way.", objectives = "" }
WordHunterWoW_QuestEN[25505] = { title = "Do Me a Favor?", description = "Hey there, {name}. I'm Pozzik, world-renowned rocket car pilot. Welcome to my Speedbarge.\n\nI share your concerns about helping all of Thousand Needles. It's my firm belief that the Speedbarge is the best hope for the entire region.\n\nPerhaps you could help us out a little bit here? I'll make sure that you're equipped with what you need to tackle everything else.\n\nAs to that, if you could just run this list of parts over to Razzeric in his shop, you'll be well on your way.", objectives = "" }
WordHunterWoW_QuestEN[25506] = { title = "Sea-Food Chain", description = "Our time here draws to a close.\n\nI must find my way across the chasm and discover the purpose behind the naga activities here.\n\nIf you are to follow me, you would be wise to conclude your search for a suitable mount first.\n\nSearch the area north of here and find a puffer hatchling. Once you've caught one, bring it to the trench to the west. I will prepare everything you need there.", objectives = "" }
WordHunterWoW_QuestEN[25507] = { title = "Hell's Shells", description = "Fresh and stinking, these innards will prove to be irresistible for Nemesis, the befouled turtle god created by Twilight's Hammer.\n\nNemesis must eventually be destroyed, but first, we must collect a piece of his fiery armored shell. With it, we'll be able to work some magic to free the true ancient.\n\nGo into the Flamewake and drop this bait near Nemesis. It will distract him. Pry off a piece of his shell... then run, if you hope to survive the encounter.", objectives = "" }
WordHunterWoW_QuestEN[25509] = { title = "Physical Training: Forced Labor", description = "Training to join our ranks is not pleasant.  Why should it be?\n\nThe path to serve the Old Gods is long, painful, and soul-harrowing.  Consider this your first step.\n\nTake this pick and break the lodestone deposits found in the gorge.\n\nNo, we don't need any of the ore.  This is purely for your benefit.", objectives = "" }
WordHunterWoW_QuestEN[25510] = { title = "Tortolla Speaks", description = "<The Arch Druid fills the shell fragment with water, which boils instantly. He adds a bundle of herbs and closes his eyes in a silent prayer.>\n\n{name}, Tortolla the turtle ancient is ageless, a part of this world since the time of the titans. He speaks a language older than our understanding.\n\nDrink this and find a place of calm within yourself. You will be able to understand the language of Tortolla. Go to him now, in the Ashen Lake. Earn the ancient's trust. The fate of Hyjal hinges on this. ", objectives = "" }
WordHunterWoW_QuestEN[25513] = { title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Kelsey Steelspark, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", objectives = "" }
WordHunterWoW_QuestEN[25514] = { title = "Breaking the Bonds", description = "From the deep...\nA realm of darkness and fire.\nGrasping in my slumber.\n\nI am ensnared, {race}.\n\nShadows lurk in the rods of fire beside me.\nSlay them.\nThat I may be free again.", objectives = "" }
WordHunterWoW_QuestEN[25515] = { title = "Down in the Deeps", description = "<Jinky rolls up her sleeves and slicks back her hair while eyeing you up and down.>\n\nFine, if Fizzle wants you to have your own boat, the first thing we'll need is parts. Guess who gets to go get them?\n\n<Jinky smiles as she points downward and then grabs you a spare diving helm and flippers.>\n\nThat's right, brother. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", objectives = "" }
WordHunterWoW_QuestEN[25516] = { title = "Down in the Deeps", description = "Well, friend, if Pozzik wants you to have your own boat, the first thing we're going to need is parts. Now guess who gets to go get them?\n\n<Razzeric smiles as he points downward and then grabs you a spare diving helm and flippers.>\n\nI'm afraid so, {name}. You get to go down into the deeps and salvage what rocket car parts you can find at the Raceway Ruins.", objectives = "" }
WordHunterWoW_QuestEN[25517] = { title = "Bar Fight!", description = "Those no-good, smelly, green in the gills goblins have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their insolence, {name}!", objectives = "" }
WordHunterWoW_QuestEN[25518] = { title = "Bar Fight!", description = "Those pint-sized, goober-looking, no-explosion gnomes have got it coming!\n\nI want you to go into the Speedbarge Bar, order a bottle of grog, and hit one over the head with it!\n\nShow them that we're not going to take any more of their arrogance, {name}!", objectives = "" }
WordHunterWoW_QuestEN[25519] = { title = "Children of Tortolla", description = "My children.\nThey lie below.\nIn silt and sand.\n\nThe others corrupt them.\nDarken them within their shells.\n\nSlay the others.\nDestroy the corruptors.\nSave them...", objectives = "" }
WordHunterWoW_QuestEN[25520] = { title = "An Ancient Awakens", description = "I slumbered in the healing silt of Hyjal.\nI slept until the world broke open.\nWhen the others came, I was not ready.\n\nI am ready now, {race}.\n\nMy children and I. Slow to anger.\nBut our wrath is final.\n\nTell those who sent you that we are prepared for war.\n\nThe others will be cast from the mountain.", objectives = "" }
WordHunterWoW_QuestEN[25521] = { title = "I'm With Scorpid", description = "You gotta help me, you just gotta! Chelsea and I came out here to make a bit of money, just sell some supplies, legit work. Next thing I know she's on her deathbed! She's got a fever that'd shock a blacksmith, and she's hallucinating...\n\nShe must've been stung by the scorpids near here! I've seen it happen, it's not pretty. I gotta get some poison glands to make an antidote but I can't leave her side!\n\nPlease, help me! Get me those glands!", objectives = "" }
WordHunterWoW_QuestEN[25522] = { title = "Gargantapid", description = "No! It didn't work! I don't know what to do, unless...\n\nOh gosh, it's worse than I thought! She must've been stung by the one lurking in the cave. I saw it the first night we arrived. Claws the size of a goblin. A tail as tall as a tree! We shared hushed whispers of it around the campfire... we called it... GARGANTAPID!\n\n ...hey, are you laughing? Stop that! This is serious! Chelsea's life is on the line! Please, I'll make it worth your while...just bring me Gargantapid's poison gland!", objectives = "" }
WordHunterWoW_QuestEN[25523] = { title = "Flight in the Firelands", description = "{name}, our enemy is using this grotto in the Firelands to prepare an invasion. We're going to hit them hard right where they live.\n\nBut first, you'll need to get your wings. Flight in the Firelands does not work as it does in the outside world. Something about the dense, superheated air. You'll need some practice!\n\nGet a Twilight Firelance from the rack behind me, equip it, then mount one of Aviana's Guardians. Practice flying - flap your wings! Visit a flag placed on the ledge below and return. ", objectives = "" }
WordHunterWoW_QuestEN[25524] = { title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those Southsea treasure hunters has got to have a crowbar!", objectives = "" }
WordHunterWoW_QuestEN[25525] = { title = "Wave One", description = "Here they come, {name}! The Twilight Knight Riders, astride black buzzards birthed in the scorching sulfurous breeding pools of the Firelands. The only way to defeat them is from the sky!\n\nTake wing once more, {class}, and slay them.\n\nRun into enemy riders with your lance to destroy them.\n\nGo forth. Fly, fool. Fly!", objectives = "" }
WordHunterWoW_QuestEN[25526] = { title = "In the Outhouse", description = "Hello? Hello! HELP!\n\nI'm almost out of air! You have to get me out of here!\n\n<The voice inside gags.>\n\nOne of those filthy Southsea treasure hunters has got to have a crowbar!", objectives = "" }
WordHunterWoW_QuestEN[25531] = { title = "Twilight Riot", description = "I thank you for freeing me.  Let us take advantage of the distraction you've created and get out of here.\n\nWe must hurry before the cultists catch on.\n\nMeet me again when we've left this place.", objectives = "" }
WordHunterWoW_QuestEN[25532] = { title = "Pirate Accuracy Increasing", description = "I don't know if you've noticed, but the cannonballs are hitting us. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Go talk to Mazzer Stripscrew.\n\nPut those fires out!", objectives = "" }
WordHunterWoW_QuestEN[25533] = { title = "Pirate Accuracy Increasing", description = "Oh no, {name}, the cannonballs are hitting the Speedbarge. I'd say the Southsea pirates are getting more accurate... the ship is on fire!\n\nYou've got a river boat now. Please, go speak with Griznak.\n\nExtinguish those fires!", objectives = "" }
WordHunterWoW_QuestEN[25534] = { title = "Going Off-Task", description = "As you may have seen, the ship docked to the north has its cannons blazing. While it's pretty fun watching the gnomes run face-first into a hail of iron, my bruisers keep doing it too, and it's absolutely killing my overhead expenses.\n\nI'd like you to try and dance through the cannonfire, get on that ship, and kill the taskmaster leading the cannoneers. The rest of the crew is probably a bunch of spineless prats; once he's down, we should be good.", objectives = "" }
WordHunterWoW_QuestEN[25535] = { title = "A Powerful Need To Eat", description = "Poor things. They're starving.\n\nWe've many matters to attend to, not the least of them the naga, but first we need to get some food in these bellies. I'm not sure what the naga fed them up in that shell, if anything, but they're definitely worse for the wear.\n\nQuite a few of the survivors have made their way into Glimmerdeep Gorge, to the northwest. Go join them and help out. With a bit of clam meat, we can get these survivors back on their feet.", objectives = "" }
WordHunterWoW_QuestEN[25536] = { title = "Cold Welcome", description = "Many of the survivors made their way down into Glimmerdeep Gorge to help with the clam diving. We've been receiving reports back of deliberate attacks from some kind of murlocs down there.\n\nThe Admiral has to stay here as more men report in from the shell, so I'm having trouble convincing him to get any significant muscle to help the divers. If you'd be up for it, I'm certain they could use your help.\n\nCome back and let me know if you get the situation under control.", objectives = "" }
WordHunterWoW_QuestEN[25537] = { title = "Art of Attraction", description = "I have an idea. A brilliant idea! Those clown-looking fish have developed a symbiotic defensive relationship with the anemones. Having dismissed anemone disguise plausibilities, I've uncovered the chemical attractor that lures the fish.\n\nI have a gyrocoptic thermascrub extractor that I've brought down to take samples. Use it to extract the chemical attractor from several of the anemones, then bring the samples back to me for rapid synthesis and deployment.\n\nGo with haste! Brilliance is waiting!", objectives = "" }
WordHunterWoW_QuestEN[25538] = { title = "Odor Coater", description = "Marvelous creation if I do say so myself. Ready for deployment.\n\nSimply spray the clam divers with a bit of the chemical and they shall soon be accompanied by a protective aquatic companion. You can even spray yourself to similar effect if you so desire.\n\nSpeaking of desire, I would highly recommend that you moderate deployment of the chemical attractor to minimal applications. Large doses could result in undesirable effects...\n\nUndesirable for you anyway. Likely very desirable for the fish.\n\nAway!", objectives = "" }
WordHunterWoW_QuestEN[25539] = { title = "Clamming Up", description = "Here to help with the clam diving?\n\nGet to it then. There are clams about everywhere just waiting to be dived.", objectives = "" }
WordHunterWoW_QuestEN[25540] = { title = "Bellies Await", description = "We have quite a stock of gathered clams to tote back to the cave, I was simply awaiting someone to do the toting. You've proven dangerous enough to be the sort.\n\nI highly expect that such a fine meal shall not pass uncontested by predators on the way back, so I'd make your trip as swift as possible.\n\nThank you for your help, friend. It's been a pleasure.", objectives = "" }
WordHunterWoW_QuestEN[25541] = { title = "Filling Our Pockets", description = "We've looted everything that isn't bolted down around here, but I'm not done yet. If we're bothering to do the Steamwheedle Cartel's dirty work for them, we're going to make as much cash as we can while we're here.\n\nI haven't seen many earrings on these pirates, so the gold must be in the next best place...their teeth. The Southsea musketeers and strongarms to the south are the higher-ups here; they'll be the ones with the adornment. Bring me back a good fistful of gold fillings.", objectives = "" }
WordHunterWoW_QuestEN[25542] = { title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[25543] = { title = "Circle the Wagons... er, Boats", description = "The fires are dealt with, but there are still Southsea pirates getting ready to board the Speedbarge.\n\nTime to switch to the other side cannon and sink them before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[25544] = { title = "Wave Two", description = "You've stirred up the hornets, {name}. The ceiling is coming down on us! And their strongest fighters are taking wing on creatures warped and twisted by this world of flame.\n\nGet back out there and take them down! Watch out for flaming boulders.", objectives = "" }
WordHunterWoW_QuestEN[25545] = { title = "To Arms!", description = "As we struggled not to drown, my men and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I'm inclined to believe him.\n\nIf we're going to stand a chance, we'll need your help to recover our lost armaments. They should be lying on the sea floor near our shipwrecks.\n\nHurry, {race}, we're defenseless here.", objectives = "" }
WordHunterWoW_QuestEN[25546] = { title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these men ready for battle.\n\nAny decent leader knows that his men travel and fight on their stomachs. No food, no victory.\n\nThese soldiers are weak from their recent ordeal. They'll need sustenance if they're to put up any kind of fight when the need arises.\n\nSpeaking of traveling on stomachs, I've seen several crabs out there on the sea floor....", objectives = "" }
WordHunterWoW_QuestEN[25547] = { title = "On Our Own Terms", description = "We're as ready as we'll ever be. No sense waiting around for the naga to find us.\n\nI'll address the men, then we'll meet the enemy on our own terms and let fate decide the outcome.", objectives = "" }
WordHunterWoW_QuestEN[25548] = { title = "Might of the Firelord", description = "I've been charged with leading our military operations against the enemy.  A humbling task when you consider there are demigods walking among us.\n\nI'm going to have you carry out a series of hit-and-run attacks behind enemy lines.  It will be important that you keep the enemy off guard and weaken their numbers ahead of our main force's attack.\n\nYour first target will be the Ascendant's Rise, where the most highly trained Twilight's Hammer devotees have achieved a partial elemental state.", objectives = "" }
WordHunterWoW_QuestEN[25549] = { title = "The Sanctum of the Prophets", description = "The mad prophets of the Twilight's Hammer congregate in the area just north of the Ascendant's Rise.\n\nIt is said that their dark visions are granted to them directly by the Old Gods.  Whether or not that is true, they provide tremendous spiritual guidance to the cult.  Attacking the Sanctum of the Prophets will deal a devastating blow to the enemy's morale and if we're lucky you might run into one of the Firelord's own emissaries while you're there.", objectives = "" }
WordHunterWoW_QuestEN[25550] = { title = "Magma Monarch", description = "The magma giants who serve Ragnaros are kept in line by their king's heavy-handed rule.  Were we to take care of him, the rest will surely fall into disarray.\n\nWithout the giants, the fight on the ground will get a lot more even.  Perhaps even tilt to our favor.\n\nBut felling the magma monarch will be no easy task.  Use these drums to enlist the help of the great Tortolla who is capable of holding off King Moltron for an eternity.  But holding him off won't be enough -- and that's where you come in.", objectives = "" }
WordHunterWoW_QuestEN[25551] = { title = "The Firelord", description = "With his gatekeeper gone, you've given the Guardians of Hyjal access to Sulfuron Spire.\n\nRagnaros will have no choice but to defend the main entryway to the Firelands himself.\n\nGo through the Twilight's Hammer portal at the Sanctum of the Prophets and meet me inside.  Malfurion and Hamuul will also aid us while the others continue to fight the enemy outside.", objectives = "" }
WordHunterWoW_QuestEN[25552] = { title = "Brood of Evil", description = "This egg you recovered is an alarming sign, {name}.  The Twilight dragons are usually raised from stolen eggs from other dragonflights, which are then modified through dark magic.\n\nThis \"natural\" egg is evidence that one of their matriarchs has become a viable broodmother.  We must destroy her before her brood spreads.\n\nGo to the Ascendant's Rise where they claim these aberrations are kept and slay one of the juvenile drakes.  We will use its skull to lure out its mother.", objectives = "" }
WordHunterWoW_QuestEN[25553] = { title = "Death to the Broodmother", description = "We've located the matriarch's feeding grounds south of the Ascendant's Rise.\n\nShe will be extremely angry to have lost one of her drakes.  Place the skull there near the carcasses she devours.  If she's anywhere in the vicinity, she will come out and attempt to exact revenge.\n\nWe will have a surprise waiting for her.", objectives = "" }
WordHunterWoW_QuestEN[25554] = { title = "Secrets of the Flame", description = "If we are to banish Ragnaros back into the Firelands, we will need to gain access to Sulfuron Spire.\n\nOnly the most trusted members of the Twilight's Hammer will have been entrusted with such valuable information.\n\nGo search the Ascendant's Rise for any written tomes you might find.  Foul as they are, we cannot waste the opportunity to learn about our enemy's weaknesses.", objectives = "" }
WordHunterWoW_QuestEN[25555] = { title = "The Gatekeeper", description = "According to these tomes, one of Ragnaros' most powerful lieutenants serves as the sole gatekeeper to Sulfuron Spire.\n\nYou won't be able to defeat him alone.\n\nSound this horn when you engage in combat with Azralon and any of our forces in the vicinity will come to your aid.\n\nYou must hurry, {name}.  It won't be long before the Firelord realizes what we're up to.", objectives = "" }
WordHunterWoW_QuestEN[25556] = { title = "Into Zul'Farrak", description = "That foul traitor...I should've known better than to trust his kind. My hunt for Sul'thraze has blinded me.\n\nForgive me, {name}. Mazoga has fled inside of Zul'Farrak, the heart of the Sandfury civilization.\n\nIf you truly seek the sword, you must pursue him. Do not go alone; the entirety of the Sandfury tribe lies in wait behind those walls, and they will not welcome you.\n\nI will stay here. My search for the blade must end. Should you find it, keep it; I must give up before I am consumed.", objectives = "" }
WordHunterWoW_QuestEN[25558] = { title = "All or Nothing", description = "This is it.\n\nThis is where we make our stand.\n\nWe must defend this ship to our last breath, and make these cretins think twice before approaching it again!\n\nMay our blades strike fear in their hearts!", objectives = "" }
WordHunterWoW_QuestEN[25559] = { title = "Laying Claim", description = "We're not the only ones interested in these ruins, it seem. Of all things, we've got blood elves after our dig sites.\n\nI'd expect them to wilt in the heat without all their fancy fountains and cushy pillows, but they're surprisingly scrappy, and they're trying to drive us out of the Southmoon Ruins by force.\n\nIt's time to crack a few heads. Head over there and teach those elves not to mess with us!", objectives = "" }
WordHunterWoW_QuestEN[25560] = { title = "Egg Wave", description = "Without any defenders, the Firelands eggs are vulnerable.\n\nTake wing once more and smash those eggs! Simply rush over them to crush them. Search all the nooks, crannies, and side-caves. Hurry! ", objectives = "" }
WordHunterWoW_QuestEN[25561] = { title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Mazzer Stripscrew and get on your boat. Use the cannon to sink them before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[25562] = { title = "Circle the Wagons... er, Boats", description = "The fires may be dealt with, but those Southsea pirates are still getting ready to board the Speedbarge!\n\n{name}, you need to go back to Griznak and get on your boat. Use the cannon to sink them before it's too late!", objectives = "" }
WordHunterWoW_QuestEN[25564] = { title = "Stormwind Elite Aquatic and Land Forces", description = "You've done us a great service, {class}, so I'm going to let you in on a little secret. The men you've saved today aren't your everyday Stormwind troops.\n\nWe belong to a special detachment of elite soldiers sent here not only to contend with the Horde, but to investigate the massive geological disturbances originating from the nearby sea floor.\n\nI tell you this because our top secret equipment lies in the bottom of some of our wrecked ships here.\n\nThat gear must be retrieved!", objectives = "" }
WordHunterWoW_QuestEN[25565] = { title = "Fragments of Language", description = "We've had our first big find in years here at the Southmoon ruins. My lads have dug up stone tablets, engraved with ancient writings.\n\nThe glyphs on the tablets are like nothing we've ever seen, but I have a hunch we can connect them with titanic scripts found at other digsites. Imagine what a breakthrough like that could mean!\n\n I need you to go to the Southmoon ruins and help us collect the tablets; the other lads can't leave, lest the blood elves take our site!", objectives = "" }
WordHunterWoW_QuestEN[25566] = { title = "The Secrets of Uldum", description = "I studied these ruins for years trying to find a way in. We even took a good chunk out of the gate, only to find impenetrable walls beneath. Now the cataclysm may've wrecked everything in there something fierce, but it's done what we couldn't and opened a way in!\n\nI'd like you to have the honor, lad. Head on in there and see if anything's been left uncracked. Be careful though... there's no telling what, or who, might be stirring in there.", objectives = "" }
WordHunterWoW_QuestEN[25571] = { title = "A Natural Occurrence", description = "This Elemental Shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary in any capital city.  This could be exactly what they are looking for.", objectives = "" }
WordHunterWoW_QuestEN[25574] = { title = "Flames from Above", description = "We've identified the general direction where the infiltrators have been coming from, thanks to your work.\n\nNow we just need to shut down their camp and put an end to their operations this side of Nordrassil.\n\nTake this horn.  It will signal one of our emerald drakes to swoop down and give these Twilight cultists a taste of the flames they so madly worship.", objectives = "" }
WordHunterWoW_QuestEN[25575] = { title = "Forged of Shadow and Flame", description = "The weapons the Twilight's Hammer uses against us are crafted by Forgemaster Pyrenduis within these very halls. The metal slices through armor like cheese in the hands of its wielder. Yet, when captured, the steel turns brittle and shatters.\n\nSo be it, {name}. I'd rather see those cursed arms smashed than delivered to our enemy.\n\nSeek out the crates of Twilight arms in these caverns and smash them to pieces.", objectives = "" }
WordHunterWoW_QuestEN[25576] = { title = "Rage of the Wolf Ancient", description = "Here we are deep within the realm of the fire god and what do we find? The little puppets of Ragnaros, scurrying around to do his bidding.\n\nThese Dark Iron laborers are finishing and packaging the weapons Twilight's Hammer hopes to use in their conquest of Hyjal. I don't care if they're here of their own free will or if they've been brainwashed or kidnapped... They're a foe of our beloved wolf ancient and they should pay the ultimate price.", objectives = "" }
WordHunterWoW_QuestEN[25577] = { title = "Crushing the Cores", description = "These searing guardians are murderous! We destroy them, and within minutes, they reignite from the ashes.\n\nI think there's a way to destroy them permanently, but we'll need someone who can fight through the front ranks.\n\n{name}, kill the searing guardians and take their smoldering cores to the nearby anvils. Smash them on the Twilight Anvils, and destroy them for good!", objectives = "" }
WordHunterWoW_QuestEN[25578] = { title = "Return to Nordrassil", description = "I will take Fandral to Moonglade swiftly.  I hope to return soon so I may continue to aid in the battle.\n\nIn the meantime, report back to Ysera and inform her of these recent developments.", objectives = "" }
WordHunterWoW_QuestEN[25579] = { title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", objectives = "" }
WordHunterWoW_QuestEN[25580] = { title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", objectives = "" }
WordHunterWoW_QuestEN[25581] = { title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nAll I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance. The statues interest me especially.", objectives = "" }
WordHunterWoW_QuestEN[25582] = { title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", objectives = "" }
WordHunterWoW_QuestEN[25583] = { title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", objectives = "" }
WordHunterWoW_QuestEN[25584] = { title = "The Return of the Ancients", description = "It'll be crucial to reclaim each of the ancients' shrines, {name}.\n\nFollow the road west of the Verdant Thicket, into Wolf's Run.\n\nWe have operatives stationed there.  Aid them in any way that you can and work your way to the first shrine.\n\nThe wolf god was known to the elves as Goldrinn and to the orcs as Lo'Gosh.  He will be a fierce ally in our fight against the enemy.", objectives = "" }
WordHunterWoW_QuestEN[25585] = { title = "Quiet the Cannons", description = "Now it's time to do something about those darn cannons up on the bluffs to the east!\n\nIf you'd be so kind, hop into your boat and cruise on over to the Southsea Holdfast. Up top you'll see a bunch of cannons firing down on us.\n\nThose pirates don't know squat about engineering. It shouldn't be too difficult for you to clog 'em up and make them explode.", objectives = "" }
WordHunterWoW_QuestEN[25586] = { title = "Quiet the Cannons", description = "Now it's time to do something about those darn cannons up on the bluffs to the east!\n\nIf you'd be so kind, hop into your boat and cruise on over to the Southsea Holdfast. Up top you'll see a bunch of cannons firing down on us.\n\nThose pirates don't know squat about engineering. It shouldn't be too difficult for you to clog 'em up and make them explode.", objectives = "" }
WordHunterWoW_QuestEN[25587] = { title = "Gimme Shelter!", description = "Please, {race}! You must help me!\n\nI've barely managed to survive, what with naga, sharks, and that horrible monster that attacked our ship.\n\nI can see a cave that might be safe, but I don't dare try to make it unless I know there's air inside.\n\nCan you make sure it's ok?", objectives = "" }
WordHunterWoW_QuestEN[25588] = { title = "A Little Payback", description = "It's time for a little payback, I think. Can you blame me? After they locked me down in that outhouse and left me to drown?!\n\nI'll make it worth your while if you head up to the Southsea Holdfast on the eastern bluffs and exact my revenge.", objectives = "" }
WordHunterWoW_QuestEN[25589] = { title = "A Little Payback", description = "It's time for a little payback, I think. Can you blame me? After they locked me down in that outhouse and left me to drown?!\n\nI'll make it worth your while if you head up to the Southsea Holdfast on the eastern bluffs and exact my revenge.", objectives = "" }
WordHunterWoW_QuestEN[25590] = { title = "Where's Wizzle?", description = "Hey, {name}, you haven't seen my other brother, Wizzle, have you?\n\nI just know that the pirates captured him! He said that he was going to try to sell them some engineering stuff, or something.\n\nWould you please look for him up at the Southsea Holdfast to the east? I'll bet that no-good goblin he's always traveling with, Synge, got him into trouble!", objectives = "" }
WordHunterWoW_QuestEN[25591] = { title = "Thunderdrome: Grudge Match!", description = "It seems we have a special request! I have here a note from one Megs Dreadshredder, requesting to enter the cage and settle a dispute.\n\nShe's asked for you to be her partner, {name}. A fan of your previous victories? Or perhaps you're acquainted outside the ring?\n\nI wouldn't back down now if I were you. This is the grand finale...", objectives = "" }
WordHunterWoW_QuestEN[25592] = { title = "Deep Attraction", description = "I've been able to help some of the survivors make it to the cave, but it's starting to get hairy out there. If we didn't have enough problems, some glowing murlocs started creeping up from the nearby crevice to attack the stranded survivors.\n\nThe men up there are warriors--they won't go down without a fight--but they're much worse for the wear after that damned shell.\n\nIf you have any breath left in your lungs, get up there and take out some of those murlocs. Hellscream's eyes are upon you.", objectives = "" }
WordHunterWoW_QuestEN[25593] = { title = "Shelled Salvation", description = "A lot of the men haven't made it to the cave yet. It's a safe bet that they're stranded at the vents on the ridge above us.\n\nWe found some spiralung shells on the way here. They don't produce much air, but it was enough for us to make the cave.\n\nI need to stay here to count heads and get them back on their feet as they arrive. Do me a favor - go collect those spiralung shells, get them to any of my men that are still up on the ridge, and give them a swift kick in the arse so that they get moving.", objectives = "" }
WordHunterWoW_QuestEN[25594] = { title = "Crafty Crabs", description = "It was that darn crab!\n\nHere I thought that all the exercise from walking here was making me super buff! My pack just kept getting lighter and lighter. But no! That crab snipped a hole in my bag and all my parts were falling out the whole way here.\n\nPlease, help a good lookin' goblin out, will ya? Go back and help me pick up all of my stray parts. I'm sure those conniving vicious little crabs ran off with some of them too.", objectives = "" }
WordHunterWoW_QuestEN[25595] = { title = "Something Edible", description = "Were they trying to starve us all to death?! Not giving prisoners food is just despicable.\n\nWe need to get these soldiers fed. The best prospect I spotted on the way here were those giant grouper. Several of those and we shouldn't want for meat for a while.\n\nIf you can bring me back some, I'll see to it that it gets cooked and passed out fairly.", objectives = "" }
WordHunterWoW_QuestEN[25596] = { title = "Where's Synge?", description = "Hey, {name}, you haven't seen our gunsmith, Synge, have you?\n\nI just know that the pirates captured him! He said that he was going to try to sell them some rifles, or something.\n\nWould you please look for him up at the Southsea Holdfast to the east? I'll bet that no-good gnome he's always traveling with, Wizzle Brassbolts, got him into trouble!", objectives = "" }
WordHunterWoW_QuestEN[25597] = { title = "Commander Jarod Shadowsong", description = "Only once has there been a leader capable of commanding demigods and mortals alike.\n\nHis name was Jarod Shadowsong and his ability to lead in battle was such that Cenarius and the other ancients placed themselves under his command.\n\nHe disappeared for years and his whereabouts were unknown.  Until now.\n\nHe is being held captive inside a Twilight camp in Darkwhisper Gorge.\n\nYour job is to infiltrate their ranks and free Jarod.  Speak to the one known as Ortell at Darkwhisper Pass to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[25598] = { title = "Ain't Too Proud to Beg", description = "Now that you've brought me to safety, I'm afraid I must impose upon your kindness just a bit further.\n\nThe captain of our ship, Samir, is still out there. Mack too. I'm sure they made it to the sea floor but beyond that I didn't see what became of them.\n\nI simply couldn't get by in a place like this without their help.\n\nI lost sight of them in a clump of kelp west of where you found me.\n\nPlease hurry! They couldn't have gotten far...", objectives = "" }
WordHunterWoW_QuestEN[25599] = { title = "Cindermaul, the Portal Master", description = "Twilight's Hammer is using these corridors, and others like them, to move supplies from the elemental planes up into Azeroth. In order to seal these passages off, we're going to need to know how they're constructed.\n\nFind for me the Tome of Openings, used by the elementals to open gates between the planes.\n\nCindermaul the Portal Master should have one. You'll have to kill him. Careful! He's probably got some tricks up his sleeve...", objectives = "" }
WordHunterWoW_QuestEN[25600] = { title = "Forgemaster Pyrendius", description = "A terrible evil squats in the heart of this cavern, {name}. Forgemaster Pyrendius has personally crafted many of the cursed weapons that Twilight's Hammer is using in their conquest of the realms above.\n\nBefore we leave these lands of flame... Pyrendius must die.\n\nHe will not go down easy. But, if I'm reading the tome correctly, we can briefly open up small gateways to the Abyssal Maw, the realm of water. Lure Pyrendius onto a portal rune and activate it to weaken him!", objectives = "" }
WordHunterWoW_QuestEN[25601] = { title = "Head of the Class", description = "That settles it, \"{name}damus!\"  You are head of your class!\n\nYou will get a chance to address a crowd of the most fanatical, bloodthirsty and certifiably insane people on this planet.\n\nGo report to your instructor for the details, but remember: your goal is to exploit the animosity between the ogres at the Seat of the Chosen and the other, less privileged races.\n\nIf all goes well, we will smuggle Jarod out of here during the ensuing riot.", objectives = "" }
WordHunterWoW_QuestEN[25602] = { title = "Can't Start a Fire Without a Spark", description = "Mack's still out of it, and I fear we may lose him if I can't get this fire started. With the wood being soaked, we'll need something special to get it going.\n\nThere's an abandoned camp nearby with a barrel of explosives in it. There's no way I can recover it on my own.\n\nWould you mind hauling it back for us? For Mack?", objectives = "" }
WordHunterWoW_QuestEN[25607] = { title = "Ze Gnomecorder", description = "Zese goblinz dizgust me. Zer filzy goblin technology iz inferior to anyzing gnomish, yet...\n\n<Professor Xakxak sighs.>\n\nIt iz ze last piece of ze puzzle! Wizout ze filzy goblin technology ze gnomecorder cannot be built!\n\nVenture eazt into ze \"Skunkworks\" and take from zem zer filzy goblin junk! You vill most likely find zem on goblin technicians.\n\n<Professor Xakxak laughs mockingly.>\n\nGoblin technician? Vut iz zat anyvay?\n\n<Professor Xakxak shrugs.>\n\nZome kind of oxymoron?", objectives = "" }
WordHunterWoW_QuestEN[25608] = { title = "Slash and Burn", description = "Victory is possible, {name}.\n\nThis portal is not just a means of bringing back Cenarius through the dream.  Think about it, {name}.  Once a gateway through the Emerald Dream is open, our forces can use them to move freely from Moonglade, Nordrassil, and even Wyrmrest, to this strategic location.\n\nAll Ysera needs is time. It'll be up to you to keep the Twilight's Hammer forces in Darkwhisper Gorge from pulling together and attacking us from the east.\n\nTake one of the emerald drakes and hit them hard, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25609] = { title = "Sunken Treasure", description = "The key to the cage is held by Tony Two-Tusk, the pirate admiral, and he's guarded by ogres that you'll never be able to kill!\n\n<Wizzle cries some more and then looks up, an idea forming in his brain.>\n\nI've got it! What do all pirates want more than anything else? No, not grog. Something even better... treasure!\n\nThey had a ship full of treasure that was sunk by a giant whale-shark. The treasure is scattered all over down in the Mirage Abyss to the northwest.\n\nGo get it!", objectives = "" }
WordHunterWoW_QuestEN[25610] = { title = "Sunken Treasure", description = "The key to the cage is held by Tony Two-Tusk, the pirate admiral, and he's guarded by ogres that you'll never be able to kill!\n\n<Wizzle cries some more and then looks up, an idea forming in his brain.>\n\nI've got it! What do all pirates want more than anything else? No, not grog. Something even better... treasure!\n\nThey had a ship full of treasure that was sunk by a giant whale-shark. The treasure is scattered all over down in the Mirage Abyss to the northwest.\n\nGo get it!", objectives = "" }
WordHunterWoW_QuestEN[25611] = { title = "Return from the Firelands", description = "I'll usher out the rest of Goldrinn's followers and seal this portal behind us.\n\nThe rest of our forces at Mount Hyjal will want to hear of this victory. Return to Ian Duran and let him know what we've discovered and how we were triumphant!\n\nSimply step through the portal to return to Mount Hyjal.", objectives = "" }
WordHunterWoW_QuestEN[25612] = { title = "Return from the Firelands", description = "I'll usher out the rest of the followers of Lo'Gosh and seal this portal behind us.\n\nThe rest of our forces at Mount Hyjal will want to hear of this victory. Return to Takrik Ragehowl and let him know what we've discovered and how we were triumphant!\n\nSimply step through the portal to return to Mount Hyjal.", objectives = "" }
WordHunterWoW_QuestEN[25613] = { title = "Do Yourself a Favor", description = "So these night elves send out a desperate call for help to us, goes something like this:\n\n<Gnombus changes the pitch of his voice to sound like a woman.>\n\n\"Please come help us! The big, mean Horde has goblins! Oh, we can't handle goblins! They pull our hair and make us cry!\"\n\nRight, anyway, so here we are.\n\nThe first thing I did was upgrade their aerial defenses with some of my new sniper guns. Problem is, they don't use guns. Do yourself a favor and lend 'em a hand, eh? Find 'em south of here.", objectives = "" }
WordHunterWoW_QuestEN[25614] = { title = "The Only Way Down is in a Body Bag", description = "The skies are swarming with heavily armored orcs on the backs of even more heavily armored wind riders. Our best efforts to bring them down have thus far proven fruitless. Our arrows usually just bounce off of those foul creatures. If we do happen to take one down the orcs deploy their goblin parachutes and safely land on the ground below.\n\nI need you to use Gnombus's sniper cannons and blow up the Warsong wind riders and then blow up the parachuting orcs.\n\nThe only way down is in a body bag.", objectives = "" }
WordHunterWoW_QuestEN[25615] = { title = "Return to Stardust", description = "Huntress Jalin will be pleased to know that the way to Windshear Hold is now clear. Please return to Stardust Spire and inform her of your success. She will most assuredly have more work for you now that our path is clear.\n\nThank you and good luck, friend.", objectives = "" }
WordHunterWoW_QuestEN[25616] = { title = "Hellscream's Legacy", description = "Enter Stonetalon Mountains through Talondeep Pass and head towards the smoldering trees. Seek out the Krom'gar incinerators that are destroying the forest and slay as many as you can! Be warned, the incinerators are powerful orcs. Attacking them through conventional means will likely result in your death. Destroy the oil canisters on their backs and they will be devoured by flame!\n\nReport to Sentinel Heliana at Windshear Mine should you succeed. She will have your new orders.", objectives = "" }
WordHunterWoW_QuestEN[25617] = { title = "Into the Maw!", description = "Atop the Lightning Ledge, the Twilight's Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.\n\nI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.\n\nBe bold, {name}. Find out where that flamegate leads, and destroy whatever lies within.", objectives = "" }
WordHunterWoW_QuestEN[25618] = { title = "Into the Maw!", description = "Atop the Lightning Ledge, the Twilight's Hammer has erected an enormous flamegate. I do not know where it leads; I know it is not of this realm, and I cannot enter. None of my other followers have returned.\n\nI need you to enter this realm and be my fangs within. Step through the flamegate. If he is still alive, meet with Jordan Olafson inside. He will give you a token that will allow you to use my powers in that realm.\n\nBe bold, {name}. Find out where that flamegate leads, and destroy whatever lies within.", objectives = "" }
WordHunterWoW_QuestEN[25619] = { title = "Reoccupation", description = "There's no shortage of Kvaldir to slaughter. They're obviously still reeling from our assault.  The city has been desolate so long, I doubt they expected any naga to contest them here.\n\nThere have been no reports yet of their leader. I'm sure that culling them further will force the coward to rear his head soon enough.\n\nShall we continue?", objectives = "" }
WordHunterWoW_QuestEN[25620] = { title = "The Revered Lady", description = "The Revered Lady has sent word for you. She awaits you at the far end of the temple gardens.\n\nIf you feel the need to mention the heroic exploits of your faithful battle brother, Azjentus, please don't hold back. I won't take your admiration of me as a weakness.\n\nI'll hold you up no longer. The Lady awaits.", objectives = "" }
WordHunterWoW_QuestEN[25621] = { title = "Field Test: Gnomecorder", description = "Ze Gnomecorder iz complete! Now ve must test zit!\n\nVenture into Stonetalon Mountains to ze southeast and valk down ze Talondeep Pass until you reach a filzy goblin drill machine. I vill activate ze gnomecorder ven you reach your destination!", objectives = "" }
WordHunterWoW_QuestEN[25622] = { title = "Burn, Baby, Burn!", description = "Deze orc incinerators zat burn ze forest carry viz zem powerful veaponry! You must kill zem and take zhere flame thrower. Vonce you have ze flame thrower, search ze forest for varsong stockpilez and use ze flame thrower to burn zem down!\n\nBurn zem all and I vill reward you! Yes, ze Gnomecorder can transport items!\n\nVait! Do you hear zat! I zink zhere iz an orc nearby! Vatchout!", objectives = "" }
WordHunterWoW_QuestEN[25623] = { title = "Into the Maw!", description = "{name}, there you are! Goldrinn has a mission that only his champion can accomplish. Atop the Lightning Ledge, Twilight's Hammer has erected a flamegate. We don't know where it leads, but Goldrinn can't enter. The ancient needs you to be his fangs.\n\nStep into the flamegate and talk to Jordan Olafson when you get inside. He'll give you a token to allow you to use Goldrinn's power in that realm. Find out where the flamegate leads!", objectives = "" }
WordHunterWoW_QuestEN[25624] = { title = "Into the Maw!", description = "{name}! Lo'Gosh needs you. Atop the Lightning Ledge, Twilight's Hammer has erected a flamegate. We don't know where it leads, but nobody who's gone through has returned. You are to venture inside and be the fangs of Lo'Gosh within.\n\nStep into the flamegate and talk to Jordan Olafson when you get inside. He'll give you a token to allow you to use Lo'Gosh's power inside that realm. Find out where the flamegate leads!", objectives = "" }
WordHunterWoW_QuestEN[25626] = { title = "Visions of the Past: Rise from the Deep", description = "What you told me of the naga before has been plaguing my mind. Who are these allies they're summoning? Do they really think they can defeat the Tidehunter?\n\nEscaping this cave brings a degree of relief, but our purpose here remains. I'm hoping you will be willing to seek answers from the Battlemaiden one last time.\n\nThere's only one place that I can think of where they would have taken the artifact - the temple atop the ruins. It's sure to be well guarded. Proceed carefully.", objectives = "" }
WordHunterWoW_QuestEN[25627] = { title = "Two-Tusk Takedown", description = "This treasure's all fake, but it's not like those den whompers are going to know the difference. Stupid ogres!\n\nHere's the plan... you head into the Admiral's Den and spread all of this \"treasure\" around to any ogres that get in your way. Then all you have to do is confront Tony Two-Tusk.\n\nYou'll have the key to the cage in no-time!", objectives = "" }
WordHunterWoW_QuestEN[25628] = { title = "Two-Tusk Takedown", description = "This treasure's all fake, but it's not like those den whompers are going to know the difference. Stupid ogres!\n\nHere's the plan... you head into the Admiral's Den and spread all of this \"treasure\" around to any ogres that get in your way. Then all you have to do is confront Tony Two-Tusk.\n\nYou'll have the key to the cage in no-time!", objectives = "" }
WordHunterWoW_QuestEN[25629] = { title = "Her Lady's Hand", description = "Battlemaiden!\n\nFind my Honor Guard upon the field of battle and relieve them of their foes. I need them to return to guard the priestesses immediately!\n\nI will hold the entrance. Be swift!", objectives = "" }
WordHunterWoW_QuestEN[25630] = { title = "The Fires of Mount Hyjal", description = "Do you see it, {name}? From the ridge southwest of here... plumes of black smoke curling into the sky.\n\nMount Hyjal is burning.\n\nIf the fires have raced this far up the mountain, surely they threaten the Grove of Aessina and all of our forces there. Can you investigate?\n\nSpeak with Laina Nightsky near the Grove of Aessina. Last I heard, she was fighting off the assault.", objectives = "" }
WordHunterWoW_QuestEN[25636] = { title = "Starve a Fever, Feed a Cold", description = "Mack is fading in and out of consciousness.\n\nIf he's going to make it, he's going to need all the help we can muster.\n\nI know a good recipe for turtle soup that's sure to warm him up.\n\nBring me some turtle meat and I'll handle the rest.", objectives = "" }
WordHunterWoW_QuestEN[25637] = { title = "To the Fathom-Lord's Call", description = "Fathom-Lord Zin'jatar has sent word that the Kvaldir leader has shown himself. I would like you to make your way to him at the far end of the terrace above us, on the middle level of the ruins: Nar'shola Terrace.\n\nKill any Kvaldir that stand in your path on that terrace. We want the echoes of this defeat to ring in their minds so that they will dare not return to threaten our purpose here.\n\nYour devotion does not go unnoticed, my battlemaiden. Go knowing that you have my blessing.", objectives = "" }
WordHunterWoW_QuestEN[25638] = { title = "A Desperate Plea", description = "The note in this bottle is soaked through, but still legible.\n\nIn it, the author claims to have escaped from some sort of undersea naga prison.\n\nHe is clearly in fear for his life, and you can't help but wonder if it might be one of your recently abducted shipmates.\n\nAt a loss as to how to locate the escapee, you determine to share the find with Erunak.", objectives = "" }
WordHunterWoW_QuestEN[25639] = { title = "[DND] Test Rifts", description = "", objectives = "" }
WordHunterWoW_QuestEN[25640] = { title = "Bombs Away: Windshear Mine!", description = "Ve have discovered ze vhereabouts of ze gigantic goblin bomb zat you discovered at Silvervind Refuge.\n\nYou remember Boog? Ze gnome you rescued from ze orcish vagon of agony? Vell, he and Minx have tracked ze bomb down to Windshear Mine. Go zhere immediately, {name}! Zey'll be expecting you.", objectives = "" }
WordHunterWoW_QuestEN[25641] = { title = "The Flow of Muisek", description = "I've done all I can for you. Muisek stronger than the hippogryph just isn't within my power to work with yet, so I won't make you deal with the disaster that could bring.\n\nBut while you've been busy, I've fully readied the hippogryph muisek. Take it to my master, Witch Doctor Uzer'i in Camp Mojache. He can create powerful weapons with it, and hopefully he'll be impressed by what I've done.", objectives = "" }
WordHunterWoW_QuestEN[25642] = { title = "Don't Look Them in the Eyes", description = "Keep your head down, {name}. No need to draw unwanted attention.\n\nLooks like the orcs are piling that balloon up with some type of ore from the mine. Get in there and take the ore from the orcs. Bring me back whatever you manage to grab and I'll ship it off to the professor for examination.\n\nBefore you go, a word of advice: you can avoid the Krom'gar pretty easily in there as (1) they're dumb as dirt and (2) they can't see anything if they're carrying ore. Of course, you need to kill them to get their ore.", objectives = "" }
WordHunterWoW_QuestEN[25643] = { title = "The Darkmist Ruins", description = "I have been beset by visions, {class}. Visions of an icon of great power falling into sinister hands. I see an amulet, held by the ancient elves...sitting forgotten while its surroundings turn to ruins, until it is captured by demons through treachery and malice.\n\nEvery night, these sights flow through my dreams. The spirits are warning us. I am too old, and the camp's braves too occupied with guarding us. I must beseech you to follow my visions to the south, to the Darkmist Ruins, and seek out the amulet.", objectives = "" }
WordHunterWoW_QuestEN[25644] = { title = "The Twilight Egg", description = "The egg is unlike any that you've seen before.  Its translucent shell appears to bend the light around it.\n\nAccompanying it, you find a note describing the arrival of a fertile broodmother at the Ascendant's Rise.\n\nPerhaps you should show this to Aronus.", objectives = "" }
WordHunterWoW_QuestEN[25645] = { title = "Return to Sage Palerunner", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. This must be the amulet Sage Palerunner sent you here for...", objectives = "" }
WordHunterWoW_QuestEN[25646] = { title = "Windshear Mine Cleanup", description = "The Horde has overrun Windshear Mine. I'm not sure what these orcs are hauling out of here or why they're here, but I know that it can't be good. Get in that mine and take out the management. Without goblin overseers, these peons will be even more worthless.\n\nWhile you're inside, keep your eyes peeled for any other information about the Horde operation in the mines.\n\nGood luck!", objectives = "" }
WordHunterWoW_QuestEN[25647] = { title = "Illegible Orc Letter", description = "You've discovered a parchment with an impressive looking Horde seal imprinted upon its page. Unfortunately, the rest of the document is completely illegible as it is in orcish.\n\nTake the letter to Boog. He might know what to do with it!", objectives = "" }
WordHunterWoW_QuestEN[25648] = { title = "Beyond Durotar", description = "Hmmph... it looks like your services are being requested elsewhere.  Ag'tor Bloodfist is looking for recruits to assist the Horde's ventures in Azshara, north of Orgrimmar.\n\nI'm sure you still have work to do here in Durotar, and I understand that they'll shortly be asking for your help in the Barrens.  I wouldn't be going anywhere yet if I were you, but if you're itching for some manifest destiny... Azshara awaits.", objectives = "" }
WordHunterWoW_QuestEN[25649] = { title = "Minx'll Fix It", description = "The good news is that Minx is fluent in orcish and she's nearby. Head back into the mine and find her. She's probably deeper inside, standing around being useless.\n\nDon't forget the parchment!", objectives = "" }
WordHunterWoW_QuestEN[25650] = { title = "Orders from High Command", description = "The letter is actually an order from Horde high command. Someone named Overlord Krom'gar has issued a \"strip job\" on this mine in order to obtain something called azure iron flake. Presumably this flake is obtained from breaking down the ore.\n\nIt gets worse. They plan to mix the azure flake with the explosives sitting inside the huge bomb outside and blow up Windshear Hold.\n\nWe don't have a moment to lose, {name}! Take this translated copy of the letter and return to Boog! He'll know what to do next.", objectives = "" }
WordHunterWoW_QuestEN[25651] = { title = "Oh, the Insanity!", description = "So, I've been thinkin'...\n\nIf someone's out-of-their-mind-guano-crazy, do they know it?\n\nCase in point, I coulda swore that I'd collected a barrel of gunpowder from the cannonballs around here, but it's nowhere ta be found.\n\nI distinctly remember lifting the cannonballs from them Gilblins just west of here.\n\nMaybe they're right... maybe I really have lost it.", objectives = "" }
WordHunterWoW_QuestEN[25652] = { title = "Commandeer That Balloon!", description = "We don't have a moment to lose, {name}. You're going to have to commandeer that hot air balloon and stop it!\n\nHow? I have no idea! We don't have time to argue details! Grab onto that rope ladder and climb up! Just start banging on stuff once you're inside!\n\nIf you somehow manage to stop the balloon and survive, report to Lord Fallowmere at Windshear Hold in the west.\n\nGood luck, we're all counting on you. Now if you'll excuse me I'm going to RUN FOR MY LIFE!", objectives = "" }
WordHunterWoW_QuestEN[25653] = { title = "The Ancients are With Us", description = "Nemesis... destroyed.\n\nI feel rejuvenated.\nPowerful.\nAwakened.\n\nTell Ysera my strength is hers.\n\nThe Twilight's Hammer will fall.", objectives = "" }
WordHunterWoW_QuestEN[25654] = { title = "Dark Heart", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. It is her malicious will that leads the harpies to defend their nests among the ruins of our people.\n\nThe harpies can call to her with a horn they carry - blowing it by the Hatetalon stones, in the northern part of the ruins, will summon Edana.\n\nShow no mercy for these foul creatures. Slay her, and bring her dark heart to me.", objectives = "" }
WordHunterWoW_QuestEN[25655] = { title = "The Wormwing Problem", description = "Skylord Omnuron has been too gentle with the Wormwing harpies. He allows them to share a perch on this mountain just because they're creatures of the air. Well {class}, not all creatures of the air are created equal.\n\nWhen the attacks on Hyjal began, the Wormwing went into a frenzy. They're up there right now, assaulting a sacred shrine they once claimed to revere.\n\nI'm not troubled. Now we have a reason to drive them from Hyjal, don't we?", objectives = "" }
WordHunterWoW_QuestEN[25656] = { title = "Scrambling for Eggs", description = "There's a pattern to these Wormwing attacks. While groups make a showy assault on the shrine itself, others swoop into the nearby nests and make off with eggs from all the flying creatures of Hyjal.\n\nThese animals are under our protection. Before we find out why the Wormwing are doing this, it's up to us to rescue as many eggs as we can from their talons.", objectives = "" }
WordHunterWoW_QuestEN[25657] = { title = "Dah, Nunt... Dah, Nunt...", description = "So, seein' as ya been so kind to me, I'm inclined to let you in on a special secret.\n\nI've found the biggest shiney of all, no more than 50 steps from where we're standin'!\n\nOnly one thing stands between you, me, and great fortune - and his name is Gnaws.\n\nDon't fret now - I've got a plan.\n\nGnaws loves his grubs, so I've loaded one up with that gunpowder so as to make like a trap of sorts, ya see?\n\nJust set it floatin' up in the reef. Once the shark is dead, we're rich!", objectives = "" }
WordHunterWoW_QuestEN[25658] = { title = "Built to Last", description = "My lady, I have a request from the High Priestess that I am to pass along to you. Many of the city's defenses remain from long before it sunk beneath the waves, and some of them are but a trivial task to reactivate, were it not for the countless Kvaldir that stand in our way.\n\nWe are told you are to be fighting on Nar'shola Terrace above us. You would do my lady a great service if you would but touch some of the devices as you pass. Your noble blood should prove more than sufficient to reactivate them.", objectives = "" }
WordHunterWoW_QuestEN[25659] = { title = "Not Soon Forgotten", description = "The Kvaldir leader has shown his rotting, ugly face but a short swim from here, down this hall to our west. We kill him now and the Kvaldir occupation of our once beloved city shall be ended.\n\nBeware Battlemaiden, for he is no weakling. He has many Kvaldir at his command. Some Sira'kess Sea Witches have been dispatched to weaken him during your attack, but they will be interrupted if you let any of his Kvaldir attack them.\n\nShow no mercy, Battlemaiden.", objectives = "" }
WordHunterWoW_QuestEN[25660] = { title = "Haunted", description = "You think I'm going to just let you go after you killed me like that, mon? No way! I didn't create a piratical mercantile empire out of nothing just to see you bring me down.\n\nYou're going to help me get back to life. Find my ex-wife, Ajamon, on the north side of the Holdfast. Just follow your nose. She'll be wherever the stinky brewing cauldron is.", objectives = "" }
WordHunterWoW_QuestEN[25661] = { title = "With a Little Help...", description = "Fine, I be helpin' ya. He not gettin' outa payin' me alimony that easy! 'Sides, there be the baby he had with me sistah ta take care of!\n\nFirst thing we needin' is the innards of his closest friends. That'd be his cap'ns.\n\nGo down there an' pay the three of them a visit.", objectives = "" }
WordHunterWoW_QuestEN[25662] = { title = "Free Our Sisters", description = "Yesterday morning I dispatched a squadron of huntresses on a mission into Windshear Crag to obtain information about Horde operations in Stonetalon. Field intelligence reports that they have all been captured, including their squad leader, Huntress Illiona.\n\nHead east into Windshear Crag and slay the Krom'gar infantry that occupy the crag and take from them their keys to unlock the Horde cages holding our sisters.\n\nDo your best to locate Illiona once you've freed the huntresses.", objectives = "" }
WordHunterWoW_QuestEN[25663] = { title = "An Offering for Aviana", description = "Although the guardian of all winged creatures is no longer with us in body, I sometimes hear her voice in the whisper of swaying leaves.\n\n{name}, we ask much of you as you set out to preserve this mountain. Before going on, take a moment to reflect.\n\nTake this offering of nectar to Aviana's burial circle, a circle of stones just outside the main door of the shrine. Perhaps some time alone with Aviana's memory will help sharpen your focus.", objectives = "" }
WordHunterWoW_QuestEN[25664] = { title = "A Prayer and a Wing", description = "A winged visage? Could it be...?\n\n{name}, there's no time to waste. You may have been speaking to Aviana herself, trying to return to us.\n\nI'll need something from Aviana's past to reach out to her. High atop the ridge overlooking this shrine, you'll find a series of huge nests belonging to Blaithe, an ancient bird of prey that was once her consort. For ten thousand years he's been mad with grief.\n\nGo to one of his roosts, and use this call to summon him. Kill Blaithe and bring me one of his feathers.", objectives = "" }
WordHunterWoW_QuestEN[25665] = { title = "A Plea From Beyond", description = "<You can't make sense of the spirit's urgent plea, but maybe Choluna can decipher what's going on here.>\n\n<Speak with Choluna back inside the shrine!>", objectives = "" }
WordHunterWoW_QuestEN[25666] = { title = "Getting Your Hands Dirty", description = "Make no mistake, {race}, that is one clever shark. You don't survive down here as long as he has without a little extra smarts.\n\nWhat I'm saying is he won't be fooled so easily again. We're going to have to change our approach a bit.\n\nI won't bore you with the details just yet. For now, I need you to collect a bunch of the innards from these giant sea grubs.\n\nThink you can handle that?", objectives = "" }
WordHunterWoW_QuestEN[25667] = { title = "Culling the Wendigos", description = "The wendigos in the Grizzled Den to the southwest of town have long been a thorn in our side. They're never quite strong enough to threaten Kharanos directly, yet they prey on travelers, mountaineer patrols, and supply convoys.\n\nI'm going to be withdrawing my observers from the Grizzled Den because I need them on the troll front. Would you help my men finish culling the wendigo population? Without strength of numbers, they won't be able to attack us.", objectives = "" }
WordHunterWoW_QuestEN[25668] = { title = "Pilfered Supplies", description = "With the Frostmanes making trouble to our east, the wendigos have sensed our weakness and grown bolder in their raids. Only one of the four most recent supply wagons has made it here safely. The wendigos made off with the rest, stashing it in the Grizzled Den, a cave southwest of town. If you're willing to go down there and recover the stolen supplies, you would have the gratitude of all the townspeople and the mountaineers defending Kharanos.", objectives = "" }
WordHunterWoW_QuestEN[25669] = { title = "Rumble in the Lumber... Mill", description = "Prepare yourself, {name}! The Warlord comes! Kill him and take his key. Use the key to release me.\n\nShould we make it out of here, report the following to Lord Fallowmere at Windshear Hold:\n\nThe Horde has aborted their plans to destroy Windshear Hold due to the efforts of one of our heroes. They now plan to move the bomb to Battlescar Valley and drop it on our armies battling the Horde at that location.\n\nThey must be stopped!", objectives = "" }
WordHunterWoW_QuestEN[25670] = { title = "DUN-dun-DUN-dun-DUN-dun", description = "If ol' Gnaws had heels he'd be on 'em right now.\n\nFortunately for you, I think like a shark.\n\nGnaws is mad as all get out and we're gunna use that to our advantage.\n\nHere, I found this chain while out treasure-huntin'. Use it to tie off to that harpoon gun.\n\nWhen Gnaws sees ya he'll be consumed with rage - that's when we strike!\n\nYou try to finish him off and I'll sneak in there and grab the shiney.\n\nHurry, {class}, before he grows them teeth back!", objectives = "" }
WordHunterWoW_QuestEN[25671] = { title = "Thinning the Horde", description = "The Horde's numbers swell as reinforcements from Ashenvale and Azshara arrive. There is no diplomacy to be had with the beasts. This is Hellscream's Horde and Hellscream's Horde wants our blood! We will not sit idly by and allow them to take our land and kill our people. We must act!\n\nWe must thin the Horde! Consider it your daily responsibility.\n\nVenture forth into Stonetalon Mountains and slay as many of the Horde as you are able. Let them know that the Alliance will not surrender!", objectives = "" }
WordHunterWoW_QuestEN[25672] = { title = "Carcass Collection", description = "These organs be a good start, mon, but we still be needin' lotsa other tings. Normally, we'd be gettin' stuff from family now, but dats only me and my sistah's boy, and Tony ain't worth it!\n\nSo, we be substitutin' some stuff. Lotsa carcasses, in fact!\n\nDeep down in the Shimmering Deep, there's tons of dem from when the water came rushin' in. Killed all of dem creatures. Go down there and bring me up some.", objectives = "" }
WordHunterWoW_QuestEN[25673] = { title = "Just Ask Alice", description = "Mr. P is sick, mister. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. P alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. P's stuff back so he can teach those baddies in the Horde a lesson?", objectives = "" }
WordHunterWoW_QuestEN[25674] = { title = "Futile Pride", description = "This is actually an old orc city... one of the oldest on Azeroth.  That is, it was until the ogres pushed us out.\n\nToday's Horde refuses to be pushed over by ogres.  My troops and I took the town back by force, and the ogres who once lived here now work as my servants.  Now, our real work begins.\n\nYou look strong enough, but I'd like to see some proof.  Kill one of the ogres that still besiege us, and return to me.", objectives = "" }
WordHunterWoW_QuestEN[25675] = { title = "Ogre Combat", description = "I saw your handiwork down there, {race}.  How'd you like to hunt some more ogres?\n\nWe only enslaved the ones we could catch.  Most of the strongest ogres still brood in Dreadmaul Post, plotting our demise.  Our guards can handle the scattered ambushers, but we are not yet firmly entrenched, and will buckle quickly under a coordinated attack.\n\nGo south to Dreadmaul Post and send a message, {name}.  Slay the strongest before they get any ideas.", objectives = "" }
WordHunterWoW_QuestEN[25676] = { title = "Heartstrike", description = "We don't have any hope of taking the Nethergarde Mines from the Alliance... at least not yet.  Nethergarde is well-defended, and their supply routes are established and strong.  Our goal, then, is to damage their economy.  We can't take the mine by force, but with surgical strikes we can drastically reduce the mine's efficiency.\n\nI have men creating a distraction outside the mines.  Head east, sneak into the mines, and speak with Rofilian Dane for your assignment.", objectives = "" }
WordHunterWoW_QuestEN[25677] = { title = "It's All Mine", description = "All over this cavern you'll find unguarded piles of ore, just waiting to be tampered with.  Our first choice would be to steal the ore, obviously, but that requires mine carts, protection, and labor... three things we just don't have.  So instead, we're just going to ruin this little mining party with a little bit of highly corrosive solvent.\n\nTake this bottle - CAREFULLY - and pour it onto those heaps of ore.  'Cause if we can't have this ore, then neither can they.", objectives = "" }
WordHunterWoW_QuestEN[25678] = { title = "Pick Your Fate", description = "It costs the Alliance approximately fifty gold to train a miner, two hundred to train an engineer, and three hundred to train a foreman.  Every Alliance goon that we kill isn't just a military victory... it's a financial one.\n\nNow get down there and destroy their workers!", objectives = "" }
WordHunterWoW_QuestEN[25679] = { title = "Into the Mountain", description = "The next phase of operations takes place deeper within the mine.  Speak with Tak'arili for your next assignment.  Just follow the mine cart rails to the southeast, and follow the curve around.  You'll see him at the entrance to the mine's upper chamber.\n\nIt's been a pleasure doing business with you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25680] = { title = "That's Not Us", description = "First things first... it looks like we got ourselves a problem.  These miners down the pathway to the right have been runnin' around like a chickens without they heads on.  My best guess is that they dug too deep and found somethin' nasty... a demon, an elemental, or some kind o' tentacley beast.\n\nTak'arili don't like surprises.  Find out what the problem is and take care of it, then we get ourselves back on track.", objectives = "" }
WordHunterWoW_QuestEN[25681] = { title = "Some People Just Need Killing", description = "The tunnel ahead, headin' west, will take you straight to Chief Prospector Hondo's office.  He's the big cheese around here, and Tak'arili's heard tell that he's a darn fine miner.  That's why he's gotta die.\n\nThere's just one problem: the pathway is completely FILLED with those pesky Nethergarde flunkies.  That's why you gotta disguise yourself.  Hop inside this box here, and sneak down the pathway.  Hopefully you won't draw too much suspicion on your way to da killin'.", objectives = "" }
WordHunterWoW_QuestEN[25682] = { title = "Mission Complete", description = "We be done here, mon.  Only thing left to do is send a report to Okrilla.  You doin' anything right now?", objectives = "" }
WordHunterWoW_QuestEN[25683] = { title = "The Dreadmaul Furnace", description = "I meant what I said, {race}.  You helped me, now I'll pass on what I know.\n\nA demon hunter recently came through here, but only briefly.  He was headed south, speaking of demons.  Normally I'd have slain the night elf on sight, but he didn't seem to be Alliance scum, and anybody who kills demons is useful to me for the time being.\n\nYou should check in with Lynnore and Drazial, a pair of blood mages I sent down that way.  They've camped in the back of an ogre cave.", objectives = "" }
WordHunterWoW_QuestEN[25684] = { title = "Attune the Bloodstone", description = "I admit, we haven't picked the most... convenient of spots to perform our studies, especially for passing adventurers who wish to enter and leave at will.  Our agreement with the ogres is tenuous, and I'm afraid we can't convince them not to attack you when you draw near.\n\nHowever, I can allow you to attune yourself to our bloodstone teleporters.  Simply place your hands on the stone to my right, and you will be teleported outside of the cave.  Then use the stone outside to teleport back!", objectives = "" }
WordHunterWoW_QuestEN[25685] = { title = "The First Step", description = "To perform the ritual you've requested - and perhaps some more rituals in the near future - we're going to need blood.  The Blasted Lands are filled with every type of reagent we might need for our blood magic... it's just a matter of the correct combination.\n\n<Lynnore quickly confers with Drazial for a moment.>\n\nBasilisks and hyenas, even amounts.  And we're going to need plenty of it.  Head east, to the center of the Blasted Lands.  And don't forget... you can use that teleporter!", objectives = "" }
WordHunterWoW_QuestEN[25686] = { title = "Blood Ritual", description = "Our goal is to find the demon hunter, Loramus Thalipedes.  Let me know when you are ready to begin the blood ritual, and then stand back.", objectives = "" }
WordHunterWoW_QuestEN[25687] = { title = "Not Just Any Body", description = "Loramus Thalipedes is dead.  Well, let me step back... that's an assumption on my part, but I do know that his body lies in three pieces.\n\n<Lynnore ponders for a moment.>\n\nIf you bring me the pieces, we still have a recourse.  All three pieces are nearby... the Dreadmaul ogres hide them in their caves.  In fact, one of them is in that chest, down the ledge behind me...", objectives = "" }
WordHunterWoW_QuestEN[25688] = { title = "The Altar of Storms", description = "Up on the bluffs above our comfy cave is a powerful altar.  A powerful DEMONIC altar, guarded by cultists, but powerful nonetheless.  If you can reach it, you can use it to bring Loramus back to us.\n\nThe altar will likely resist your efforts, so you'll have to protect Loramus' body while the ritual completes.  Bring the demon hunter back to me afterwards.", objectives = "" }
WordHunterWoW_QuestEN[25689] = { title = "Time is Short", description = "I was hunting a demon named Razelikh, when his ogre lieutenant Grol assaulted me.  I was caught unaware, and I died... but so did Grol.\n\nRazelikh plans to return to the Blasted Lands and overwhelm the lands with his demons.  Even now, he is preparing to summon his legions to eliminate us.\n\n<The demon hunter quickly draws a rune in the air, then hands it to you.>\n\nDeliver this to Wazzik at the Dark Portal, to the southeast.  He will guide you.  Quickly!  We haven't much time!", objectives = "" }
WordHunterWoW_QuestEN[25690] = { title = "A Bloodmage's Gotta Eat Too", description = "Contrary to popular belief, blood elf bloodmages do NOT drink blood.  We eat normal food like everybody else - something which can be hard to come by in the recesses of an ogre stronghold.\n\nThe ashmane boars in the central valley of the Blasted Lands are, if nothing else, convenient for eating, as their meat does not require any cooking.  Would you hunt these boars and help us replenish our foodstores?", objectives = "" }
WordHunterWoW_QuestEN[25691] = { title = "The Charred Granite of the Dark Portal", description = "Loramus wants us - er, YOU - to gather granite chips from these chunks of rock around the Dark Portal.  I don't know what he'd want rocks for, but I have my suspicions, and they're not pleasant ones.\n\nUse this pick and look for small outcroppings of rock along the edge of the portal's blast radius.", objectives = "" }
WordHunterWoW_QuestEN[25692] = { title = "The Vile Blood of Demons", description = "Thalipedes wants demon blood.  Personally, the stuff doesn't even seem like blood to me - more like liquid rot - but that's neither here nor there.\n\nLuckily for you, the area around the Dark Portal is crawling with demons.  Infernals, felhounds, felguards... they've all got what you need, in copious, pustulent amounts.", objectives = "" }
WordHunterWoW_QuestEN[25693] = { title = "Enhancing the Stone", description = "<Wazzik finishes packing the materials up in a neatly-wrapped package.>\n\nThat's all that Loramus asked of us.  When you see him, make sure you let him know how much of a help I was.  I fear he will not see my hand in this.", objectives = "" }
WordHunterWoW_QuestEN[25694] = { title = "Protecting Our Rear", description = "The only reason you see me standing aside Alliance soldiers is because our duty outweighs our enmity... however slightly.  We have been charged with protecting the Dark Portal from unauthorized travel, and with the recent cataclysm, we are particularly susceptible to an attack.  We've already heard reports of black dragons in the area...\n\nWith my men focused on their duty, we need someone to keep the area demons in check.  Around the portal you will find three demon lieutenants.  Slay them.", objectives = "" }
WordHunterWoW_QuestEN[25695] = { title = "Watching Our Back", description = "<Warlord Dar'toon speaks in hushed tones.>\n\nI have orders from... higher up... that you would be suitable for.  I've seen the Alliance periodically referring to a stack of papers on that barrel over there.  I'd like you to take a look at those papers and find out what it is that they're plotting.  My duty and station prevent me from such a questionable task, but a newcomer like you might be able to slip in unnoticed...", objectives = "" }
WordHunterWoW_QuestEN[25696] = { title = "The Sunveil Excursion", description = "Oh, right, I received a notification from someone a few days ago.  The Reliquary, was it?  They're looking for someone to... do something...\n\n<The Warlord rifles through some papers.>\n\nAh, here it is!  Yes, Rohan Sunveil of The Reliquary is seeking able-bodied adventurers to assist with an archaeological expedition to the south.\n\nHere, take this with you.  Why don't you go speak with that elf?", objectives = "" }
WordHunterWoW_QuestEN[25697] = { title = "The Amulet of Allistarj", description = "When my master helped me to take my eyes out, he gave me the gift of sight... a sight much greater than yours, or even of these blood-craving elves.  My sight allows me to see objects of demonic power, such as the Amulet of Allistarj.\n\nAllistarj himself is dead, but he locked his amulet up in a trove inside the Serpent's Coil, to the east.  Along with the other amulets, this relic will give us access to Razelikh's perch.", objectives = "" }
WordHunterWoW_QuestEN[25698] = { title = "The Amulet of Sevine", description = "Sevine's amulet is in the hands of a murloc, far to the east, on a shelf that overlooks the Shattershore.  How it ended up in that murloc's possession, I cannot say, but I can state with certainty that you will find it there.\n\nI feel a stronger connection with Sevine than with the rest of Razelikh's servants... possibly because she built the Altar of Storms, upon which you resurrected me.  Bring her Amulet to Lynnore, along with the rest.", objectives = "" }
WordHunterWoW_QuestEN[25699] = { title = "The Amulet of Grol", description = "Grol... the ogre who tore me apart.\n\n<Loramus laughs.>\n\nIt would seem that Grol's body has changed hands several times since we died together, but it no longer rests with the ogres.  His body, along with his amulet of power, is in a wrecked ship off the Shattershore, to the east.  His amulet is the last... once combined, the three will give us access to Razelikh, and therein lies our chance to stop his madness.", objectives = "" }
WordHunterWoW_QuestEN[25700] = { title = "Loramus Thalipedes Awaits", description = "The enchantment on these amulets was not complex.  Together, their power will grant you access to Razelikh, the amulets' creator.\n\nI am prepared to perform the ritual on you and Loramus.  Speak with me when you are both ready.", objectives = "" }
WordHunterWoW_QuestEN[25701] = { title = "You Are Rakh'likh, Demon", description = "Hero, listen well.\n\nFirst, we must travel to the Deathly Usher, who waits at the northern foot of the Rise of the Defiler, to our northeast.  The usher will take us to the top of the rise.  Once there, I need you to help me defeat Razelikh, for I fear that I am not strong enough to defeat him alone.\n\nMost importantly, I need you to hold the stone knife, and do not use it until I tell you to.  The knife will trap Razelikh's soul within its new, eternal prison.\n\nIf we succeed, speak with Wazzik.", objectives = "" }
WordHunterWoW_QuestEN[25702] = { title = "Home... Gone... Naga...", description = "<The murloc struggles to speak your language.>\n\nRockpool... attacked.  Naga turn, take village, villagers.\n\nSalt-Flop escape, but others do not.  Go south, talk to Chief Neptool.  Maybe he survive.", objectives = "" }
WordHunterWoW_QuestEN[25703] = { title = "Atrocities", description = "<Though his lips do not move, you can feel the murloc chief speaking to you.>\n\nThe Bloodwash naga and the Rockpool murloc have lived among one another for as long as we could remember.  We have always had our differences, but never provoked one another.  Why, then, would they turn on us?\n\n<Neptool looks over his shoulder at his former villagers.>\n\nYou see what they do now?  They enslave us, sacrifice us, force us to fight one another.  I will stop them, {race}... and you will be my weapon.", objectives = "" }
WordHunterWoW_QuestEN[25704] = { title = "The Mad Magus", description = "There's only one ting left dat we can do. Ya gotta slay someone with the big mojo in Tony's presence.\n\nNo, not me!\n\nOl' Magus Tirth went crazy when he tried ta stop the waters rushin' in at the Cataclysm. Now he be hauntin' the area just south of the Holdfast.\n\nTake dis soul stick an' use it on his corpse, mon. Then bring Tony back an' we be gettin' him back in his body.\n\nYa can use me spirit portal ta get down there an' back.", objectives = "" }
WordHunterWoW_QuestEN[25705] = { title = "False Idols", description = "Neptulon the Tidehunter is our god.  He was the god of the Bloodwash, too, but they have turned their back on him, it seems.  They now choose to worship only Azshara, their naga queen.  You will see likenesses of Azshara littered around their settlements, carved out of seastone.\n\n<The murloc spirit eyes your weapon.>\n\nThat weapon will do.  Send it through their Azsh'ir idols.  They need to be reminded that our father Neptulon is the only one who truly rules the seas.", objectives = "" }
WordHunterWoW_QuestEN[25706] = { title = "Neptool's Revenge", description = "No number of naga deaths will bring back the Rockpool tribe, but any amount of revenge will help the spirits of my people rest more easily.\n\nMany of the more powerful Bloodwash have set up a fortress in the caverns to the northwest.  Slay them, in the name of the Rockpool.  The remaining Bloodwash have erected gladiatorial pools and Azsh'ir altars on our beach, where they pit my people against one another and worship their false god.  Slay them, in the name of the Tidehunter.", objectives = "" }
WordHunterWoW_QuestEN[25707] = { title = "The Future of the Rockpool", description = "The Rockpool tadpoles left upon this crate appear tired, scared, and nearly dried out.  They need to be taken to the water, and quickly.\n\nPerhaps if you can drag this crate across the beach and into the Forbidden Sea, far off the coast of the Red Reaches, then they will have a chance of escaping, and the Rockpool murlocs may live on...", objectives = "" }
WordHunterWoW_QuestEN[25708] = { title = "Our Fallen Friends", description = "Based on what you're telling me, it sounds like there aren't many survivors... just restless spirits.  The least we can do is give them their rest.\n\n<Enohar takes a long draw off of a mug of black ale.>\n\nHead back to the Shattershore and vanquish the worgen ghosts that still remain.  Doing so should release their spirit from this world and allow them to pass into the next.", objectives = "" }
WordHunterWoW_QuestEN[25709] = { title = "Curtail the Darktail", description = "The other thing that concerns me about those shipwrecks is all the vultures that they've attracted.  Knowing how those birds operate, they've already picked the bones clean, but still... we can't allow them to further desecrate the bodies of our friends.\n\nBefore I brewed, I hunted.  Here, take this bow, and more importantly, these arrows.  They've been laced with a little concoction that should give those bonepickers a surprise.", objectives = "" }
WordHunterWoW_QuestEN[25710] = { title = "Minor Distractions", description = "Nethergarde has stood steadfast for years against the demon onslaught that plagues this land.  Our watch is never-ending, our vigilance unfaltering, and our courage bottomless.\n\nWe have held these lands since the portal opened, but now these Horde insects have the insolence to stand in our way!?  We have protected THEM as well as we have protected ourselves!\n\n<Lungertz looks you over.>\n\nLet's see if you've got a hand for combat.  Slay one of the Horde's Okril'lon scouts that nibble at our perimeter.", objectives = "" }
WordHunterWoW_QuestEN[25711] = { title = "Eliminate the Okril'lon", description = "The Horde are a nuisance that we will deal with, but they are proving more difficult than previously expected.  You are to put a stop to this.\n\nTo the west of Nethergarde, the Okril'lon main forces press on our defenses.  They currently hold the Nethergarde Mines, and they mean to move into the supply camps and, eventually, the Keep.  Thin their numbers and delay their advance, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25712] = { title = "Nethergarde Reigns", description = "Lungertz is a strong leader, but he is proud.  He understates the pressure that the Horde is really putting on us.  Without our mine... Nethergarde is penniless.\n\nWe need to move the Horde forces from the supply camp NOW, and doing so means killing their commander, Captain Metlek.  He's not a strong leader, and prefers to bark orders from the back lines, but even so, his death might buy us the victory we need.", objectives = "" }
WordHunterWoW_QuestEN[25713] = { title = "Remove Their Arms", description = "Say there... {name}, is it?  I've got a proposition for you which involves explosions.  Interested?\n\nI couldn't help but overhear your conversation with the quartermaster.  You see... I've been working on an explosive device.  It's not very effective against other creatures, but devastating against artillery.  If you're heading back into the field to visit those orcs, find some enemy supplies and give this thing a try.  Who knows... maybe they like explosions too.", objectives = "" }
WordHunterWoW_QuestEN[25714] = { title = "Watcher Mahar Ba", description = "It's time for you to visit the Watcher.  He's been in a bit of a mood lately, and I'm not quite sure why.\n\nHead up to the top of the mage tower and check in with him.  I don't have any work for you here, but I'm certain that he will.", objectives = "" }
WordHunterWoW_QuestEN[25715] = { title = "A Closer Look", description = "We've seen countless ships sail past the shore to the southeast, but most pass by inconspicuously.  Several days ago, however, a powerful storm carried several of the ships to shore and left them wrecked.\n\nI'd bet a pint of Nethergarde Bitter that they were Horde ships if I didn't love Nethergarde Bitter so much.  I can pay you gold, though, if you'll go check out those ships and report back.", objectives = "" }
WordHunterWoW_QuestEN[25716] = { title = "Cultists at our Doorstep", description = "You may have already run into some of the Shadowsworn cultists that dwell in the caves just to the southwest of Nethergarde.  They do not impress an immediate danger upon our fortress, but I fear that they are planning something more dreadful than you can imagine.\n\nThe low-ranking members carry spell foci that might hold an answer.  Bring some back to me intact, if you can wrench them from the cultists' hands.", objectives = "" }
WordHunterWoW_QuestEN[25717] = { title = "The Demons and the Druid", description = "The Reliquary is focused on the acquisition and preservation of magical artifacts.  Our particular excursion is focused on the demonic artifacts that are hidden in what used to be the Tainted Scar.\n\nA worgen druid has taken residence in the scar and is coaxing a forest to grow.  He seems to be failing, however, as the area is still infested with demons.\n\nAnyhow, his forest stands in the way of our excursion, as do these demons.  Slay the tainted ones, then return to me so we might deal with the druid.", objectives = "" }
WordHunterWoW_QuestEN[25718] = { title = "How Best to Proceed", description = "Your demon-slaying down there bought our scouts enough time to get a good look at that druid.  My intelligence tells me that his name is Marl Wormthorn... a rogue Gilnean druid of substantial power.  He resides in Maldraz, the large, twisted tree at the center of the forest, and is protected from harm by some strange force.  Whether that force is of demonic or natural sources, we have yet to determine.\n\nSpeak with Elijah.  He may have some more information for you.", objectives = "" }
WordHunterWoW_QuestEN[25719] = { title = "Demoniac Vessel", description = "We need a way to get Wormthorn's attention.  Something to break him out of his trance.  Something that's guaranteed to work.\n\nThe few types of wildlife that managed to make a foothold in the Tainted Forest are, without a doubt, affected by the land's latent energies.  Your task is to collect their body parts and find a way to combine them into a vessel.  If Wormthorn's trance is druidic, or even if it is demonic, a large enough vessel of tainted animal flesh should be able to break it.", objectives = "" }
WordHunterWoW_QuestEN[25720] = { title = "The Downfall of Marl Wormthorn", description = "Wormthorn's unnatural forest threatens our excursion's progress.  His trees' roots break our picks, his moss grows over our excavation sites, and his animals attack my men.  When it comes to digging, I'll take a demon-infested wasteland over a forest any day.\n\nTake the demoniac vessel and use it on Marl Wormthorn to pull him from his trance.  Return to me when he is no more.", objectives = "" }
WordHunterWoW_QuestEN[25721] = { title = "Fight the Flood", description = "I'm here because Muradin himself knew that this survey needed someone to keep these buffoons on their toes. They're all too scared of the wildlife to do a thing! If I'm to get them off their duffs, I'm going to need some cleanup done.\n\nWe've got an elemental problem, first off. The flood did such a number here that the water itself's gone hysterical.\n\nI bet you've never slapped the sense into an entire lake before, but I'm askin' it of you now. Whallop those elementals but good for me.", objectives = "" }
WordHunterWoW_QuestEN[25722] = { title = "Sedimentary, My Dear", description = "The destruction of the Stonewrought Dam was no small thing, lad. We're here to find out just how bad the damage is. A mighty load of water's rampaged through here, and if it's disturbed the earth too far, we could be in for worse later on.\n\nWe can tell a lot from studying the sediment of the flooded area. I need as many soil samples as I can get, so if you could head out there and collect some more, I'd much appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[25723] = { title = "Thresh Out of Luck", description = "The local wildlife's all messed up from the flood, it seems. This fen used to be full of crocolisks, but I haven't spotted a single one.\n\nWhat I have spotted are threshadons. Never used to be any here, so the flood must've swept them all right out of Loch Modan.\n\nLucky for us, because they're tastier than crocolisks, and I'm running low on provisions. Bring me back some threshadon meat for the camp, and I'll gladly pay you for it.", objectives = "" }
WordHunterWoW_QuestEN[25724] = { title = "Frostmane Aggression", description = "The cataclysm has thrown the balance of power in Dun Morogh into question, {name}. Without warning, a wave of troggs emerged from the caves near Gnomeregan and overran the Frostmane trolls. The trolls have been migrating east ever since.\n\nThere has always been a Frostmane presence up on Shimmer Ridge, to the northwest, but with the migration, the trolls now surround us. We can't allow the trolls to use this position to their advantage. While my men hold the line in the east, strike against Shimmer Ridge.", objectives = "" }
WordHunterWoW_QuestEN[25725] = { title = "Fenbush Berries", description = "We're good on provisions, but we're in need of some medicine. Half the camp's fiercely hung over, and a remedy's in order.\n\nLuckily, I know a good folk remedy taught to me by my dear old mum. We just need some local ingredients.\n\nGather me some fenbush berries, if you would. They keep to where there's water and shade, so look along the shore and near other plants.", objectives = "" }
WordHunterWoW_QuestEN[25726] = { title = "A Dumpy Job", description = "Alright, I need you to help me find my dumpy level.\n\nWhat's that look for? That's right! I said my dumpy level! It's a piece of significant surveying equipment!\n\nI didn't name the bloody thing, alright? Go look it up! All I did was leave it on a rock long enough for one of those horrible oozes to swallow it up. The place is crawling with 'em, but one of them should still have it inside.", objectives = "" }
WordHunterWoW_QuestEN[25727] = { title = "Drungeld Glowerglare", description = "The Dark Iron clan is up to no good out here. And if that surprises you, you're thicker than the addled blotters over in that tent. Muradin may pay lip service to those sooty cretins back in Ironforge, but out here all bets are off.\n\nWe had a raid against the camp last night, and one raid is too many. Their leader's a stout fellow by the name of Glowerglare, and he's hiding in the cave on the south bank of the river.\n\nBring me Glowerglare's beard as proof he's no longer a threat to us and Ironforge.", objectives = "" }
WordHunterWoW_QuestEN[25728] = { title = "Mr. P's Wild Ride", description = "Now Mr. P just needs an angel to help him navigate. Will you be that angel, mister? With you helping we can go out into the crag and kill bunches and bunches of Horde! Waddya say? Come on, mister! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Horde, Mr. Fallowmere will buy us all ice cream!", objectives = "" }
WordHunterWoW_QuestEN[25729] = { title = "Gerenzo the Traitor", description = "<The Gnomecorder comes to life with a loud buzz.>\n\nCome in, {name}! Are you zhere? I have noted on ze map that you are near ze Cragpool Lake vater vheel, is that correct?\n\nIt vould appear that ze Venture Co. has holed up at ze vheel. Have a look around vhile you are up zhere. If you happen to zee a traitorous gnome by ze name of Gerenzo Wrenchwhistle, put your boot firmly up his keester for me and for Gnomeregan! I vill pay handsomely!", objectives = "" }
WordHunterWoW_QuestEN[25730] = { title = "BEWARE OF CRAGJAW!", description = "By order of people not wanting to get themselves devoured whole by a really huge fish, Cragpool Lake is OFF-LIMITS! Someone decided to up and put a huge, dwarf-eating fish in the lake.\n\nIt is strongly recommended that you stay out, however, if you are the heroic type and have a few friends around, do us all a favor and kill the damned thing! Maybe I can get some fishing done then, eh?\n\nIf you manage to actually do it, meet me back at Windshear Hold for a reward.\n\n-Ol' Irongoat", objectives = "" }
WordHunterWoW_QuestEN[25731] = { title = "A Bird in Hand", description = "It's time to get to the bottom of this. We need to interrogate the matron of these beasts, Marion Wormwing. We'll capture her alive. Here's the plan:\n\nThe harpies communicate across the ridge using a series of signal fires. If we extinguish one, Marion is sure to come investigate.\n\nYou fight her as a distraction while I sneak up behind and grab her. I'll leave the questioning to you. Let's get her, {name}! ", objectives = "" }
WordHunterWoW_QuestEN[25732] = { title = "A Bone to Pick", description = "We did it!\n\nGnaws is down, and I have our shiney!\n\nThat's good news.\n\nDarn shiney is cursed treasure - makes everyone who touches it a skeleton.\n\nThat's bad news.\n\nThese cursed pirates say the Gilblin King has the secret to remove the hex.\n\nThat's good news.\n\nI can't step foot outside the reef or I'll be cursed forever.\n\nThat's bad news.", objectives = "" }
WordHunterWoW_QuestEN[25733] = { title = "Get Out Of Here, Stalkers", description = "Thelgen Rock's an important site here. We need to use it to study the bedrock formations an' such.\n\nOf course, it can't be that easy, so Thelgen Rock's also full of giant cave stalkers. Big as a dwarf and twice as hungry. Like I said, these fancy-lads are researchers, not warriors, so if I want them to get anything done you're gonna have to help me clear the filthy bugs out.\n\nKill as many of the blighters as you can and I'll make it worth your while, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25734] = { title = "Down In Thelgen Rock", description = "I'm feeling slightly less wobbly now, so I'm going to start setting up the level for my final measurements here. There's one last thing I need from you.\n\nThere's a seismograph set up deep within Thelgen Rock to record any movements in the earth. If things have been continuing to shift since the cataclysm, this'll tell us.\n\nThe seismograph's at the very bottom of the cave; find it and bring the record it's created back to me.", objectives = "" }
WordHunterWoW_QuestEN[25735] = { title = "Incendicite Ore", description = "Thelgen Rock over yonder is something of a natural wonder. It's the only known source of incendicite in the world!\n\nThe stuff's rare, highly sought, and ridiculously explosive. Hit it with a steel mining pick and you'll set off a fireworks show that'll put a room full of goblins to shame.\n\nLuckily, I've developed a spark-proof pick for such tasks. I'll loan it to you if you bring me back some incendicite ore, and I'll split you in on the profits, of course.", objectives = "" }
WordHunterWoW_QuestEN[25736] = { title = "The Floodsurge Core", description = "This is all that's left of the huge elemental that attacked you: a frothing orb of water that continues to fight your grip.\n\nForba might appreciate seeing proof that you helped stop another threat to the camp.", objectives = "" }
WordHunterWoW_QuestEN[25737] = { title = "Tenuous Negotiations", description = "From what I've learned about these water-goblins, this should work.\n\nI've crafted a shark-tooth necklace from the items you scrounged up. Not only is it a shiny trinket, but it's a memento of Gnaws' death. There's no telling how many gilblins were eaten alive by that monster.\n\nOffer the necklace to the gilblin leader. In exchange, I need an artifact called The Pewter Pounder.\n\nAnd be quick about it, kid. I'm already beginning to miss my flesh...", objectives = "" }
WordHunterWoW_QuestEN[25738] = { title = "Shallow End of the Gene Pool", description = "<Gurboggle inspects the Gnaws Tooth Necklace for a moment.>\n\nNot bad, {race}, assuming it's the real thing. I'll hafta send one of my boys out to make sure your story checks out.\n\nIn the meantime, you're gunna do a little somethin' for me, see, 'cause this little trinket ain't worth givin' up The Pewter Pounder - not by a longshot!\n\nMy cousin, Gilblingle, has had his eye on my throne for years. Dumb as a bag of coral, that one - but still dangerous.\n\nYou take him out, and then we'll talk.", objectives = "" }
WordHunterWoW_QuestEN[25739] = { title = "If the Horde Don't Get You...", description = "<Captain Kosak coughs weakly.>\n\nWas traveling up Webwinder Path, coming from Northwatch Expedition Base Camp in the south. Ambushed. Not by Horde. Spiders. Big, ugly, hairy, nasty spiders.\n\nFought off dozens, maybe hundreds. Lost count. Overtaken by their queen. She took a chunk right out of me. Barely made it out alive. Might be dying.\n\nMore of my men coming. Must provide safe passage. Kill spider queen.\n\n<Captain Kosak passes out.>", objectives = "" }
WordHunterWoW_QuestEN[25740] = { title = "Fact-Finding Mission", description = "The dragon Sethria must be stopped. We know that her roost is south of here, along the southern cliffs of Hyjal, but beyond that we know little else.\n\nI have sent Thisalee on a fact-finding mission to Sethria's Roost. She specifically requested your help - evidently you made quite an impression with the young druid.\n\nMeet Thisalee just beyond the tunnel leading to Sethria's Roost. And remember, this is a fact-finding mission - don't do anything crazy!", objectives = "" }
WordHunterWoW_QuestEN[25741] = { title = "Preparations for the Future", description = "Poisoned travelers are becoming a common occurrence around Windshear Hold. Why just the other day a Northwatch Captain fell prey to the spiders of the Webwinder Hollow. He would have died to the poison had it not been for my anti-venom. Sadly my stock of anti-venom is almost completely depleted.\n\nIf you're heading south towards Webwinder Hollow, would you kindly recover Deepmoss venom sacs for me? You should be able to acquire them from Deepmoss spiders.", objectives = "" }
WordHunterWoW_QuestEN[25742] = { title = "What? This Old Thing?", description = "A deal's a deal.\n\nI present you - mysterious {race} stranger - with the one and only Pewter Pounder.\n\nYou may approach and receive this illustrious gift.\n\nThere, now, while it may look to be a simple hammer to the untrained eye, there are surely many hidden properties that will only manifest themselves when the appropriate situation arises.\n\nTake good care of this treasure, stranger. It has been in my royal possession for... well... days, now!", objectives = "" }
WordHunterWoW_QuestEN[25743] = { title = "Decisions, Decisions", description = "This is no magic solution to my curse! It's just a hammer!\n\nI may be crazy, but I'm not stupid.\n\nThere's NO WAY I'm gunna use this to break my shiney - not after all I've gone through to get it.\n\n<Budd pauses in thought for a moment.>\n\nBut that means I'm stuck down here for eternity...\n\nI had just learned to sail, you know.\n\nOhhh... I can't decide.\n\nHere, you take the hammer and I'll just set the shiney down and look the other way.", objectives = "" }
WordHunterWoW_QuestEN[25744] = { title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Crazzle Sprysprocket and Kravel Koalbeard northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[25745] = { title = "Negotiations", description = "{name}, great job defending the Speedbarge! I've got something else that I need you to help out with.\n\nI've sent Riznek and Trackmaster Zherin northeast to negotiate with the centaur survivors. Their Splithoof Heights is dripping with oil!\n\nI figure those smelly half horses won't know what they've got and we'll get the rights to pump up that black gold for a song, but I'd feel better if you took charge of the talks.\n\nWhat do you say?", objectives = "" }
WordHunterWoW_QuestEN[25746] = { title = "Sethria's Brood", description = "First order of business is to thin the herd here. This place crawls.\n\nLet's start slaughtering these dragonkin and worry about why they're here later.", objectives = "" }
WordHunterWoW_QuestEN[25747] = { title = "Looking Forward", description = "The Admiral used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", objectives = "" }
WordHunterWoW_QuestEN[25748] = { title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south?", objectives = "" }
